    organizationId: v.id('organizations'),
    employeeId: v.id('users'),
    reason: v.string(),
    category: v.union(
      v.literal('laptop'),
      v.literal('monitor'),
      v.literal('phone'),
      v.literal('peripheral'),
      v.literal('software'),
      v.literal('other'),
    ),
  },
