// HELPER FUNCTIONS
// ─────────────────────────────────────────────────────────────────────────────

function getAgeEmoji(age: number): string {
  if (age < 18) return '🧒';
  if (age < 30) return '🎓';
  if (age < 40) return '👨‍💼';
  if (age < 50) return '👨‍💼';
  if (age < 60) return '👴';
  return '👴';
}

function getAgeWord(age: number): string {
  const lastDigit = age % 10;
  const lastTwoDigits = age % 100;

  if (lastTwoDigits >= 11 && lastTwoDigits <= 19) {
    return 'лет';
  }

  if (lastDigit === 1) {
    return 'год';
  }

  if (lastDigit >= 2 && lastDigit <= 4) {
    return 'года';
  }

  return 'лет';
}

function getMonthName(month: number): string {
  const months = [
    'января',
    'февраля',
    'марта',
    'апреля',
    'мая',
    'июня',
    'июля',
    'августа',
    'сентября',
    'октября',
    'ноября',
    'декабря',
  ];
  return months[month - 1] ?? 'января';
}

/**
 * Scheduled job: проверять дни рождения каждое утро в 9:00
 * Настроить в Convex Dashboard: Functions → birthdays → scheduledBirthdayCheck
 * Schedule: 0 9 * * * (каждое утро в 9:00)
 */
export const scheduledBirthdayCheck = mutation({
  args: {
    organizationId: v.id('organizations'),
  },
  handler: async (ctx, args): Promise<any> => {
    const { organizationId } = args;
    // Проверить сегодня
    const today = await ctx.runMutation(api.birthdays.checkBirthdaysToday, {
      organizationId,
    });

    // Проверить предстоящие (через 3 дня для напоминания)
    const upcoming = await ctx.runMutation(api.birthdays.checkUpcomingBirthdays, {
      organizationId,
      daysAhead: 7,
    });

    return {
      today,
      upcoming,
    };
  },
});

