      organizationId: orgId,
      title: args.title,
      description: args.description,
      policyType: args.policyType,
      content: args.content,
      version: args.version,
      isActive: true,
      effectiveFrom: Date.now(),
      createdBy: user._id,
      updatedBy: user._id,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    });

    await ctx.db.insert('auditLogs', {
      organizationId: orgId,
      userId: user._id,
      action: 'policy_created',
