/** Get shift history for a driver */
export const getShiftHistory = query({
  args: {
    driverId: v.id('drivers'),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) throw new Error('Not authenticated');
    const { driverId, limit } = args;
    // Only the driver or an admin can view shift history
    const driverRecord = await ctx.db.get(driverId);
    if (
      !driverRecord ||
      (driverRecord.userId !== caller._id && caller.role !== 'admin' && !isSuperadmin(caller))
    ) {
      throw new Error('Only the driver or an admin can view shift history');
    }
    const shifts = await ctx.db
      .query('driverShifts')
      .withIndex('by_driver', (q) => q.eq('driverId', driverId))
      .order('desc')
      .take(limit || 50);

    return shifts.map((shift) => ({
      ...shift,
      duration: shift.endTime ? (shift.endTime - shift.startTime) / (1000 * 60 * 60) : null,
    }));
  },
});

/** Get shift statistics for organization */
export const getShiftStatistics = query({
  args: {
    organizationId: v.id('organizations'),
    period: v.union(v.literal('week'), v.literal('month'), v.literal('year')),
  },
  handler: async (ctx, args) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) return null;
    const { organizationId, period } = args;
    if (!isSuperadmin(caller) && caller.organizationId !== organizationId) {
      return null;
    }
    const now = Date.now();
    let periodStart: number;

    if (period === 'week') {
      periodStart = now - 7 * 24 * 60 * 60 * 1000;
    } else if (period === 'month') {
      periodStart = now - 30 * 24 * 60 * 60 * 1000;
    } else {
      periodStart = now - 365 * 24 * 60 * 60 * 1000;
    }

    const shifts = await ctx.db
      .query('driverShifts')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .filter((q) => q.gte(q.field('startTime'), periodStart))
      .take(MAX_PAGE_SIZE);

    const completedShifts = shifts.filter((s) => s.status === 'completed');

    const totalShifts = completedShifts.length;
    const totalHours = completedShifts.reduce((sum, s) => sum + (s.totalHours || 0), 0);
    const totalOvertime = completedShifts.reduce(
      (sum, s) => sum + (s.overtimeHours || 0),
      0,
    );
    const totalTrips = completedShifts.reduce(
      (sum, s) => sum + (s.tripsCompleted || 0),
      0,
    );
    const totalDistance = completedShifts.reduce(
      (sum, s) => sum + (s.totalDistance || 0),
      0,
    );

    const avgShiftDuration = totalShifts > 0 ? totalHours / totalShifts : 0;
    const avgTripsPerShift = totalShifts > 0 ? totalTrips / totalShifts : 0;

    return {
      totalShifts,
      totalHours,
      totalOvertime,
      totalTrips,
      totalDistanceKm: totalDistance,
      avgShiftDuration,
      avgTripsPerShift,
      activeShifts: shifts.filter((s) => s.status === 'active').length,
    };
  },
});

'use node';

import { action } from './_generated/server';
import { v } from 'convex/values';
import dns from 'dns';
import { promisify } from 'util';

const resolveMx = promisify(dns.resolveMx);

/**
 * Validates email: format check + DNS MX record verification
 */
export const validateEmail = action({
  args: { email: v.string() },
  handler: async (_ctx, { email }): Promise<{ valid: boolean; reason?: string }> => {
    const trimmed = email.trim().toLowerCase();

    // 1. Format check
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(trimmed)) {
      return { valid: false, reason: 'invalid_format' };
    }

    // 2. Extract domain
    const domain = trimmed.split('@')[1];
    if (!domain) {
      return { valid: false, reason: 'invalid_format' };
    }

    // 3. Block disposable/temporary email domains
    const disposableDomains = [
      'tempmail.com',
      'throwaway.email',
      'guerrillamail.com',
      'mailinator.com',
      'yopmail.com',
      'trashmail.com',
      'tempail.com',
      'fakeinbox.com',
      '10minutemail.com',
      'dispostable.com',
      'sharklasers.com',
      'guerrillamailblock.com',
    ];
    if (disposableDomains.includes(domain)) {
      return { valid: false, reason: 'disposable_email' };
    }

    // 4. DNS MX record check
    try {
      const mxRecords = await resolveMx(domain);
      if (!mxRecords || mxRecords.length === 0) {
        return { valid: false, reason: 'no_mx_records' };
      }
      return { valid: true };
    } catch (err: any) {
      // ENOTFOUND = domain doesn't exist, ENODATA = no MX records
      if (err.code === 'ENOTFOUND' || err.code === 'ENODATA') {
        return { valid: false, reason: 'domain_not_found' };
      }
      // Network error — allow through (don't block on temporary failures)
      return { valid: true };
    }
  },
});

