// ═══════════════════════════════════════════════════════════════════════════
// EMPLOYEE UPSERT — the write half of a sync
// ═══════════════════════════════════════════════════════════════════════════

const incomingEmployeeValidator = v.object({
  email: v.string(),
  name: v.string(),
  department: v.optional(v.string()),
  position: v.optional(v.string()),
  phone: v.optional(v.string()),
  location: v.optional(v.string()),
  employeeType: v.optional(v.union(v.literal('staff'), v.literal('contractor'))),
  isActive: v.optional(v.boolean()),
  externalId: v.optional(v.string()),
});

/**
 * Create or update employees pulled from a provider.
 *
 * Guard rails:
 *  - never creates or modifies privileged roles (admin/supervisor/superadmin);
 *  - scoped to the organization by email, so an address belonging to another
 *    tenant is skipped rather than hijacked;
 *  - respects the organization's seat limit, same as manual employee creation.
 */
export const upsertEmployeeBatch = internalMutation({
  args: {
    organizationId: v.id('organizations'),
    provider: providerValidator,
    employees: v.array(incomingEmployeeValidator),
  },
  handler: async (ctx, { organizationId, provider, employees }) => {
    const org = await ctx.db.get(organizationId);
    if (!org) throw new Error('Organization not found');

    let created = 0;
    let updated = 0;
    let skipped = 0;
    const notes: string[] = [];

    // Seat accounting is done once per batch, then tracked locally as we insert.
    const activeUsers = await ctx.db
      .query('users')
      .withIndex('by_org_active', (q) =>
        q.eq('organizationId', organizationId).eq('isActive', true),
      )
      .take(DEFAULT_LIST_CAP);
    let seatsUsed = activeUsers.length;

    for (const incoming of employees) {
      const email = incoming.email.toLowerCase().trim();
      if (!email || !email.includes('@')) {
        skipped++;
        notes.push(`invalid email: ${incoming.email.slice(0, 40)}`);
        continue;
      }

      // Scope the lookup to this org so we can detect a cross-tenant collision.
      const inOrg = await ctx.db
        .query('users')
        .withIndex('by_org_email', (q) => q.eq('organizationId', organizationId).eq('email', email))
        .first();

      if (inOrg) {
        if (PRIVILEGED_ROLES.has(inOrg.role)) {
          skipped++;
          notes.push(`${email}: privileged role not managed by sync`);
          continue;
        }
        const patch: Record<string, unknown> = {
          name: incoming.name || inOrg.name,
          updatedAt: Date.now(),
        };
        // Only overwrite what the provider actually sent.
        if (incoming.department !== undefined) patch.department = incoming.department;
        if (incoming.position !== undefined) patch.position = incoming.position;
        if (incoming.phone !== undefined) patch.phone = incoming.phone;
        if (incoming.location !== undefined) patch.location = incoming.location;
        if (incoming.employeeType !== undefined) patch.employeeType = incoming.employeeType;
        if (incoming.isActive !== undefined) {
          // Re-activating consumes a seat.
          if (incoming.isActive && !inOrg.isActive && seatsUsed >= org.employeeLimit) {
            skipped++;
            notes.push(`${email}: seat limit reached`);
            continue;
          }
          if (incoming.isActive && !inOrg.isActive) seatsUsed++;
          if (!incoming.isActive && inOrg.isActive) seatsUsed--;
          patch.isActive = incoming.isActive;
        }
        await ctx.db.patch(inOrg._id, patch);
        updated++;
        continue;
      }

      // Email owned by a different organization — never move or overwrite it.
      const elsewhere = await ctx.db
        .query('users')
        .withIndex('by_email', (q) => q.eq('email', email))
        .first();
      if (elsewhere) {
        skipped++;
        notes.push(`${email}: belongs to another organization`);
        continue;
      }

      if (seatsUsed >= org.employeeLimit) {
        skipped++;
        notes.push(`${email}: seat limit reached (${org.employeeLimit})`);
        continue;
      }

      const employeeType = incoming.employeeType ?? 'staff';
      const isStaff = employeeType === 'staff';
      const now = Date.now();

      await ctx.db.insert('users', {
        organizationId,
        name: incoming.name || email,
        email,
        // No usable password — the account is claimed via the reset-password flow.
        passwordHash: '',
        role: 'employee',
        employeeType,
        department: incoming.department,
        position: incoming.position,
        phone: incoming.phone,
        location: incoming.location,
        isActive: incoming.isActive ?? true,
        isApproved: true,
        travelAllowance: isStaff ? 20000 : 12000,
        paidLeaveBalance: 20,
        sickLeaveBalance: 10,
        familyLeaveBalance: 5,
        dayOffBalance: 6,
        maternityLeaveBalance: 0,
        studyLeaveBalance: 5,
        createdAt: now,
      });
      if (incoming.isActive ?? true) seatsUsed++;
      created++;
    }

    void provider;
    return { created, updated, skipped, notes };
  },
});

/**
 * Deactivate synced employees the provider no longer lists. Opt-in via the
 * `deactivateMissing` config flag — off by default because a truncated or
 * partial provider response would otherwise lock people out.
 */
export const deactivateMissingEmployees = internalMutation({
  args: {
    organizationId: v.id('organizations'),
    activeEmails: v.array(v.string()),
  },
  handler: async (ctx, { organizationId, activeEmails }) => {
    const keep = new Set(activeEmails.map((e) => e.toLowerCase().trim()));

    const orgUsers = await ctx.db
      .query('users')
      .withIndex('by_org_active', (q) =>
        q.eq('organizationId', organizationId).eq('isActive', true),
      )
      .take(DEFAULT_LIST_CAP);

    let deactivated = 0;
    for (const user of orgUsers) {
      if (PRIVILEGED_ROLES.has(user.role)) continue;
      if (keep.has(user.email.toLowerCase())) continue;
      await ctx.db.patch(user._id, { isActive: false, updatedAt: Date.now() });
      deactivated++;
    }
    return { deactivated };
  },
});

// ═══════════════════════════════════════════════════════════════════════════
// PROVIDER RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

/** Read a possibly-nested value by dot path, e.g. "data.items". */
function readPath(source: unknown, path: string): unknown {
  return path.split('.').reduce<unknown>((acc, key) => {
    if (acc && typeof acc === 'object') return (acc as Record<string, unknown>)[key];
    return undefined;
  }, source);
}

/** Keys providers commonly wrap a collection in, tried in order. */
const LIST_KEY_CANDIDATES = [
  'data',
  'items',
  'employees',
  'results',
  'records',
  'users',
  'value',
  'data.items',
  'data.employees',
  'result.items',
];

/**
 * Pull the employee array out of a provider response. An explicit
 * `employeesListKey` wins; otherwise probe the shapes we've seen in the wild.
 */
export function extractList(payload: unknown, listKey?: string): unknown[] {
  if (listKey) {
    const picked = readPath(payload, listKey);
    if (!Array.isArray(picked)) {
      throw new Error(`Response has no array at "${listKey}"`);
    }
    return picked;
  }
  if (Array.isArray(payload)) return payload;
  for (const candidate of LIST_KEY_CANDIDATES) {
    const picked = readPath(payload, candidate);
    if (Array.isArray(picked)) return picked;
  }
  throw new Error(
    'Could not find an employee array in the response — set "Employees list key" to the field holding it',
  );
}

/** Provider field names we try for each of our fields, in priority order. */
const DEFAULT_FIELD_CANDIDATES: Record<string, string[]> = {
  email: ['email', 'work_email', 'workEmail', 'mail', 'emailAddress', 'email_address', 'userEmail'],
  name: ['name', 'full_name', 'fullName', 'displayName', 'display_name'],
  firstName: ['first_name', 'firstName', 'givenName', 'given_name'],
  lastName: ['last_name', 'lastName', 'surname', 'familyName', 'family_name'],
  department: ['department', 'department_name', 'departmentName', 'dept', 'division'],
  position: ['position', 'title', 'job_title', 'jobTitle', 'role_name', 'positionName'],
  phone: ['phone', 'phone_number', 'phoneNumber', 'mobile', 'telephone'],
  location: ['location', 'office', 'city', 'site'],
  employeeType: ['employee_type', 'employeeType', 'employment_type', 'contract_type'],
  isActive: ['is_active', 'isActive', 'active', 'enabled'],
  externalId: ['id', 'employee_id', 'employeeId', 'external_id', 'externalId', 'uuid'],
};

function pick(record: Record<string, unknown>, ourField: string, map: Record<string, string>) {
  // An explicit mapping is authoritative — no fallback guessing behind it.
  const mapped = map[ourField];
  if (mapped) return readPath(record, mapped);
  for (const candidate of DEFAULT_FIELD_CANDIDATES[ourField] ?? []) {
    const value = record[candidate];
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return undefined;
}

function asString(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value === 'string') return value.trim() || undefined;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return undefined;
}

function asBoolean(value: unknown): boolean | undefined {
  if (value === undefined || value === null || value === '') return undefined;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const v = value.toLowerCase().trim();
    if (['true', '1', 'yes', 'y', 'active', 'enabled'].includes(v)) return true;
    if (['false', '0', 'no', 'n', 'inactive', 'disabled', 'terminated'].includes(v)) return false;
  }
  return undefined;
}

export type NormalizedEmployee = {
  email: string;
  name: string;
  department?: string;
  position?: string;
  phone?: string;
  location?: string;
  employeeType?: 'staff' | 'contractor';
  isActive?: boolean;
  externalId?: string;
};

/**
 * Convert provider records into our employee shape. Records without a usable
 * email are dropped and counted — email is the identity key for the upsert.
 */
export function normalizeEmployees(
  rows: unknown[],
  fieldMapJson?: string,
): { employees: NormalizedEmployee[]; dropped: number } {
  let map: Record<string, string> = {};
  if (fieldMapJson) {
    try {
      const parsed = JSON.parse(fieldMapJson);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        map = parsed as Record<string, string>;
      }
    } catch {
      throw new Error('Field mapping is not valid JSON');
    }
  }

  const employees: NormalizedEmployee[] = [];
  let dropped = 0;

  for (const row of rows) {
    if (!row || typeof row !== 'object') {
      dropped++;
      continue;
    }
    const record = row as Record<string, unknown>;

    const email = asString(pick(record, 'email', map))?.toLowerCase();
    if (!email || !email.includes('@')) {
      dropped++;
      continue;
    }

    let name = asString(pick(record, 'name', map));
    if (!name) {
      const first = asString(pick(record, 'firstName', map));
      const last = asString(pick(record, 'lastName', map));
      name = [first, last].filter(Boolean).join(' ') || undefined;
    }

    const rawType = asString(pick(record, 'employeeType', map))?.toLowerCase();
    const employeeType =
      rawType === undefined
        ? undefined
        : /contract|freelanc|vendor|temp/.test(rawType)
          ? ('contractor' as const)
          : ('staff' as const);

    employees.push({
      email,
      name: name ?? email,
      department: asString(pick(record, 'department', map)),
      position: asString(pick(record, 'position', map)),
      phone: asString(pick(record, 'phone', map)),
      location: asString(pick(record, 'location', map)),
      employeeType,
      isActive: asBoolean(pick(record, 'isActive', map)),
      externalId: asString(pick(record, 'externalId', map)),
    });
  }

  // Last record wins on duplicate emails, keeping the batch idempotent.
  const byEmail = new Map<string, NormalizedEmployee>();
  for (const e of employees) byEmail.set(e.email, e);

  return { employees: [...byEmail.values()], dropped };
}

// ═══════════════════════════════════════════════════════════════════════════
// HTTP HELPERS
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Third-party error bodies can echo back the credentials we sent, and they land
 * in sync logs shown in the UI. Truncate and strip anything secret-looking.
 */
function safeErrorBody(body: string, config: any): string {
  let out = body.slice(0, 300);
  for (const field of SECRET_FIELDS) {
    const secret = config?.[field];
    if (typeof secret === 'string' && secret.length >= 6) {
      out = out.split(secret).join(SECRET_MASK);
    }
  }
  if (typeof config?.imidAccessToken === 'string' && config.imidAccessToken.length >= 6) {
    out = out.split(config.imidAccessToken).join(SECRET_MASK);
  }
  return out;
}

/**
 * Base64 of a UTF-8 string, for HTTP Basic credentials.
 *
 * `btoa` alone throws on any code point above U+00FF, so an Armenian username
 * or password — entirely normal for an Armenian ERP — would fail the sync
 * before a request was ever made. RFC 7617 §2.1 lets the client pick the
 * charset and names UTF-8 as the one to prefer, so encode to UTF-8 bytes first
 * and hand `btoa` the latin1 view it actually accepts.
 */
function basicAuthHeader(username: string, password: string): string {
  const bytes = new TextEncoder().encode(`${username}:${password}`);
  let latin1 = '';
  for (const byte of bytes) latin1 += String.fromCharCode(byte);
  return `Basic ${btoa(latin1)}`;
}

/** Join a base URL and path without doubling or dropping the separator. */
function joinUrl(base: string, path: string): string {
  const b = base.replace(/\/+$/, '');
  const p = path.startsWith('/') ? path : `/${path}`;
  return `${b}${p}`;
}

/** Reject non-HTTPS and obviously internal targets — configs are admin-supplied. */
function assertSafeUrl(raw: string, label: string): string {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new Error(`${label}: "${raw.slice(0, 60)}" is not a valid URL`);
  }
  if (url.protocol !== 'https:') {
    throw new Error(`${label}: only https:// endpoints are allowed`);
  }
  const host = url.hostname.toLowerCase();
  const isPrivate =
    host === 'localhost' ||
    host === '::1' ||
    host.endsWith('.localhost') ||
    host.endsWith('.internal') ||
    /^127\./.test(host) ||
    /^10\./.test(host) ||
    /^192\.168\./.test(host) ||
    /^169\.254\./.test(host) ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(host);
  if (isPrivate) {
    throw new Error(`${label}: private and loopback hosts are not allowed`);
  }
  return url.toString();
}

/** A provider call that fails or stalls must not hang the whole sync. */
async function fetchJson(
  url: string,
  init: RequestInit,
  label: string,
  config: any,
): Promise<unknown> {
  let response: Response;
  try {
    response = await fetch(url, {
      ...init,
      signal: AbortSignal.timeout(20_000),
    });
  } catch (e: any) {
    const reason = e?.name === 'TimeoutError' ? 'request timed out' : 'network error';
    throw new Error(`${label}: ${reason}`);
  }

  if (!response.ok) {
    const body = await response.text().catch(() => '');
    throw new Error(`${label} API error (${response.status}): ${safeErrorBody(body, config)}`);
  }

  const text = await response.text();
  if (!text.trim()) {
    throw new Error(`${label}: empty response body`);
  }
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`${label}: response was not JSON — ${safeErrorBody(text, config)}`);
  }
}

/**
 * Call an OAuth 2.0 token endpoint.
 *
 * RFC 6749 §4.1.3 mandates `application/x-www-form-urlencoded` for token
 * requests, so that is what we send first. Some providers only accept JSON,
 * so a 400/415 response — the two statuses a server uses to reject a body it
 * cannot parse — triggers one retry with a JSON body. Any other failure is
 * a genuine error (bad credentials, wrong URL) and propagates immediately.
 */
async function fetchTokenEndpoint(
  url: string,
  params: Record<string, string>,
  label: string,
  config: any,
): Promise<Record<string, unknown>> {
  try {
    return (await fetchJson(
      url,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Accept: 'application/json',
        },
        body: new URLSearchParams(params).toString(),
      },
      label,
      config,
    )) as Record<string, unknown>;
  } catch (e: any) {
    const message = String(e?.message ?? '');
    // Only retry when the server rejected the *encoding*, not the credentials.
    if (!/\((400|415)\)/.test(message)) throw e;

    return (await fetchJson(
      url,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify(params),
      },
      label,
      config,
    )) as Record<string, unknown>;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// SYNC ORCHESTRATION
// ═══════════════════════════════════════════════════════════════════════════

type SyncOutcome = {
  message: string;
  created: number;
  updated: number;
  deactivated: number;
  skipped: number;
  details?: string;
  /** True when the provider is connected but importing is switched off. */
  skippedSync?: boolean;
};

async function performSync(
  ctx: any,
  organizationId: Id<'organizations'>,
  provider: Provider,
  config: any,
): Promise<SyncOutcome> {
  switch (provider) {
    case 'lucky_carrot':
      return syncLuckyCarrot(ctx, organizationId, config);
    case 'imid':
      return syncImid(ctx, organizationId, config);
    case 'armsoft':
      return syncArmsoft(ctx, organizationId, config);
    default:
      throw new Error(`Unknown provider: ${provider}`);
  }
}

/**
 * Fetch → normalize → upsert, shared by every provider that imports people.
 */
async function importEmployees(
  ctx: any,
  organizationId: Id<'organizations'>,
  provider: Provider,
  config: any,
  url: string,
  headers: Record<string, string>,
  label: string,
): Promise<SyncOutcome> {
  const payload = await fetchJson(url, { method: 'GET', headers }, label, config);

  const rows = extractList(payload, config.employeesListKey);
  if (rows.length > MAX_IMPORT_RECORDS) {
    throw new Error(
      `${label}: response contained ${rows.length} records, above the ${MAX_IMPORT_RECORDS} per-run limit. Narrow the query or paginate.`,
    );
  }

  const { employees, dropped } = normalizeEmployees(rows, config.fieldMap);
  if (employees.length === 0) {
    throw new Error(
      `${label}: fetched ${rows.length} record(s) but none had a usable email — check the field mapping`,
    );
  }

  let created = 0;
  let updated = 0;
  let skipped = dropped;
  const notes: string[] = [];

  for (let i = 0; i < employees.length; i += UPSERT_BATCH_SIZE) {
    const batch = employees.slice(i, i + UPSERT_BATCH_SIZE);
    const res = await ctx.runMutation(internal.integrations.upsertEmployeeBatch, {
      organizationId,
      provider,
      employees: batch,
    });
    created += res.created;
    updated += res.updated;
    skipped += res.skipped;
    notes.push(...res.notes);
  }

  let deactivated = 0;
  if (config.deactivateMissing) {
    const res = await ctx.runMutation(internal.integrations.deactivateMissingEmployees, {
      organizationId,
      // Only people the provider says are active should stay active here.
      activeEmails: employees.filter((e) => e.isActive !== false).map((e) => e.email),
    });
    deactivated = res.deactivated;
  }

  const message = `${label}: ${created} created, ${updated} updated, ${deactivated} deactivated, ${skipped} skipped`;
  return {
    message,
    created,
    updated,
    deactivated,
    skipped,
    details: notes.length ? JSON.stringify(notes.slice(0, 50)) : undefined,
  };
}

// ── Lucky Carrot Sync ──────────────────────────────────────────────────────
async function syncLuckyCarrot(
  ctx: any,
  organizationId: Id<'organizations'>,
  config: any,
): Promise<SyncOutcome> {
  if (!config.apiKey || !config.apiUrl) {
    throw new Error('Lucky Carrot: API key and URL required');
  }
  if (config.autoSyncEmployees === false) {
    return {
      message: 'Lucky Carrot: credentials verified, employee import is switched off',
      created: 0,
      updated: 0,
      deactivated: 0,
      skipped: 0,
      skippedSync: true,
    };
  }

  const base = assertSafeUrl(config.apiUrl, 'Lucky Carrot API URL');
  const url = assertSafeUrl(
    joinUrl(base, config.employeesPath || '/api/v1/employees'),
    'Lucky Carrot employees URL',
  );

  return importEmployees(
    ctx,
    organizationId,
    'lucky_carrot',
    config,
    url,
    {
      Authorization: `Bearer ${config.apiKey}`,
      Accept: 'application/json',
    },
    'Lucky Carrot',
  );
}

// ═══════════════════════════════════════════════════════════════════════════
// LUCKY CARROT INBOUND WEBHOOK
// ═══════════════════════════════════════════════════════════════════════════

/** Header carrying the hex HMAC-SHA256 of `<timestamp>.<body>`. */
export const WEBHOOK_SIGNATURE_HEADER = 'x-luckycarrot-signature';
/** Header carrying the unix-seconds timestamp that is signed alongside the body. */
export const WEBHOOK_TIMESTAMP_HEADER = 'x-luckycarrot-timestamp';

/** Deliveries older than this are rejected, so a captured request cannot be replayed. */
const WEBHOOK_MAX_SKEW_MS = 5 * 60 * 1000;

/** Refuse oversized bodies before spending CPU on HMAC or JSON parsing. */
export const WEBHOOK_MAX_BODY_BYTES = 1_000_000;

/** Outcome of an inbound delivery; the HTTP layer maps this to a status code. */
type WebhookOutcome =
  | { status: 'unauthorized' }
  | { status: 'disabled' }
  | { status: 'invalid'; message: string }
  | { status: 'ok'; message: string; created: number; updated: number; skipped: number };

/**
 * Compare two hex digests without leaking where they diverge. A `===` here would
 * finish early on the first differing character, which is a timing oracle an
 * attacker can walk one nibble at a time to forge a signature.
 */
function timingSafeEqualHex(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

function toHex(buffer: ArrayBuffer): string {
  return Array.from(new Uint8Array(buffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/** HMAC-SHA256 over `<timestamp>.<body>`, hex-encoded. */
async function signWebhookPayload(
  secret: string,
  timestamp: string,
  body: string,
): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const mac = await crypto.subtle.sign(
    'HMAC',
    key,
    new TextEncoder().encode(`${timestamp}.${body}`),
  );
  return toHex(mac);
}

/** Internal: normalize an organization id from a raw string (for use in actions). */
export const normalizeOrganizationId = internalQuery({
  args: { organizationIdRaw: v.string() },
  handler: async (ctx, { organizationIdRaw }) => {
    return ctx.db.normalizeId('organizations', organizationIdRaw);
  },
});

/**
 * A webhook may carry a whole directory or a single employee event. `extractList`
 * covers the collection shapes; fall back to the common single-record envelopes
 * so a "employee.updated" push does not need a separate code path.
 */
function extractWebhookRecords(payload: unknown, listKey?: string): unknown[] {
  try {
    return extractList(payload, listKey);
  } catch (listError) {
    if (payload && typeof payload === 'object') {
      const envelope = payload as Record<string, unknown>;
      for (const key of ['employee', 'user', 'data', 'record', 'object']) {
        const candidate = envelope[key];
        if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) {
          return [candidate];
        }
      }
      // A bare employee object posted at the top level.
      if (!Array.isArray(payload)) return [payload];
    }
    throw listError;
  }
}

/**
 * Credentials needed to authenticate an inbound delivery. Takes the org id as a
 * raw string because it arrives from the URL — `normalizeId` both validates it
 * and rejects ids belonging to another table.
 */
export const getWebhookAuth = internalQuery({
  args: { organizationIdRaw: v.string() },
  handler: async (ctx, { organizationIdRaw }) => {
    const organizationId = ctx.db.normalizeId('organizations', organizationIdRaw);
    if (!organizationId) return null;

    const doc = await ctx.db
      .query('integrationConfigs')
      .withIndex('by_org_provider', (q) =>
        q.eq('organizationId', organizationId).eq('provider', 'lucky_carrot'),
      )
      .first();
    if (!doc?.config.webhookSecret) return null;

    return {
      organizationId,
      secret: doc.config.webhookSecret,
      // Enablement is reported rather than enforced here: the caller checks the
      // signature first, so a legitimate sender gets a clear "disabled" answer
      // while an unauthenticated one learns nothing.
      isEnabled: doc.config.isEnabled === true && doc.config.webhookEnabled === true,
      employeesListKey: doc.config.employeesListKey,
      fieldMap: doc.config.fieldMap,
    };
  },
});

/** Record that a delivery landed, so the UI can show webhook freshness. */
export const markWebhookReceived = internalMutation({
  args: { organizationId: v.id('organizations') },
  handler: async (ctx, { organizationId }) => {
    const existing = await ctx.db
      .query('integrationConfigs')
      .withIndex('by_org_provider', (q) =>
        q.eq('organizationId', organizationId).eq('provider', 'lucky_carrot'),
      )
      .first();
    if (!existing) return;

    await ctx.db.patch(existing._id, {
      config: { ...existing.config, lastWebhookAt: Date.now() },
      updatedAt: Date.now(),
    });
  },
});

/**
 * Authenticate and apply one inbound Lucky Carrot delivery.
 *
 * Kept out of the HTTP handler so the signing secret never enters the routing
 * layer, and so the whole path is unit-testable without a live request.
 *
 * Unlike a scheduled sync this never deactivates anyone: a webhook payload is
 * usually a single event or a partial page, and treating "absent from this push"
 * as "no longer employed" would lock out the whole organization.
 */
export const ingestLuckyCarrotWebhook = internalAction({
  args: {
    organizationIdRaw: v.string(),
    body: v.string(),
    signature: v.string(),
    timestamp: v.string(),
  },
  handler: async (ctx, args): Promise<WebhookOutcome> => {
    const { organizationIdRaw, body, signature, timestamp } = args;

    if (!signature || !timestamp) return { status: 'unauthorized' };

    const auth: {
      organizationId: Id<'organizations'>;
      secret: string;
      isEnabled: boolean;
      employeesListKey?: string;
      fieldMap?: string;
    } | null = await ctx.runQuery(internal.integrations.getWebhookAuth, { organizationIdRaw });
    // An unknown org, an unconfigured provider and a bad signature are all
    // reported identically — otherwise this endpoint enumerates organizations.
    if (!auth) return { status: 'unauthorized' };

    const sentAt = Number(timestamp);
    if (!Number.isFinite(sentAt)) return { status: 'unauthorized' };
    // Seconds and milliseconds are both accepted; senders differ.
    const sentAtMs = sentAt > 1e11 ? sentAt : sentAt * 1000;
    if (Math.abs(Date.now() - sentAtMs) > WEBHOOK_MAX_SKEW_MS) {
      return { status: 'unauthorized' };
    }

    const expected = await signWebhookPayload(auth.secret, timestamp, body);
    if (!timingSafeEqualHex(signature.trim().toLowerCase(), expected)) {
      return { status: 'unauthorized' };
    }

    // Past this line the sender is proven authentic, so it is safe to give it
    // specific feedback — and to write to the sync log without letting an
    // anonymous caller flood the table.
    if (!auth.isEnabled) return { status: 'disabled' };

    let payload: unknown;
    try {
      payload = JSON.parse(body);
    } catch {
      return { status: 'invalid', message: 'Body was not valid JSON' };
    }

    let records: unknown[];
    try {
      records = extractWebhookRecords(payload, auth.employeesListKey);
    } catch (error: any) {
      return {
        status: 'invalid',
        message: error?.message ? String(error.message) : 'Unrecognized payload shape',
      };
    }

    if (records.length > MAX_IMPORT_RECORDS) {
      return {
        status: 'invalid',
        message: `Delivery contained ${records.length} records, above the ${MAX_IMPORT_RECORDS} per-request limit`,
      };
    }

    let normalized;
    try {
      normalized = normalizeEmployees(records, auth.fieldMap);
    } catch (error: any) {
      return {
        status: 'invalid',
        message: error?.message ? String(error.message) : 'Could not read the payload',
      };
    }

    const { employees, dropped } = normalized;
    if (employees.length === 0) {
      return {
        status: 'invalid',
        message: `Received ${records.length} record(s) but none had a usable email — check the field mapping`,
      };
    }

    let created = 0;
    let updated = 0;
    let skipped = dropped;
    const notes: string[] = [];

    for (let i = 0; i < employees.length; i += UPSERT_BATCH_SIZE) {
      const res = await ctx.runMutation(internal.integrations.upsertEmployeeBatch, {
        organizationId: auth.organizationId,
        provider: 'lucky_carrot' as const,
        employees: employees.slice(i, i + UPSERT_BATCH_SIZE),
      });
      created += res.created;
      updated += res.updated;
      skipped += res.skipped;
      notes.push(...res.notes);
    }

    const message = `Lucky Carrot webhook: ${created} created, ${updated} updated, ${skipped} skipped`;

    await ctx.runMutation(internal.integrations.logSync, {
      organizationId: auth.organizationId,
      provider: 'lucky_carrot' as const,
      action: 'webhook',
      status: 'success',
      message,
      created,
      updated,
      deactivated: 0,
      skipped,
      details: notes.length ? JSON.stringify(notes.slice(0, 50)) : undefined,
    });

    await ctx.runMutation(internal.integrations.markWebhookReceived, {
      organizationId: auth.organizationId,
    });

    return { status: 'ok', message, created, updated, skipped };
  },
});

/**
 * Mint a new webhook signing secret and return it once.
 *
 * Rotating invalidates the previous secret immediately, so the value must be
 * copied into Lucky Carrot before the next delivery. It is deliberately absent
 * from every read path (see SERVER_ONLY_FIELDS) — this mutation's return value
 * is the only time it is ever transmitted.
 */
export const rotateWebhookSecret = mutation({
  args: { organizationId: v.id('organizations') },
  handler: async (ctx, { organizationId }) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) throw new Error('Not authenticated');
    if (!canAdminOrg(caller, organizationId)) {
      throw new Error('Only admins of this organization can manage webhooks');
    }

    const existing = await ctx.db
      .query('integrationConfigs')
      .withIndex('by_org_provider', (q) =>
        q.eq('organizationId', organizationId).eq('provider', 'lucky_carrot'),
      )
      .first();
    if (!existing) {
      throw new Error('Save the Lucky Carrot configuration before generating a webhook secret');
    }

    // 256 bits of entropy, hex-encoded — the same shape the HMAC key expects.
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    const secret = Array.from(bytes)
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('');

    const now = Date.now();
    await ctx.db.patch(existing._id, {
      config: { ...existing.config, webhookSecret: secret },
      updatedAt: now,
    });

    await ctx.db.insert('auditLogs', {
      organizationId,
      userId: caller._id,
      action: 'integration_lucky_carrot_webhook_secret_rotated',
      target: 'lucky_carrot',
      details: JSON.stringify({ rotated: true }),
      createdAt: now,
    });

    return { secret };
  },
});

// ── imID Sync ──────────────────────────────────────────────────────────────
/**
 * imID is an identity provider, not an HR system: there is no employee
 * directory to pull. A sync therefore validates the OAuth client-credentials
 * grant and caches the resulting token for signing/verification calls.
 */
async function syncImid(
  ctx: any,
  organizationId: Id<'organizations'>,
  config: any,
): Promise<SyncOutcome> {
  if (!config.clientId || !config.clientSecret) {
    throw new Error('imID: Client ID and Client Secret required');
  }
  if (config.enableLogin && !config.redirectUri) {
    throw new Error('imID: Redirect URI is required when login with imID is enabled');
  }
  if (config.redirectUri) {
    assertSafeUrl(config.redirectUri, 'imID Redirect URI');
  }

  const tokenUrl = assertSafeUrl(
    config.tokenPath || 'https://api.imid.am/v1/oauth/token',
    'imID token URL',
  );

  const payload = await fetchTokenEndpoint(
    tokenUrl,
    {
      client_id: config.clientId,
      client_secret: config.clientSecret,
      grant_type: 'client_credentials',
    },
    'imID auth',
    config,
  );

  const accessToken =
    asString(payload.access_token) ?? asString(payload.accessToken) ?? asString(payload.token);
  if (!accessToken) {
    throw new Error('imID: auth succeeded but no access_token was returned');
  }

  const expiresInRaw = payload.expires_in ?? payload.expiresIn;
  const expiresIn = typeof expiresInRaw === 'number' ? expiresInRaw : 3600;
  // Expire a minute early so a token is never used on the edge of validity.
  const expiresAt = Date.now() + Math.max(60, expiresIn - 60) * 1000;

  await ctx.runMutation(internal.integrations.cacheImidToken, {
    organizationId,
    accessToken,
    expiresAt,
  });

  const enabled = [
    config.enableLogin ? 'login' : null,
    config.enableSigning ? 'e-signature' : null,
    config.enableVerification ? 'verification' : null,
  ].filter(Boolean);

  return {
    message: `imID: authenticated, token cached until ${new Date(expiresAt).toISOString()}${
      enabled.length ? ` (enabled: ${enabled.join(', ')})` : ' (no features enabled yet)'
    }`,
    created: 0,
    updated: 0,
    deactivated: 0,
    skipped: 0,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// imID OAUTH LOGIN FLOW
// ═══════════════════════════════════════════════════════════════════════════

/** Default imID OAuth endpoints — used when no path override is saved. */
const IMID_AUTHORIZE_DEFAULT = 'https://api.imid.am/v1/oauth/authorize';
const IMID_USERINFO_DEFAULT = 'https://api.imid.am/v1/oauth/userinfo';
const IMID_SIGNING_DEFAULT = 'https://api.imid.am/v1/sign';

/** Result of an imID employee verification request. */
type ImidVerifyResult =
  | { verified: boolean; method: 'sub' }
  | { verified: false; method: 'phone'; requestId?: string; message: string };

/** Result of an imID login callback; returned via the HTTP handler redirect. */
type ImidLoginResult =
  | { status: 'error'; message: string }
  | {
      status: 'ok';
      sessionToken: string;
      sessionExpiry: number;
      userId: Id<'users'>;
      isNewUser: boolean;
      needsApproval: boolean;
    };

/**
 * Generate the authorize URL for the imID OAuth login flow.
 *
 * The frontend calls this query, then redirects the browser to the returned URL.
 * After authentication, imID redirects to the callback endpoint with an
 * authorization code that `imidLoginCallback` exchanges for a session.
 */
export const imidGetAuthorizationUrl = mutation({
  args: { organizationId: v.id('organizations') },
  handler: async (ctx, { organizationId }) => {
    // Public mutation — called from the login page before the user is authenticated.
    // Must be a mutation because it writes the OAuth state to the config.
    // CSRF protection is provided by the OAuth state parameter.
    const config = await ctx.db
      .query('integrationConfigs')
      .withIndex('by_org_provider', (q) =>
        q.eq('organizationId', organizationId).eq('provider', 'imid'),
      )
      .first();

    if (!config || !config.config.isEnabled || !config.config.enableLogin) {
      throw new Error('imID login is not enabled for this organization');
    }
    if (!config.config.clientId || !config.config.redirectUri) {
      throw new Error('imID: Client ID and Redirect URI must be configured');
    }

    const authorizeUrl = assertSafeUrl(
      config.config.authorizePath || IMID_AUTHORIZE_DEFAULT,
      'imID authorize URL',
    );

    // Generate a secure random state parameter to prevent CSRF.
    const stateBytes = new Uint8Array(32);
    crypto.getRandomValues(stateBytes);
    const state = Array.from(stateBytes)
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('');

    // Persist the state so the callback can validate it.
    await ctx.db.patch(config._id, {
      config: { ...config.config, oauthState: state },
    });

    const params = new URLSearchParams({
      client_id: config.config.clientId,
      redirect_uri: config.config.redirectUri,
      response_type: 'code',
      scope: 'openid profile email',
      state,
    });

    return { url: `${authorizeUrl}?${params.toString()}`, state };
  },
});

/**
 * Exchange an OAuth authorization code for an access token from imID.
 * Used by `imidLoginCallback` to complete the OAuth flow.
 */
export const imidExchangeCode = internalAction({
  args: {
    organizationId: v.id('organizations'),
    code: v.string(),
    redirectUri: v.string(),
  },
  handler: async (ctx, { organizationId, code, redirectUri }) => {
    const config = await ctx.runQuery(internal.integrations.getIntegrationConfigInternal, {
      organizationId,
      provider: 'imid',
    });
    if (!config) throw new Error('imID config not found');

    const tokenUrl = assertSafeUrl(
      config.config.tokenPath || 'https://api.imid.am/v1/oauth/token',
      'imID token URL',
    );

    const { clientId, clientSecret } = config.config;
    if (!clientId || !clientSecret) {
      throw new Error('imID: Client ID and Client Secret must be configured');
    }

    const payload = await fetchTokenEndpoint(
      tokenUrl,
      {
        client_id: clientId,
        client_secret: clientSecret,
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
      },
      'imID token exchange',
      config.config,
    );

    const accessToken =
      asString(payload.access_token) ?? asString(payload.accessToken) ?? asString(payload.token);
    if (!accessToken) {
      throw new Error('imID: token exchange succeeded but no access_token was returned');
    }

    const idToken = asString(payload.id_token);

    return { accessToken, idToken, raw: payload };
  },
});

/**
 * Fetch user info from the imID userinfo endpoint using the access token.
 * Returns the user's email, name, and any other available claims.
 */
export const imidGetUserInfo = internalAction({
  args: {
    organizationId: v.id('organizations'),
    accessToken: v.string(),
  },
  handler: async (ctx, { organizationId, accessToken }) => {
    const config = await ctx.runQuery(internal.integrations.getIntegrationConfigInternal, {
      organizationId,
      provider: 'imid',
    });
    if (!config) throw new Error('imID config not found');

    const userInfoUrl = assertSafeUrl(
      config.config.userInfoPath || IMID_USERINFO_DEFAULT,
      'imID userinfo URL',
    );

    const payload = (await fetchJson(
      userInfoUrl,
      {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          Accept: 'application/json',
        },
      },
      'imID userinfo',
      config.config,
    )) as Record<string, unknown>;

    const email =
      asString(payload.email) ??
      asString(payload.preferred_username) ??
      asString(payload.sub) ??
      '';
    const nameRaw = asString(payload.name);
    const given = asString(payload.given_name);
    const family = asString(payload.family_name);
    const name = nameRaw || [given, family].filter(Boolean).join(' ') || 'User';
    const sub = asString(payload.sub) ?? email;
    const phone = asString(payload.phone_number) ?? asString(payload.phone);

    if (!email) {
      throw new Error('imID: userinfo did not return an email');
    }

    return {
      sub,
      email: email.toLowerCase(),
      name,
      phone,
      raw: payload,
    };
  },
});

/**
 * Clear the one-time OAuth state from the imID integration config.
 * Extracted into a mutation because `imidLoginCallback` is an internal action
 * and has no direct `ctx.db`.
 */
export const clearImidOauthState = internalMutation({
  args: { configId: v.id('integrationConfigs') },
  handler: async (ctx, { configId }) => {
    const doc = await ctx.db.get(configId);
    if (!doc) return;
    const cleaned: Record<string, unknown> = { ...doc.config };
    delete cleaned.oauthState;
    await ctx.db.patch(configId, { config: cleaned as Doc<'integrationConfigs'>['config'] });
  },
});

/**
 * Full OAuth login callback — exchange code, fetch user, create/login.
 * Called from the HTTP handler after imID redirects the user back.
 *
 * Returns a signed session token the HTTP handler bakes into the redirect
 * cookie, so the user lands in the app already authenticated.
 */
export const imidLoginCallback = internalAction({
  args: {
    organizationId: v.id('organizations'),
    code: v.string(),
    state: v.string(),
  },
  // Annotated explicitly: the handler calls ctx.runAction through
  // internal.integrations which creates a circular reference — without the
  // annotation TS cannot break the inference cycle.
  handler: async (ctx, { organizationId, code, state }): Promise<ImidLoginResult> => {
    const config = await ctx.runQuery(internal.integrations.getIntegrationConfigInternal, {
      organizationId,
      provider: 'imid',
    });
    if (!config) {
      return { status: 'error', message: 'imID configuration not found' } as const;
    }

    // Validate state (CSRF protection).
    if (config.config.oauthState && config.config.oauthState !== state) {
      return {
        status: 'error',
        message: 'Invalid state parameter — possible CSRF attack',
      } as const;
    }

    // Clear the state regardless of outcome (one-time use).
    await ctx.runMutation(internal.integrations.clearImidOauthState, { configId: config._id });

    const redirectUri = config.config.redirectUri || '';
    if (!redirectUri) {
      return { status: 'error', message: 'Redirect URI not configured' } as const;
    }

    // Exchange the authorization code for an access token.
    let tokenResult: { accessToken: string; idToken?: string | null };
    try {
      tokenResult = await ctx.runAction(internal.integrations.imidExchangeCode, {
        organizationId,
        code,
        redirectUri,
      });
    } catch (error: any) {
      return {
        status: 'error',
        message: error?.message ? String(error.message) : 'Token exchange failed',
      } as const;
    }

    // Fetch user info from imID.
    let userInfo: { sub: string; email: string; name: string; phone?: string };
    try {
      userInfo = await ctx.runAction(internal.integrations.imidGetUserInfo, {
        organizationId,
        accessToken: tokenResult.accessToken,
      });
    } catch (error: any) {
      return {
        status: 'error',
        message: error?.message ? String(error.message) : 'Failed to fetch user info',
      } as const;
    }

    // Create or log in the user via the auth module.
    try {
      const sessionToken = crypto.randomUUID();
      const sessionExpiry = Date.now() + 7 * 24 * 60 * 60 * 1000; // 7 days

      const result = await ctx.runMutation(internal.integrations.imidUpsertUser, {
        organizationId,
        email: userInfo.email,
        name: userInfo.name,
        phone: userInfo.phone,
        imidSub: userInfo.sub,
        sessionToken,
        sessionExpiry,
      });

      return {
        status: 'ok',
        sessionToken,
        sessionExpiry,
        userId: result.userId,
        isNewUser: result.isNewUser,
        needsApproval: result.needsApproval,
      } as const;
    } catch (error: any) {
      return {
        status: 'error',
        message: error?.message ? String(error.message) : 'Failed to create session',
      } as const;
    }
  },
});

/**
 * Upsert a user logging in via imID OAuth.
 *
 * If the user's email exists in this org → log them in.
 * If not → create a new user (pending approval unless first in org).
 */
export const imidUpsertUser = internalMutation({
  args: {
    organizationId: v.id('organizations'),
    email: v.string(),
    name: v.string(),
    phone: v.optional(v.string()),
    imidSub: v.string(),
    sessionToken: v.string(),
    sessionExpiry: v.number(),
  },
  handler: async (ctx, args) => {
    const { organizationId, email, name, phone, imidSub, sessionToken, sessionExpiry } = args;
    const normalizedEmail = email.toLowerCase().trim();

    // Look up the user by email within this org.
    const existing = await ctx.db
      .query('users')
      .withIndex('by_org_email', (q) =>
        q.eq('organizationId', organizationId).eq('email', normalizedEmail),
      )
      .first();

    if (existing) {
      if (!existing.isActive) {
        throw new Error('Your account has been deactivated. Contact your administrator.');
      }
      if (!existing.isApproved) {
        throw new Error('Your account is pending approval.');
      }

      // Update session and imID subject id.
      await ctx.db.patch(existing._id, {
        sessionToken,
        sessionExpiry,
        lastLoginAt: Date.now(),
        imidSub,
      });

      return { userId: existing._id, isNewUser: false, needsApproval: false };
    }

    // New user — check org limits and create.
    const org = await ctx.db.get(organizationId);
    if (!org || !org.isActive) throw new Error('Organization is inactive');

    const activeUsers = await ctx.db
      .query('users')
      .withIndex('by_org_active', (q) =>
        q.eq('organizationId', organizationId).eq('isActive', true),
      )
      .take(DEFAULT_LIST_CAP);

    if (activeUsers.length >= org.employeeLimit) {
      throw new Error('Organization has reached its employee limit');
    }

    const isFirstMember = activeUsers.length === 0;
    const role = isFirstMember ? 'admin' : 'employee';
    const isApproved = isFirstMember;

    const userId = await ctx.db.insert('users', {
      organizationId,
      name: name || normalizedEmail.split('@')[0] || 'User',
      email: normalizedEmail,
      passwordHash: '', // OAuth-only user
      phone,
      role,
      employeeType: 'staff',
      isActive: true,
      isApproved,
      approvedAt: isApproved ? Date.now() : undefined,
      imidSub,
      sessionToken: isApproved ? sessionToken : undefined,
      sessionExpiry: isApproved ? sessionExpiry : undefined,
      lastLoginAt: isApproved ? Date.now() : undefined,
      travelAllowance: 20000,
      paidLeaveBalance: 24,
      sickLeaveBalance: 10,
      familyLeaveBalance: 5,
      dayOffBalance: 6,
      maternityLeaveBalance: 0,
      studyLeaveBalance: 5,
      createdAt: Date.now(),
    });

    if (!isApproved) {
      // Notify admins.
      const admins = await ctx.db
        .query('users')
        .withIndex('by_org_role', (q) => q.eq('organizationId', organizationId).eq('role', 'admin'))
        .take(20);

      for (const admin of admins) {
        await ctx.db.insert('notifications', {
          organizationId,
          userId: admin._id,
          type: 'join_request',
          title: '🙋 New imID Sign-Up',
          message: `${name} (${normalizedEmail}) signed up with imID and wants to join ${org.name || 'organization'}.`,
          isRead: false,
          relatedId: userId,
          route: '/organization',
          createdAt: Date.now(),
        });
      }
    }

    return { userId, isNewUser: true, needsApproval: !isApproved };
  },
});

// ═══════════════════════════════════════════════════════════════════════════
// imID SIGN — e-signature via imID Sign API
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Initiate a signing request via the imID Sign API.
 *
 * Uses the cached access token from `syncImid` to authenticate.
 * If the token has expired, the caller should re-sync first.
 *
 * @param documentId — the internal signature document to be signed.
 * @param signerPhone — the phone number of the person who should sign.
 * @param documentTitle — a human-readable title shown in the imID app.
 * @param documentContent — the content/PDF to be signed (base64 or text).
 */
export const imidInitiateSigning = action({
  args: {
    organizationId: v.id('organizations'),
    documentId: v.id('signatureDocuments'),
    signerPhone: v.string(),
    documentTitle: v.string(),
    documentContent: v.string(),
    callbackUrl: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const caller = await ctx.runQuery(internal.integrations.assertCanSync, {
      organizationId: args.organizationId,
    });
    if (!caller) throw new Error('Not authorized');

    const config = await ctx.runQuery(internal.integrations.getIntegrationConfigInternal, {
      organizationId: args.organizationId,
      provider: 'imid',
    });
    if (!config || !config.config.isEnabled || !config.config.enableSigning) {
      throw new Error('imID Sign is not enabled for this organization');
    }

    const accessToken = config.config.imidAccessToken;
    if (!accessToken) {
      throw new Error('imID: no cached access token — run Sync first');
    }
    if (config.config.imidTokenExpiresAt && config.config.imidTokenExpiresAt < Date.now()) {
      throw new Error('imID: cached token has expired — run Sync to refresh');
    }

    const signingUrl = assertSafeUrl(
      config.config.signingPath || IMID_SIGNING_DEFAULT,
      'imID Sign URL',
    );

    const body = {
      phone: args.signerPhone,
      title: args.documentTitle,
      content: args.documentContent,
      callback_url: args.callbackUrl || `${process.env.CONVEX_SITE_URL || ''}/webhooks/imid/sign`,
      document_id: args.documentId,
    };

    const payload = (await fetchJson(
      signingUrl,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify(body),
      },
      'imID Sign',
      config.config,
    )) as Record<string, unknown>;

    const signingId =
      asString(payload.signing_id) ?? asString(payload.id) ?? asString(payload.request_id);

    await ctx.runMutation(internal.integrations.logSync, {
      organizationId: args.organizationId,
      provider: 'imid',
      action: 'sign_initiated',
      status: 'success',
      message: `imID Sign initiated for ${args.signerPhone}: ${args.documentTitle}`,
    });

    return {
      success: true,
      signingId,
      message: `Signing request sent to ${args.signerPhone}`,
    };
  },
});

/**
 * Webhook handler for imID Sign callbacks.
 * Called by imID when a user has completed or declined a signing request.
 */
export const ingestImidSignCallback = internalAction({
  args: {
    organizationIdRaw: v.string(),
    body: v.string(),
  },
  handler: async (ctx, { organizationIdRaw, body }) => {
    const organizationId = await ctx.runQuery(internal.integrations.normalizeOrganizationId, {
      organizationIdRaw,
    });
    if (!organizationId) {
      return { status: 'invalid', message: 'Unknown organization' } as const;
    }

    let payload: Record<string, unknown>;
    try {
      payload = JSON.parse(body) as Record<string, unknown>;
    } catch {
      return { status: 'invalid', message: 'Body was not valid JSON' } as const;
    }

    const signingStatus = asString(payload.status) ?? asString(payload.event) ?? '';
    const documentId = asString(payload.document_id) ?? asString(payload.documentId) ?? '';

    if (signingStatus === 'completed' || signingStatus === 'signed') {
      // Mark the internal signature request as completed.
      if (documentId && documentId.startsWith('signature')) {
        try {
          await ctx.runMutation(internal.integrations.markImidSignComplete, {
            documentId: documentId as any,
          });
        } catch {
          // Document may not exist — log and continue.
        }
      }

      await ctx.runMutation(internal.integrations.logSync, {
        organizationId,
        provider: 'imid',
        action: 'sign_completed',
        status: 'success',
        message: `imID Sign completed for document ${documentId}`,
      });

      return { status: 'ok', message: 'Signing completed' } as const;
    }

    if (signingStatus === 'declined' || signingStatus === 'rejected') {
      await ctx.runMutation(internal.integrations.logSync, {
        organizationId,
        provider: 'imid',
        action: 'sign_declined',
        status: 'success',
        message: `imID Sign declined for document ${documentId}`,
      });

      return { status: 'ok', message: 'Signing declined' } as const;
    }

    return { status: 'ok', message: 'Unrecognized status, acknowledged' } as const;
  },
});

/** Mark an internal signature request as completed by imID Sign webhook. */
export const markImidSignComplete = internalMutation({
  args: { documentId: v.id('signatureDocuments') },
  handler: async (ctx, { documentId }) => {
    const doc = await ctx.db.get(documentId);
    if (!doc || doc.status === 'completed') return;

    await ctx.db.patch(documentId, {
      status: 'completed',
      completedAt: Date.now(),
    });

    await ctx.db.insert('signatureAuditLog', {
      documentId,
      organizationId: doc.organizationId,
      userId: doc.createdBy,
      action: 'signed',
      metadata: JSON.stringify({ source: 'imid_sign', timestamp: Date.now() }),
      timestamp: Date.now(),
    });
  },
});

// ═══════════════════════════════════════════════════════════════════════════
// imID VERIFICATION — employee identity verification
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Verify an employee's identity through imID.
 *
 * Uses the cached access token and expects the user's imID subject ID (sub)
 * to have been stored on the user record during OAuth login. If the user has
 * never logged in via imID, a phone-based verification can be used instead.
 */
export const imidVerifyEmployee = action({
  args: {
    organizationId: v.id('organizations'),
    userId: v.id('users'),
    /** Used when the user has no imID sub — send verification to their phone. */
    phone: v.optional(v.string()),
  },
  // Annotated explicitly: the handler reaches into `internal.integrations` for
  // authorization and verification, creating a circular reference that TS
  // cannot break without an explicit return type annotation.
  handler: async (ctx, args): Promise<ImidVerifyResult> => {
    const caller = await ctx.runQuery(internal.integrations.assertCanSync, {
      organizationId: args.organizationId,
    });
    if (!caller) throw new Error('Not authorized');

    const config = await ctx.runQuery(internal.integrations.getIntegrationConfigInternal, {
      organizationId: args.organizationId,
      provider: 'imid',
    });
    if (!config || !config.config.isEnabled || !config.config.enableVerification) {
      throw new Error('imID Verification is not enabled for this organization');
    }

    const accessToken = config.config.imidAccessToken;
    if (!accessToken) {
      throw new Error('imID: no cached access token — run Sync first');
    }
    if (config.config.imidTokenExpiresAt && config.config.imidTokenExpiresAt < Date.now()) {
      throw new Error('imID: cached token has expired — run Sync to refresh');
    }

    const user = await ctx.runQuery(internal.integrations.getUserForVerification, {
      userId: args.userId,
    });
    if (!user) throw new Error('User not found');

    // Try subject-based verification first (user logged in via imID before).
    if (user.imidSub) {
      const verifyUrl = assertSafeUrl(
        config.config.userInfoPath || IMID_USERINFO_DEFAULT,
        'imID verify URL',
      );

      const payload = (await fetchJson(
        verifyUrl,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${accessToken}`,
            Accept: 'application/json',
          },
        },
        'imID verification',
        config.config,
      )) as Record<string, unknown>;

      const verified =
        asString(payload.sub) === user.imidSub ||
        asString(payload.email)?.toLowerCase() === user.email.toLowerCase();

      await ctx.runMutation(internal.integrations.logSync, {
        organizationId: args.organizationId,
        provider: 'imid',
        action: 'verification',
        status: verified ? 'success' : 'error',
        message: verified
          ? `Verified ${user.name} (${user.email}) via imID`
          : `Verification failed for ${user.email}`,
      });

      return { verified, method: 'sub' };
    }

    // Fallback: phone-based verification request.
    if (args.phone) {
      const verifyUrl = assertSafeUrl(
        config.config.signingPath || IMID_SIGNING_DEFAULT,
        'imID verify URL',
      );

      const payload = (await fetchJson(
        `${verifyUrl}/verify`,
        {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${accessToken}`,
            'Content-Type': 'application/json',
            Accept: 'application/json',
          },
          body: JSON.stringify({
            phone: args.phone,
            purpose: 'employee_verification',
            callback_url: `${process.env.CONVEX_SITE_URL || ''}/webhooks/imid/verify`,
          }),
        },
        'imID phone verification',
        config.config,
      )) as Record<string, unknown>;

      const requestId = asString(payload.request_id) ?? asString(payload.id);

      return {
        verified: false,
        method: 'phone',
        requestId,
        message: `Verification request sent to ${args.phone}`,
      };
    }

    throw new Error('imID: cannot verify — user has no imID subject and no phone was provided');
  },
});

/**
 * Resolve an organization id from an OAuth state parameter.
 *
 * Scans all imID integration configs for a matching `oauthState`.
 * This is an action instead of a query because httpActions cannot call queries
 * with arbitrary args — but they can call actions. The action delegates to an
 * internal query internally.
 */
export const imidResolveOrgByState = internalAction({
  args: { state: v.string() },
  // Annotated explicitly: the handler queries internal.integrations which
  // creates a circular reference — without the annotation TS cannot break
  // the inference cycle.
  handler: async (ctx, { state }): Promise<{ organizationId: Id<'organizations'> } | null> => {
    // We need to scan configs, so use the internal list query.
    const configs = await ctx.runQuery(internal.integrations.listAllImidConfigs, {});
    for (const cfg of configs) {
      if (cfg.oauthState === state) {
        return { organizationId: cfg.organizationId };
      }
    }
    return null;
  },
});

/**
 * List organizations that have imID login enabled.
 * Used by the login page to show the "Login with imID" button.
 * Returns org id, name, slug so the frontend can display a picker if needed.
 */
export const imidListEnabledOrgs = query({
  args: {},
  handler: async (ctx) => {
    const docs = await ctx.db
      .query('integrationConfigs')
      .withIndex('by_provider_enabled', (q) =>
        q.eq('provider', 'imid').eq('config.isEnabled', true),
      )
      .take(50);

    const enabled = docs.filter(/* has login enabled */ (d) => d.config.enableLogin === true);
    if (enabled.length === 0) return [];

    // Resolve org names.
    const orgs = await Promise.all(
      enabled.map(async (d) => {
        const org = await ctx.db.get(d.organizationId);
        if (!org || !org.isActive) return null;
        return {
          id: d.organizationId,
          name: org.name,
          slug: org.slug,
          hasLogin: d.config.enableLogin === true,
        };
      }),
    );

    return orgs.filter(Boolean);
  },
});

/**
 * Process an inbound imID verify webhook callback.
 *
 * Called from the HTTP handler because `httpAction` has no direct `ctx.db`.
 * Validates the organization, parses the webhook body, and logs the
 * verification result.
 */
export const ingestImidVerifyCallback = internalAction({
  args: {
    organizationIdRaw: v.string(),
    body: v.string(),
  },
  handler: async (ctx, { organizationIdRaw, body }) => {
    const organizationId = await ctx.runQuery(internal.integrations.normalizeOrganizationId, {
      organizationIdRaw,
    });
    if (!organizationId) {
      return { status: 'invalid', message: 'Unknown organization' } as const;
    }

    let payload: Record<string, unknown>;
    try {
      payload = JSON.parse(body) as Record<string, unknown>;
    } catch {
      return { status: 'invalid', message: 'Body was not valid JSON' } as const;
    }

    const verified = payload.verified === true || payload.status === 'verified';

    if (verified) {
      await ctx.runMutation(internal.integrations.logSync, {
        organizationId,
        provider: 'imid',
        action: 'verification_completed',
        status: 'success',
        message: 'Phone verification completed successfully',
      });
    }

    return { status: 'ok', message: 'Verified' } as const;
  },
});

/** Internal: list all imID configs (for state resolution). */
export const listAllImidConfigs = internalQuery({
