import type { Doc, Id } from '../_generated/dataModel';
import { getProfile } from '../lib/userProfile';

/**
 * Helper function to batch load users and enrich leave data
 * Eliminates N+1 queries by pre-loading all users in one batch
 */
export async function enrichLeavesWithUserData(
  ctx: any,
  leaves: Doc<'leaveRequests'>[],
  includeReviewer: boolean = true,
) {
  if (leaves.length === 0) return [];

  // Collect all unique user IDs and reviewer IDs
  const userIds = [...new Set(leaves.map((l) => l.userId))] as Id<'users'>[];
  const reviewerIds = includeReviewer
    ? [...new Set(leaves.map((l) => l.reviewedBy).filter((id): id is Id<'users'> => Boolean(id)))]
    : [];

  // Batch load all users and reviewers in parallel
  const [users, reviewers] = await Promise.all([
    Promise.all(userIds.map((id) => ctx.db.get(id))),
    Promise.all(reviewerIds.map((id) => ctx.db.get(id as Id<'users'>))),
  ]);

  // Load profiles for user enrichment
  const profiles = await Promise.all(userIds.map((id) => getProfile(ctx, id)));

  // Create lookup maps for O(1) access
  const userMap = new Map(users.map((u) => [u?._id, u]));
  const reviewerMap = new Map(reviewers.map((r) => [r?._id, r]));
  const profileMap = new Map(userIds.map((id, i) => [id, profiles[i]]));

  // Enrich leaves with user data (no more N+1!)
  return leaves.map((leave) => {
    const user = userMap.get(leave.userId);
    const profile = profileMap.get(leave.userId);
    const reviewer = leave.reviewedBy ? reviewerMap.get(leave.reviewedBy) : null;

    return {
      ...leave,
      userName: user?.name ?? 'Unknown',
      userEmail: user?.email ?? '',
      userDepartment: profile?.department ?? user?.department ?? '',
      userEmployeeType: profile?.employeeType ?? user?.employeeType ?? 'staff',
      userAvatarUrl: profile?.avatarUrl ?? user?.avatarUrl,
      reviewerName: reviewer?.name,
    };
  });
}

import { v } from 'convex/values';
import { getAuthCaller } from '../lib/getAuthCaller';
import { mutation } from '../_generated/server';
import type { MutationCtx } from '../_generated/server';
import type { Id } from '../_generated/dataModel';
import { isSuperadmin, isSuperadminEmail } from '../lib/auth';
import { MAX_PAGE_SIZE } from '../pagination';
import { patchProfile } from '../lib/userProfile';
import { DEFAULT_LIST_CAP } from '../lib/limits';

// ─────────────────────────────────────────────────────────────────────────────
// CREATE LEAVE REQUEST
// ─────────────────────────────────────────────────────────────────────────────
export const createLeave = mutation({
  args: {
    userId: v.id('users'),
    type: v.union(
      v.literal('paid'),
      v.literal('unpaid'),
      v.literal('sick'),
      v.literal('family'),
      v.literal('doctor'),
      v.literal('day_off'),
      v.literal('maternity'),
      v.literal('paternity'),
      v.literal('study'),
    ),
    startDate: v.string(),
    endDate: v.string(),
    days: v.number(),
    reason: v.string(),
    comment: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const user = await ctx.db.get(args.userId);
    if (!user) throw new Error('User not found');
    if (!user.isApproved) throw new Error('Account pending approval');
    if (!user.organizationId) throw new Error('User does not belong to an organization');

    const leaveId = await ctx.db.insert('leaveRequests', {
      organizationId: user.organizationId, // ← tenant isolation
      userId: args.userId,
      type: args.type,
      startDate: args.startDate,
      endDate: args.endDate,
      days: args.days,
      reason: args.reason,
      comment: args.comment,
      status: 'pending',
      isRead: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    });

    // Conflict detection with company events is handled by:
    // 1. Admin manually checking events before approving
    // 2. Future: scheduled job to check conflicts

    // Notify admins within same org only
    // NOTE: Using .take(DEFAULT_LIST_CAP) here because we must notify ALL admins of a new leave request; truncating would miss recipients
    const admins = await ctx.db
      .query('users')
      .withIndex('by_org_role', (q) =>
        q.eq('organizationId', user.organizationId).eq('role', 'admin'),
      )
      .take(DEFAULT_LIST_CAP);

    // ═══════════════════════════════════════════════════════════════
    // АВТО-ОТВЕТ СОТРУДНИКУ — Заявка получена
    // ═══════════════════════════════════════════════════════════════
    const expectedResponseDate = new Date();
    expectedResponseDate.setDate(expectedResponseDate.getDate() + 1); // 24 часа

    const autoReplyMessage = `Ваша заявка на ${args.type} отпуск (${args.startDate} → ${args.endDate}) получена! ✅

📋 Детали:
• Тип: ${args.type === 'paid' ? 'Оплачиваемый' : args.type === 'sick' ? 'Больничный' : args.type === 'family' ? 'Семейный' : args.type}
• Даты: ${args.startDate} — ${args.endDate} (${args.days} дн.)
• Причина: ${args.reason}

⏰ Ожидайте ответа до: ${expectedResponseDate.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' })}

Если заявка не будет рассмотрена в течение 24 часов, вам придёт напоминание.`;

    await ctx.db.insert('notifications', {
      organizationId: user.organizationId,
      userId: args.userId,
      type: 'system',
      title: '📋 Заявка получена',
      message: autoReplyMessage,
      isRead: false,
      relatedId: leaveId,
      route: '/leaves',
      createdAt: Date.now(),
    });

    for (const recipient of admins) {
      if (recipient._id === args.userId) continue;
      await ctx.db.insert('notifications', {
        organizationId: user.organizationId,
        userId: recipient._id,
        type: 'leave_request',
        title: '🏖 New Leave Request',
        message: `${user.name} requested ${args.days} day(s) of ${args.type} leave (${args.startDate} → ${args.endDate})`,
        isRead: false,
        relatedId: leaveId,
        route: '/leaves',
        createdAt: Date.now(),
      });
    }

    // Create SLA metric
    await ctx.db.insert('slaMetrics', {
      organizationId: user.organizationId,
      leaveRequestId: leaveId,
      submittedAt: Date.now(),
      targetResponseTime: 24,
      status: 'pending',
      warningTriggered: false,
      criticalTriggered: false,
      createdAt: Date.now(),
    });

    // Audit log: leave request created
    await ctx.db.insert('auditLogs', {
      organizationId: user.organizationId,
      userId: args.userId,
      action: 'leave_created',
      target: leaveId,
      details: JSON.stringify({
        type: args.type,
        startDate: args.startDate,
        endDate: args.endDate,
        days: args.days,
        reason: args.reason,
      }),
      createdAt: Date.now(),
    });

    return leaveId;
  },
});

