import { v } from 'convex/values';
import { getAuthCaller } from '../lib/getAuthCaller';
import { query } from '../_generated/server';
import { paginationOptsValidator } from 'convex/server';
import type { Id } from '../_generated/dataModel';
import {
  paginationArgs,
  normalizePageSize,
  decodeCursor,
  encodeCursor,
  MAX_PAGE_SIZE,
} from '../pagination';
import { enrichLeavesWithUserData } from './helpers';
import { isSuperadmin } from '../lib/auth';
import { getProfile } from '../lib/userProfile';

// ─────────────────────────────────────────────────────────────────────────────
// GET ALL LEAVES — scoped to caller's organization
// OPTIMIZED: Batch loading eliminates N+1 queries
// ─────────────────────────────────────────────────────────────────────────────
export const getAllLeaves = query({
  args: {
    organizationId: v.optional(v.id('organizations')),
  },
  handler: async (ctx, args) => {
    const requester = await getAuthCaller(ctx);
    const requesterId = requester?._id;
    const organizationId = args.organizationId;
    // If organizationId is provided directly, use it
    if (organizationId && !requesterId) {
      const leaves = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
        .order('desc')
        .take(MAX_PAGE_SIZE);

      return enrichLeavesWithUserData(ctx, leaves);
    }

    // Otherwise use authenticated caller
    if (!requester) return [];

    // Superadmin sees all leaves across all organizations
    let leaves;
    if (isSuperadmin(requester)) {
      leaves = await ctx.db.query('leaveRequests').order('desc').take(MAX_PAGE_SIZE);
    } else {
      // User without organization — return empty array (needs onboarding)
      if (!requester.organizationId) return [];
      leaves = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', requester.organizationId))
        .order('desc')
        .take(MAX_PAGE_SIZE);
    }

    return enrichLeavesWithUserData(ctx, leaves);
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// PAGINATED LEAVES — for the main leaves page
// ─────────────────────────────────────────────────────────────────────────────
export const listLeavesPaginated = query({
  args: {
    organizationId: v.optional(v.id('organizations')),
    paginationOpts: paginationOptsValidator,
  },
  handler: async (ctx, args) => {
    const requester = await getAuthCaller(ctx);
    if (!requester) return { page: [], isDone: true, continueCursor: '' };

    const userIsSuperadmin = isSuperadmin(requester);

    let result;
    if (args.organizationId) {
      result = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', args.organizationId))
        .order('desc')
        .paginate(args.paginationOpts);
    } else if (userIsSuperadmin) {
      result = await ctx.db.query('leaveRequests').order('desc').paginate(args.paginationOpts);
    } else if (requester.organizationId) {
      result = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', requester.organizationId))
        .order('desc')
        .paginate(args.paginationOpts);
    } else {
      return { page: [], isDone: true, continueCursor: '' };
    }

    const enriched = await enrichLeavesWithUserData(ctx, result.page);
    return { ...result, page: enriched };
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET LEAVES FOR SPECIFIC ORGANIZATION (superadmin filtered view)
// OPTIMIZED: Batch loading eliminates N+1 queries
// ─────────────────────────────────────────────────────────────────────────────
export const getLeavesForOrganization = query({
  args: { organizationId: v.id('organizations') },
  handler: async (ctx, { organizationId }) => {
    const leaves = await ctx.db
      .query('leaveRequests')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .order('desc')
      .take(MAX_PAGE_SIZE);

    return enrichLeavesWithUserData(ctx, leaves);
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET USER LEAVES — own leaves only (or admin sees all within org)
// ─────────────────────────────────────────────────────────────────────────────
export const getUserLeaves = query({
  args: { userId: v.id('users') },
  handler: async (ctx, { userId }) => {
    return await ctx.db
      .query('leaveRequests')
      .withIndex('by_user', (q) => q.eq('userId', userId))
      .order('desc')
      .take(MAX_PAGE_SIZE);
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET PENDING LEAVES — scoped to org
// OPTIMIZED: Batch loading eliminates N+1 queries
// ─────────────────────────────────────────────────────────────────────────────
export const getPendingLeaves = query({
  args: {},
  handler: async (ctx) => {
    const requester = await getAuthCaller(ctx);
    if (!requester) return [];

    // Superadmin sees all pending leaves — use status filter
    let leaves;
    if (isSuperadmin(requester)) {
      leaves = await ctx.db
        .query('leaveRequests')
        .filter((q) => q.eq(q.field('status'), 'pending'))
        .order('desc')
        .take(MAX_PAGE_SIZE);
    } else {
      if (!requester.organizationId) throw new Error('User does not belong to an organization');
      leaves = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org_status', (q) =>
          q.eq('organizationId', requester.organizationId).eq('status', 'pending'),
        )
        .take(MAX_PAGE_SIZE);
    }

    return enrichLeavesWithUserData(ctx, leaves, false); // Don't need reviewer for pending
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET LEAVE STATS — scoped to org
// ─────────────────────────────────────────────────────────────────────────────
export const getLeaveStats = query({
  args: {},
  handler: async (ctx) => {
    const requester = await getAuthCaller(ctx);
    if (!requester) return [];

    // Superadmin sees stats across all organizations
    let all;
    if (isSuperadmin(requester)) {
      all = await ctx.db.query('leaveRequests').order('desc').take(MAX_PAGE_SIZE);
    } else {
      if (!requester.organizationId) throw new Error('User does not belong to an organization');
      all = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', requester.organizationId))
        .take(MAX_PAGE_SIZE);
    }

    const pending = all.filter((l) => l.status === 'pending').length;
    const approved = all.filter((l) => l.status === 'approved').length;
    const rejected = all.filter((l) => l.status === 'rejected').length;
    const today = new Date().toISOString().split('T')[0] || '';
    const onLeaveToday = all.filter(
      (l) => l.status === 'approved' && l.startDate <= today && l.endDate >= today,
    ).length;

    return { total: all.length, pending, approved, rejected, onLeaveToday };
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET UNREAD LEAVE REQUESTS COUNT
// ─────────────────────────────────────────────────────────────────────────────
export const getUnreadCount = query({
  args: {},
  handler: async (ctx) => {
    const requester = await getAuthCaller(ctx);
    if (!requester) return 0;

    // Superadmin sees all unread across all organizations
    let unread: number;
    if (isSuperadmin(requester)) {
      const allLeaves = await ctx.db.query('leaveRequests').order('desc').take(MAX_PAGE_SIZE);
      // Treat missing isRead as false (old records before field was added)
      unread = allLeaves.filter(
        (l) => (l.isRead === false || l.isRead === undefined) && l.status === 'pending',
      ).length;
    } else {
      if (!requester.organizationId) throw new Error('User does not belong to an organization');
      const orgLeaves = await ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', requester.organizationId))
        .take(MAX_PAGE_SIZE);
      // Treat missing isRead as false (old records before field was added)
      unread = orgLeaves.filter(
        (l) => (l.isRead === false || l.isRead === undefined) && l.status === 'pending',
      ).length;
    }

    return unread;
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET LEAVES PAGINATED — with cursor-based pagination for large datasets
// ─────────────────────────────────────────────────────────────────────────────
export const getLeavesPagederated = query({
  args: {
    ...paginationArgs,
  },
  handler: async (ctx, args) => {
    const requester = await getAuthCaller(ctx);
    if (!requester) return { items: [], hasMore: false };

    const normalizedPageSize = normalizePageSize(args.pageSize);

    // Get user's leaves based on role
    let items: any[] = [];

    if (isSuperadmin(requester)) {
      // Superadmin sees all
      const query = ctx.db.query('leaveRequests').order('desc');
      if (args.cursor) {
        const cursorData = decodeCursor(args.cursor);
        items = await query
          .filter((q) => q.lt(q.field('_creationTime'), cursorData._creationTime))
          .take(normalizedPageSize + 1);
      } else {
        items = await query.take(normalizedPageSize + 1);
      }
    } else {
      // Regular user - org scoped
      if (!requester.organizationId) return { items: [], hasMore: false };
      const query = ctx.db
        .query('leaveRequests')
        .withIndex('by_org', (q) => q.eq('organizationId', requester.organizationId))
        .order('desc');
      if (args.cursor) {
        const cursorData = decodeCursor(args.cursor);
        items = await query
          .filter((q) => q.lt(q.field('_creationTime'), cursorData._creationTime))
          .take(normalizedPageSize + 1);
      } else {
        items = await query.take(normalizedPageSize + 1);
      }
    }

    const hasMore = items.length > normalizedPageSize;
    if (hasMore) {
      items.pop();
    }

    const enriched = await enrichLeavesWithUserData(ctx, items);

    return {
      items: enriched,
      hasMore,
      nextCursor:
        hasMore && items.length > 0
          ? encodeCursor({ _creationTime: items[items.length - 1]._creationTime })
          : undefined,
    };
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET LEAVE BY ID — for detail page
// ─────────────────────────────────────────────────────────────────────────────
export const getLeaveById = query({
  args: { leaveId: v.id('leaveRequests') },
  handler: async (ctx, { leaveId }) => {
    const leave = await ctx.db.get(leaveId);
    if (!leave) return null;

    const user = await ctx.db.get(leave.userId);
    const profile = leave.userId ? await getProfile(ctx, leave.userId) : null;
    return {
      ...leave,
      userName: user?.name ?? 'Unknown',
      userDepartment: profile?.department ?? user?.department ?? '',
    };
  },
});

/**
 * Server-side RBAC (Role-Based Access Control) helpers
 *
 * These functions enforce role checks on the server side (Convex mutations/queries)
 * to prevent client-side role bypass attacks.
 *
 * Usage: Import into any Convex function and call before performing sensitive operations.
 */

import type { QueryCtx, MutationCtx } from '../_generated/server';
import type { Id } from '../_generated/dataModel';
import { isSuperadminEmail, isSuperadmin as isSuperadminRole } from './auth';

/** Valid role hierarchy (lower index = higher privilege) */
export const ROLE_HIERARCHY = ['superadmin', 'admin', 'supervisor', 'driver', 'employee'] as const;

export type Role = (typeof ROLE_HIERARCHY)[number];

/** Check if roleA has at least the privileges of roleB */
export function hasRoleAtLeast(roleA: Role, roleB: Role): boolean {
  const indexA = ROLE_HIERARCHY.indexOf(roleA);
  const indexB = ROLE_HIERARCHY.indexOf(roleB);
  return indexA <= indexB;
}

/** Get user by ID with role info */
export async function getUserWithRole(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
): Promise<{
  _id: Id<'users'>;
  role: Role;
  email: string;
  organizationId?: Id<'organizations'>;
} | null> {
  const user = await ctx.db.get(userId);
  if (!user) return null;

  return {
    _id: user._id,
    role: user.role as Role,
    email: user.email,
    organizationId: user.organizationId,
  };
}

/**
 * Require the caller to be authenticated and return their user record.
 * Throws if not authenticated or user not found.
 */
export async function requireUser(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
): Promise<{ _id: Id<'users'>; role: Role; email: string; organizationId?: Id<'organizations'> }> {
  const user = await getUserWithRole(ctx, userId);
  if (!user) {
    throw new Error('User not found');
  }
  return user;
}

/**
 * Require the caller to have a specific role.
 * Throws if user doesn't have the required role.
 */
export async function requireRole(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
  requiredRole: Role,
): Promise<{ _id: Id<'users'>; role: Role; email: string; organizationId?: Id<'organizations'> }> {
  const user = await requireUser(ctx, userId);

  if (user.role !== requiredRole && !isSuperadminRole(user)) {
    throw new Error(`Insufficient permissions. Required role: ${requiredRole}`);
  }

  return user;
}

/**
 * Require the caller to have at least a certain role level.
 * E.g., requireRoleAtLeast(ctx, userId, 'admin') allows admin or superadmin.
 */
export async function requireRoleAtLeast(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
  minimumRole: Role,
): Promise<{ _id: Id<'users'>; role: Role; email: string; organizationId?: Id<'organizations'> }> {
  const user = await requireUser(ctx, userId);

  // Superadmin always has access
  if (isSuperadminRole(user)) {
    return user;
  }

  if (!hasRoleAtLeast(user.role, minimumRole)) {
    throw new Error(`Insufficient permissions. Minimum role required: ${minimumRole}`);
  }

  return user;
}

/**
 * Require the caller to be an admin or superadmin of the organization.
 * Verifies both role AND organization membership.
 */
export async function requireOrgAdmin(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
  organizationId: Id<'organizations'>,
): Promise<{ _id: Id<'users'>; role: Role; email: string; organizationId: Id<'organizations'> }> {
  const user = await requireUser(ctx, userId);

  // Superadmin has access to all orgs
  if (isSuperadminRole(user)) {
    return { ...user, organizationId };
  }

  // Admin must belong to the same org
  if (user.role !== 'admin' || user.organizationId !== organizationId) {
    throw new Error('Insufficient permissions. Organization admin access required.');
  }

  return { ...user, organizationId };
}

/**
 * Require the caller to be a supervisor or above in the organization.
 */
export async function requireOrgSupervisor(
  ctx: QueryCtx | MutationCtx,
  userId: Id<'users'>,
  organizationId: Id<'organizations'>,
): Promise<{ _id: Id<'users'>; role: Role; email: string; organizationId: Id<'organizations'> }> {
  const user = await requireUser(ctx, userId);

  // Superadmin has access
  if (isSuperadminRole(user)) {
    return { ...user, organizationId };
  }

  // Admin or supervisor must belong to the same org
  if (
    (user.role !== 'admin' && user.role !== 'supervisor') ||
    user.organizationId !== organizationId
  ) {
    throw new Error('Insufficient permissions. Supervisor access required.');
  }

  return { ...user, organizationId };
}

/**
 * Check if user can access another user's data.
 * - Superadmin: all users
 * - Admin: users in same organization
 * - Supervisor: users in same organization (except admins/superadmins)
 * - Employee/Driver: only themselves
 */
export async function canAccessUser(
  ctx: QueryCtx | MutationCtx,
  requesterId: Id<'users'>,
  targetUserId: Id<'users'>,
): Promise<boolean> {
  const requester = await getUserWithRole(ctx, requesterId);
  if (!requester) return false;

  // Users can always access their own data
  if (requesterId === targetUserId) return true;

  // Superadmin can access all
  if (isSuperadminRole(requester)) return true;

  const target = await getUserWithRole(ctx, targetUserId);
  if (!target) return false;

  // Admin can access users in same org (except superadmins)
  if (requester.role === 'admin') {
    if (isSuperadminRole(target)) return false;
    return requester.organizationId === target.organizationId;
  }

  // Supervisor can access users in same org (except admins/superadmins)
  if (requester.role === 'supervisor') {
    if (isSuperadminRole(target) || target.role === 'admin') return false;
    return requester.organizationId === target.organizationId;
  }

  // Employee/Driver can only access themselves
  return false;
}

/**
 * Require that the requester can access the target user.
 * Throws if access is denied.
 */
export async function requireUserAccess(
  ctx: QueryCtx | MutationCtx,
  requesterId: Id<'users'>,
  targetUserId: Id<'users'>,
): Promise<void> {
  const hasAccess = await canAccessUser(ctx, requesterId, targetUserId);
  if (!hasAccess) {
    throw new Error("Access denied. You do not have permission to access this user's data.");
  }
}

/**
 * Middleware wrapper for easy RBAC in mutations/queries.
 *
 * Example usage:
 * ```ts
 * export const deleteUser = mutation(
 *   withRBAC({ minimumRole: 'admin' }, async (ctx, args) => {
 *     // Your mutation code here
 *   })
 * );
 * ```
 */
type RBACOptions = {
  minimumRole?: Role;
  requiredRole?: Role;
  requireOrgMembership?: boolean;
};

type Handler<Args, Result> = (ctx: MutationCtx | QueryCtx, args: Args) => Promise<Result>;

export function withRBAC<Args extends { userId: Id<'users'> }, Result>(
  options: RBACOptions,
  handler: Handler<Args, Result>,
): Handler<Args, Result> {
  return async (ctx: MutationCtx | QueryCtx, args: Args) => {
    if (options.requiredRole) {
      await requireRole(ctx, args.userId, options.requiredRole);
    } else if (options.minimumRole) {
      await requireRoleAtLeast(ctx, args.userId, options.minimumRole);
    }

    return handler(ctx, args);
  };
}

/**
 * User Profile helper — reads from userProfiles table with lazy migration from users.
 * Use this in queries/mutations that need profile fields (department, position, phone, etc.)
 */

import type { Id, Doc } from '../_generated/dataModel';

export interface UserProfile {
  _id: Id<'userProfiles'>;
  userId: Id<'users'>;
  employeeType?: 'staff' | 'contractor';
  department?: string;
  departmentId?: Id<'departments'>;
  position?: string;
  positionId?: Id<'positions'>;
  supervisorId?: Id<'users'>;
  phone?: string;
  location?: string;
  avatarUrl?: string;
  dateOfBirth?: string;
  presenceStatus?: 'available' | 'in_meeting' | 'in_call' | 'out_of_office' | 'busy';
  travelAllowance?: number;
  paidLeaveBalance?: number;
  sickLeaveBalance?: number;
  familyLeaveBalance?: number;
  dayOffBalance?: number;
  maternityLeaveBalance?: number;
  studyLeaveBalance?: number;
}

/** Profile field names for filtering */
export const PROFILE_FIELDS = [
  'employeeType',
  'department',
  'departmentId',
  'position',
  'positionId',
  'supervisorId',
  'phone',
  'location',
  'avatarUrl',
  'dateOfBirth',
  'presenceStatus',
  'travelAllowance',
  'paidLeaveBalance',
  'sickLeaveBalance',
  'familyLeaveBalance',
  'dayOffBalance',
  'maternityLeaveBalance',
  'studyLeaveBalance',
] as const;

/**
 * Get user profile from userProfiles table.
 * Returns null if profile doesn't exist (run migration first).
 */
export async function getProfile(ctx: any, userId: Id<'users'>): Promise<UserProfile | null> {
  return await ctx.db
    .query('userProfiles')
    .withIndex('by_user', (q) => q.eq('userId', userId))
    .first();
}

/**
 * Get profile fields directly from user doc (backward compat, no migration).
 * Use this when you already have the user doc loaded and just need profile fields.
 */
export function extractProfileFromUser(user: Doc<'users'>) {
  return {
    employeeType: user.employeeType,
    department: user.department,
    departmentId: user.departmentId,
    position: user.position,
    positionId: user.positionId,
    supervisorId: user.supervisorId,
    phone: user.phone,
    location: user.location,
    avatarUrl: user.avatarUrl,
    dateOfBirth: user.dateOfBirth,
    presenceStatus: user.presenceStatus,
    travelAllowance: user.travelAllowance,
    paidLeaveBalance: user.paidLeaveBalance,
    sickLeaveBalance: user.sickLeaveBalance,
    familyLeaveBalance: user.familyLeaveBalance,
    dayOffBalance: user.dayOffBalance,
    maternityLeaveBalance: user.maternityLeaveBalance,
    studyLeaveBalance: user.studyLeaveBalance,
  };
}

/**
 * Dual-write: patch profile fields in both users and userProfiles tables.
 * Use this when updating profile fields to keep both tables in sync.
 */
export async function patchProfile(
  ctx: any,
  userId: Id<'users'>,
  patch: Partial<Omit<UserProfile, '_id' | 'userId'>>,
) {
  // Write to users table (backward compat)
  await ctx.db.patch(userId, patch);

  // Write to userProfiles table
  const profile = await ctx.db
    .query('userProfiles')
    .withIndex('by_user', (q) => q.eq('userId', userId))
    .first();

  if (profile) {
    await ctx.db.patch(profile._id, patch);
  }
  // If no profile exists yet, lazy migration will create it on next read
}

import { v } from 'convex/values';
import { mutation, query } from '../_generated/server';
import { MAX_PAGE_SIZE } from '../pagination';
import type { Id } from '../_generated/dataModel';
import { patchProfile } from '../lib/userProfile';

// ─────────────────────────────────────────────────────────────────────────────
// CALLS - Audio/Video calling using WebRTC (similar to web version)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Start a call in a conversation
 * Creates a call record and notifies participants
 */
export const startCall = mutation({
  args: {
    conversationId: v.id('chatConversations'),
    initiatorId: v.id('users'),
    callType: v.union(v.literal('audio'), v.literal('video')),
  },
  handler: async (ctx, args) => {
    const { conversationId, initiatorId, callType } = args;
    const conv = await ctx.db.get(conversationId);
    if (!conv) throw new Error('Conversation not found');

    const initiator = await ctx.db.get(initiatorId);
    if (!initiator) throw new Error('Initiator not found');

    const now = Date.now();
    const callId = await ctx.db.insert('chatMessages', {
      conversationId,
      organizationId: conv.organizationId,
      senderId: initiatorId,
      type: 'call',
      content: `${initiator.name} started a ${callType} call`,
      callType,
      callStatus: 'missed', // Will be updated when answered
      createdAt: now,
    });

    // Set initiator status to "in_call"
    await patchProfile(ctx, initiatorId, { presenceStatus: 'in_call' });

    return { callId, conversationId };
  },
});

/**
 * Answer an incoming call
 */
export const answerCall = mutation({
  args: {
    callMessageId: v.id('chatMessages'),
    userId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { callMessageId, userId } = args;
    const call = await ctx.db.get(callMessageId);
    if (!call) throw new Error('Call not found');

    // Update call status to answered
    await ctx.db.patch(callMessageId, {
      callStatus: 'answered',
      content: `Call answered`,
    });

    // Set user status to "in_call"
    await patchProfile(ctx, userId, { presenceStatus: 'in_call' });

    return callMessageId;
  },
});

/**
 * End a call
 */
export const endCall = mutation({
  args: {
    callMessageId: v.id('chatMessages'),
    userId: v.id('users'),
    duration: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const { callMessageId, userId, duration } = args;
    const call = await ctx.db.get(callMessageId);
    if (!call) throw new Error('Call not found');

    // Update call with duration
    const patch: Record<string, any> = {
      callDuration: duration,
      content: `Call ended (${duration ? Math.floor(duration / 60) : 0}m ${duration ? duration % 60 : 0}s)`,
    };

    await ctx.db.patch(callMessageId, patch);

    // Reset user status to "available"
    await patchProfile(ctx, userId, { presenceStatus: 'available' });

    return callMessageId;
  },
});

/**
 * Decline an incoming call
 */
export const declineCall = mutation({
  args: {
    callMessageId: v.id('chatMessages'),
    userId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { callMessageId, userId } = args;
    const call = await ctx.db.get(callMessageId);
    if (!call) throw new Error('Call not found');

    await ctx.db.patch(callMessageId, {
      callStatus: 'declined',
      content: `Call declined`,
    });

    // Reset initiator status
    await patchProfile(ctx, call.senderId, { presenceStatus: 'available' });

    return callMessageId;
  },
});

/**
 * Get active call info for a conversation
 */
export const getActiveCall = query({
  args: {
    conversationId: v.id('chatConversations'),
  },
  handler: async (ctx, args) => {
    const { conversationId } = args;
    const messages = await ctx.db
      .query('chatMessages')
      .withIndex('by_conversation', (q) => q.eq('conversationId', conversationId))
      .order('desc')
      .take(5);

    // Find the most recent call message that's still active
    const activeCall = messages.find(
      (m) => m.type === 'call' && (m.callStatus === 'answered' || m.callStatus === 'missed'),
    );

    if (!activeCall) return null;

    const initiator = await ctx.db.get(activeCall.senderId);

    return {
      callId: activeCall._id,
      conversationId,
      type: activeCall.callType,
      initiatorId: activeCall.senderId,
      initiatorName: initiator?.name ?? 'Unknown',
      status: activeCall.callStatus,
      createdAt: activeCall.createdAt,
    };
  },
});

/**
 * Get incoming calls for a user
 */
export const getIncomingCalls = query({
  args: {
    userId: v.id('users'),
    organizationId: v.optional(v.id('organizations')),
  },
  handler: async (ctx, args) => {
    const { userId, organizationId } = args;
    // Get all conversations for this user
    const memberships = await ctx.db
      .query('chatMembers')
      .withIndex('by_user', (q) => q.eq('userId', userId))
      .take(MAX_PAGE_SIZE);

    // Batch-load recent messages for all conversations upfront
    const conversationIds = memberships.map((m) => m.conversationId);
    const allMessages = await Promise.all(
      conversationIds.map((convId) =>
        ctx.db
          .query('chatMessages')
          .withIndex('by_conversation', (q) => q.eq('conversationId', convId))
          .order('desc')
          .take(3),
      ),
    );

    // Collect unique sender IDs from potential incoming calls
    const uniqueSenderIds = new Set<Id<'users'>>();
    for (const messages of allMessages) {
      for (const msg of messages) {
        if (msg.type === 'call' && msg.senderId !== userId && msg.callStatus === 'missed') {
          uniqueSenderIds.add(msg.senderId as Id<'users'>);
        }
      }
    }

    // Batch-load all potential initiators
    const sendersBatch = await Promise.all([...uniqueSenderIds].map((id) => ctx.db.get(id)));
    const senderMap = new Map(sendersBatch.filter(Boolean).map((s) => [s._id, s]));

    // Find active calls in these conversations
    for (let i = 0; i < memberships.length; i++) {
      const messages = allMessages[i] || [];
      const incomingCall = messages.find(
        (m) => m.type === 'call' && m.senderId !== userId && m.callStatus === 'missed',
      );

      if (incomingCall) {
        const initiator = senderMap.get(incomingCall.senderId);
        return {
          callId: incomingCall._id,
          conversationId: incomingCall.conversationId,
          type: incomingCall.callType,
          initiatorId: incomingCall.senderId,
          initiatorName: initiator?.name ?? 'Unknown',
          status: incomingCall.callStatus,
          createdAt: incomingCall.createdAt,
        };
      }
    }

    return null;
  },
});

import { v } from 'convex/values';
import { mutation, query } from '../_generated/server';
import type { Id } from '../_generated/dataModel';
import type { QueryCtx } from '../_generated/server';
import { MAX_PAGE_SIZE } from '../pagination';
import { getProfile } from '../lib/userProfile';

async function getUserOrgId(ctx: QueryCtx, userId: Id<'users'>): Promise<Id<'organizations'>> {
  const user = await ctx.db.get(userId);
  if (!user) throw new Error('User not found');
  if (!user.organizationId) throw new Error('User has no organization');
  return user.organizationId;
}

// ─────────────────────────────────────────────────────────────────────────────
// GET MY CONVERSATIONS — sorted by lastMessageAt, with unread counts
// Uses chatConversations + chatMembers (shared with desktop)
// ─────────────────────────────────────────────────────────────────────────────
export const getMyConversations = query({
  args: {
    userId: v.id('users'),
    organizationId: v.optional(v.id('organizations')),
  },
  handler: async (ctx, args) => {
    const { userId, organizationId } = args;
    const user = await ctx.db.get(userId);
    if (!user) return [];

    // For superadmin without org, get all memberships
    const memberships = await ctx.db
      .query('chatMembers')
      .withIndex('by_user', (q) => q.eq('userId', userId))
      .take(MAX_PAGE_SIZE);

    const conversations = await Promise.all(
      memberships
        .filter((m) => !m.isDeleted)
        .map(async (m) => {
          const conv = await ctx.db.get(m.conversationId);
          if (!conv || conv.isDeleted) return null;

          // For org-scoped users, only show their org conversations
          if (user.organizationId && conv.organizationId !== user.organizationId) return null;

          // For DMs: get other user's info
          let otherUser = null;
          if (conv.type === 'direct') {
            const allMembers = await ctx.db
              .query('chatMembers')
              .withIndex('by_conversation', (q) => q.eq('conversationId', conv._id))
              .take(MAX_PAGE_SIZE);
            const otherMember = allMembers.find((mm) => mm.userId !== userId);
            if (otherMember) {
              const u = await ctx.db.get(otherMember.userId);
              if (u) {
                const uProfile = await getProfile(ctx, u._id);
                otherUser = {
                  _id: u._id,
                  name: u.name,
                  avatarUrl: uProfile?.avatarUrl ?? u.avatarUrl,
                  presenceStatus: uProfile?.presenceStatus ?? u.presenceStatus,
                };
              }
            }
          }

          return {
            ...conv,
            unreadCount: m.unreadCount,
            isMuted: m.isMuted,
            lastReadAt: m.lastReadAt,
            otherUser,
            // Map desktop fields to what ConversationList expects
            lastMessagePreview: conv.lastMessageText
              ? conv.lastMessageSenderId
                ? conv.lastMessageText
                : conv.lastMessageText
              : undefined,
          };
        }),
    );

    return conversations.filter(Boolean).sort((a, b) => {
      if (a!.isPinned && !b!.isPinned) return -1;
      if (!a!.isPinned && b!.isPinned) return 1;
      return (b!.lastMessageAt ?? b!.createdAt) - (a!.lastMessageAt ?? a!.createdAt);
    });
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET CONVERSATION INFO — participants + metadata
// ─────────────────────────────────────────────────────────────────────────────
export const getConversationInfo = query({
  args: {
    conversationId: v.id('chatConversations'),
    userId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { conversationId, userId } = args;
    const membership = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', userId),
      )
      .first();
    if (!membership) throw new Error('Not a member');

    const conv = await ctx.db.get(conversationId);
    if (!conv) throw new Error('Conversation not found');

    const members = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation', (q) => q.eq('conversationId', conversationId))
      .take(MAX_PAGE_SIZE);

    const enrichedParticipants = await Promise.all(
      members.map(async (m) => {
        const user = await ctx.db.get(m.userId);
        const userProfile = await getProfile(ctx, m.userId);
        return {
          ...m,
          // Map to expected shape
          userId: m.userId,
          userName: user?.name ?? 'Unknown',
          userAvatarUrl: userProfile?.avatarUrl ?? user?.avatarUrl,
          userEmail: user?.email,
          userRole: user?.role,
          userDepartment: userProfile?.department ?? user?.department,
        };
      }),
    );

    return {
      ...conv,
      // Map desktop type to mobile type for UI compat
      type: conv.type === 'direct' ? ('personal' as const) : ('group' as const),
      participants: enrichedParticipants,
      myRole: membership.role,
      isMuted: membership.isMuted,
    };
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// GET OR CREATE DM — 1-on-1 chat using chatConversations
// ─────────────────────────────────────────────────────────────────────────────
export const getOrCreatePersonalConversation = mutation({
  args: {
    userId: v.id('users'),
    otherUserId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { userId, otherUserId } = args;
    if (userId === otherUserId) throw new Error('Cannot create conversation with yourself');

    const orgId = await getUserOrgId(ctx, userId);
    const ids = [userId, otherUserId].sort();
    const dmKey = ids.join('_');

    // Check existing DM
    const existing = await ctx.db
      .query('chatConversations')
      .withIndex('by_dm_key', (q) => q.eq('dmKey', dmKey))
      .first();
    if (existing) return existing._id;

    const now = Date.now();
    const convId = await ctx.db.insert('chatConversations', {
      organizationId: orgId,
      type: 'direct',
      createdBy: userId,
      dmKey,
      createdAt: now,
      updatedAt: now,
    });

    await ctx.db.insert('chatMembers', {
      conversationId: convId,
      userId,
      organizationId: orgId,
      role: 'member',
      unreadCount: 0,
      isMuted: false,
      joinedAt: now,
    });

    await ctx.db.insert('chatMembers', {
      conversationId: convId,
      userId: otherUserId,
      organizationId: orgId,
      role: 'member',
      unreadCount: 0,
      isMuted: false,
      joinedAt: now,
    });

    return convId;
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// CREATE GROUP CONVERSATION
// ─────────────────────────────────────────────────────────────────────────────
export const createGroupConversation = mutation({
  args: {
    creatorId: v.id('users'),
    name: v.string(),
    participantIds: v.array(v.id('users')),
  },
  handler: async (ctx, args) => {
    const { creatorId, name, participantIds } = args;
    const orgId = await getUserOrgId(ctx, creatorId);
    const now = Date.now();

    const convId = await ctx.db.insert('chatConversations', {
      organizationId: orgId,
      type: 'group',
      name,
      createdBy: creatorId,
      createdAt: now,
      updatedAt: now,
    });

    // Add creator as owner
    await ctx.db.insert('chatMembers', {
      conversationId: convId,
      userId: creatorId,
      organizationId: orgId,
      role: 'owner',
      unreadCount: 0,
      isMuted: false,
      joinedAt: now,
    });

    // Add participants
    const uniqueIds = [...new Set(participantIds.filter((id) => id !== creatorId))];
    for (const uid of uniqueIds) {
      await ctx.db.insert('chatMembers', {
        conversationId: convId,
        userId: uid,
        organizationId: orgId,
        role: 'member',
        unreadCount: 0,
        isMuted: false,
        joinedAt: now,
      });
    }

    // System message
    const creator = await ctx.db.get(creatorId);
    await ctx.db.insert('chatMessages', {
      conversationId: convId,
      organizationId: orgId,
      senderId: creatorId,
      type: 'system',
      content: `${creator?.name ?? 'Someone'} created the group "${name}"`,
      createdAt: now,
    });

    // Audit log: group conversation created
    await ctx.db.insert('auditLogs', {
      organizationId: orgId,
      userId: creatorId,
      action: 'messenger_group_created',
      target: convId,
      details: JSON.stringify({ name, participantCount: uniqueIds.length + 1 }),
      createdAt: now,
    });

    return convId;
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// UPDATE CONVERSATION — name
// ─────────────────────────────────────────────────────────────────────────────
export const updateConversation = mutation({
  args: {
    conversationId: v.id('chatConversations'),
    userId: v.id('users'),
    name: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const { conversationId, userId, name } = args;
    const membership = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', userId),
      )
      .first();
    if (!membership || (membership.role !== 'owner' && membership.role !== 'admin'))
      throw new Error('Not authorized');

    const patch: Record<string, unknown> = { updatedAt: Date.now() };
    if (name !== undefined) patch.name = name;
    await ctx.db.patch(conversationId, patch);

    // Audit log: conversation updated
    await ctx.db.insert('auditLogs', {
      organizationId: membership.organizationId,
      userId,
      action: 'messenger_conversation_updated',
      target: conversationId,
      details: JSON.stringify({ name: name || 'metadata' }),
      createdAt: Date.now(),
    });
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// LEAVE CONVERSATION
// ─────────────────────────────────────────────────────────────────────────────
export const leaveConversation = mutation({
  args: {
    conversationId: v.id('chatConversations'),
    userId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { conversationId, userId } = args;
    const membership = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', userId),
      )
      .first();
    if (!membership) return;

    await ctx.db.delete(membership._id);

    const conv = await ctx.db.get(conversationId);
    const user = await ctx.db.get(userId);
    if (conv) {
      await ctx.db.insert('chatMessages', {
        conversationId,
        organizationId: conv.organizationId,
        senderId: userId,
        type: 'system',
        content: `${user?.name ?? 'A member'} left the group`,
        createdAt: Date.now(),
      });

      // Audit log: user left conversation
      await ctx.db.insert('auditLogs', {
        organizationId: conv.organizationId,
        userId,
        action: 'messenger_user_left_conversation',
        target: conversationId,
        details: JSON.stringify({ userName: user?.name ?? 'Unknown' }),
        createdAt: Date.now(),
      });
    }
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// ADD PARTICIPANTS
// ─────────────────────────────────────────────────────────────────────────────
export const addParticipants = mutation({
  args: {
    conversationId: v.id('chatConversations'),
    adminUserId: v.id('users'),
    userIds: v.array(v.id('users')),
  },
  handler: async (ctx, args) => {
    const { conversationId, adminUserId, userIds } = args;
    const conv = await ctx.db.get(conversationId);
    if (!conv || conv.type !== 'group') throw new Error('Not a group conversation');

    const adminM = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', adminUserId),
      )
      .first();
    if (!adminM || (adminM.role !== 'owner' && adminM.role !== 'admin'))
      throw new Error('Not authorized');

    const now = Date.now();
    const admin = await ctx.db.get(adminUserId);
    const addedNames: string[] = [];

    // Batch-load all users upfront to avoid N+1 queries
    const usersBatch = await Promise.all(userIds.map((id) => ctx.db.get(id)));
    const userMap = new Map(usersBatch.filter(Boolean).map((u) => [u._id, u]));

    // Batch-check existing memberships
    const allMemberships = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation', (q) => q.eq('conversationId', conversationId))
      .take(MAX_PAGE_SIZE);
    const existingMemberIds = new Set(allMemberships.map((m) => m.userId));

    for (const uid of userIds) {
      if (existingMemberIds.has(uid)) continue;

      await ctx.db.insert('chatMembers', {
        conversationId,
        userId: uid,
        organizationId: conv.organizationId,
        role: 'member',
        unreadCount: 0,
        isMuted: false,
        joinedAt: now,
      });

      const user = userMap.get(uid);
      if (user) addedNames.push(user.name);
    }

    if (addedNames.length > 0) {
      await ctx.db.insert('chatMessages', {
        conversationId,
        organizationId: conv.organizationId,
        senderId: adminUserId,
        type: 'system',
        content: `${admin?.name ?? 'Admin'} added ${addedNames.join(', ')}`,
        createdAt: now,
      });

      // Audit log: participants added
      await ctx.db.insert('auditLogs', {
        organizationId: conv.organizationId,
        userId: adminUserId,
        action: 'messenger_participants_added',
        target: conversationId,
        details: JSON.stringify({ addedNames, count: addedNames.length }),
        createdAt: now,
      });
    }
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// REMOVE PARTICIPANT
// ─────────────────────────────────────────────────────────────────────────────
export const removeParticipant = mutation({
  args: {
    conversationId: v.id('chatConversations'),
    adminUserId: v.id('users'),
    targetUserId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { conversationId, adminUserId, targetUserId } = args;
    const adminM = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', adminUserId),
      )
      .first();
    if (!adminM || (adminM.role !== 'owner' && adminM.role !== 'admin'))
      throw new Error('Not authorized');

    const targetM = await ctx.db
      .query('chatMembers')
      .withIndex('by_conversation_user', (q) =>
        q.eq('conversationId', conversationId).eq('userId', targetUserId),
      )
      .first();
    if (!targetM) throw new Error('User is not a member');

    await ctx.db.delete(targetM._id);

    const conv = await ctx.db.get(conversationId);
    const admin = await ctx.db.get(adminUserId);
    const target = await ctx.db.get(targetUserId);
    if (conv) {
      await ctx.db.insert('chatMessages', {
        conversationId,
        organizationId: conv.organizationId,
        senderId: adminUserId,
