            ? {
                name: user.name,
                email: user.email,
                avatarUrl: userProfile?.avatarUrl ?? user.avatarUrl ?? user.faceImageUrl,
              }
            : null,
          run: run
            ? {
                period: run.period,
                status: run.status,
              }
            : null,
        };
      }),
    );

    return enriched.sort((a, b) => b.createdAt - a.createdAt);
  },
});

