    location: v.optional(v.string()),
    employeeType: v.union(v.literal('staff'), v.literal('contractor')),
  },
  handler: async (ctx, args) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) throw new Error('Not authenticated');
    await verifyRestrictedOrg(ctx, args.organizationId);

    if (caller.role !== 'superadmin' && caller.organizationId !== args.organizationId) {
      throw new Error('Access denied: cross-organization operation');
    }

    const emailLower = args.email.toLowerCase().trim();
    const existing = await ctx.db
      .query('users')
      .withIndex('by_email', (q) => q.eq('email', emailLower))
      .first();

    if (existing) {
      await ctx.db.patch(existing._id, {
        name: args.name,
        department: args.department,
        position: args.position,
        phone: args.phone,
        location: args.location,
        employeeType: args.employeeType,
        isActive: true,
      });
      return { action: 'updated' as const, userId: existing._id };
    }

    const userId = await ctx.db.insert('users', {
      organizationId: args.organizationId,
      name: args.name,
      email: emailLower,
      passwordHash: `sharepoint_sync_${Date.now()}`,
      role: 'employee',
      employeeType: args.employeeType,
      department: args.department,
      position: args.position,
      phone: args.phone,
      location: args.location,
      isActive: true,
      isApproved: true,
      travelAllowance: args.employeeType === 'staff' ? 20000 : 12000,
      paidLeaveBalance: 20,
      sickLeaveBalance: 10,
      familyLeaveBalance: 5,
      dayOffBalance: 6,
      maternityLeaveBalance: 0,
      studyLeaveBalance: 5,
      createdAt: Date.now(),
    });

    return { action: 'created' as const, userId };
  },
});

import { v } from 'convex/values';
import { query, mutation } from './_generated/server';
import { DEFAULT_LIST_CAP, SMALL_LIST_CAP } from './lib/limits';

/**
 * Deterministic, Unicode-safe content hash for integrity display. Uses a DJB2
 * hash over the full string's code points, so it works for any language
 * (Cyrillic, emoji, etc.) — unlike `btoa`, which throws on non-Latin1 input.
 */
function hashContent(content: string): string {
  let hash = 5381;
  for (let i = 0; i < content.length; i++) {
    hash = (hash * 33) ^ content.charCodeAt(i);
  }
  // >>> 0 coerces to an unsigned 32-bit int; base36 keeps it short.
  return (hash >>> 0).toString(36) + '-' + content.length.toString(36);
}

