/**
 * Strategy Maps — visual cascade of OKRs across the organization.
 *
 * Fetches the full OKR tree (Company → Team → Individual) with progress
 * and health indicators so the frontend can render an interactive map.
 *
 * Also provides Balanced Scorecard (BSC) aggregation across 4 perspectives:
 * Financial, Customer, Internal Processes, Learning & Growth.
 */
import { v } from 'convex/values';
import { query } from './_generated/server';
import { DEFAULT_LIST_CAP } from './lib/limits';
import { getProfile } from './lib/userProfile';
import type { Id } from './_generated/dataModel';

// ── Types ────────────────────────────────────────────────────────────────────

export type HealthStatus = 'on_track' | 'at_risk' | 'behind' | 'completed' | 'draft';

/** Balanced Scorecard perspectives */
export type BscPerspective = 'financial' | 'customer' | 'internal' | 'learning';
export type BscScore = 'excellent' | 'good' | 'fair' | 'poor';

/** A single perspective in the BSC dashboard */
export interface BscPerspectiveData {
  /** Financial | Customer | Internal Process | Learning & Growth */
  id: BscPerspective;
  name: string;
  score: number; // 0-100
  grade: BscScore;
  objectivesCount: number;
  onTrackCount: number;
  atRiskCount: number;
  behindCount: number;
  completedCount: number;
  avgProgress: number;
  /** Last N periods for trend sparkline */
  trend: number[];
  /** Key metrics linked to this perspective */
  metrics: Array<{ label: string; value: string; direction: 'up' | 'down' | 'neutral' }>;
}

/** North Star metric — the single most important KPI */
export interface NorthStarMetric {
  label: string;
  value: string;
  target: string;
  progress: number;
  direction: 'up' | 'down' | 'neutral';
}

/** Full Balanced Scorecard payload */
export interface BalancedScorecardData {
  northStar: NorthStarMetric;
  perspectives: BscPerspectiveData[];
  overallScore: number;
  overallGrade: BscScore;
  lastUpdated: number;
}

type ObjectiveLevel = 'company' | 'team' | 'individual';

export function getHealth(progress: number, status: string): HealthStatus {
  if (status === 'completed') return 'completed';
  if (status === 'draft' || status !== 'active') return 'draft';
  if (progress >= 70) return 'on_track';
  if (progress >= 40) return 'at_risk';
  return 'behind';
}

interface TreeNode {
  _id: Id<'objectives'>;
  title: string;
  description?: string;
  level: ObjectiveLevel;
  department?: string;
  ownerId: Id<'users'>;
  ownerName: string;
  ownerAvatar?: string;
  progress: number;
  status: string;
  health: HealthStatus;
  periodType: string;
  periodYear: number;
  keyResultsCount: number;
  children: TreeNode[];
  depth: number;
  parentObjectiveId?: Id<'objectives'>;
}

// ══════════════════════════════════════════════════════════════════════════════
// QUERIES
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Get the full strategy tree for an organization, optionally filtered by period.
 *
 * Returns a flat array of root-level objectives (company level) each populated
 * with their nested children (team → individual).
 */
export const getStrategyTree = query({
  args: {
    organizationId: v.id('organizations'),
    periodYear: v.optional(v.number()),
    periodType: v.optional(
      v.union(
        v.literal('Q1'),
        v.literal('Q2'),
        v.literal('Q3'),
        v.literal('Q4'),
        v.literal('H1'),
        v.literal('H2'),
        v.literal('FY'),
      ),
    ),
    /** If true, only show company + team levels (hide individual) */
    compact: v.optional(v.boolean()),
  },
  handler: async (ctx, args): Promise<TreeNode[]> => {
    const { organizationId, periodYear, periodType, compact } = args;

    const rawObjectives = await ctx.db
      .query('objectives')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .take(DEFAULT_LIST_CAP);

    // Apply period filters & exclude cancelled
    const objectives = rawObjectives.filter((o) => {
      if (o.status === 'cancelled') return false;
      if (periodYear !== undefined && o.periodYear !== periodYear) return false;
      if (periodType !== undefined && o.periodType !== periodType) return false;
      return true;
    });

    // Batch-load owner info
    const ownerIds = [...new Set(objectives.map((o) => o.ownerId))];
    const ownerDocs = await Promise.all(ownerIds.map((uid) => ctx.db.get(uid)));
    const ownerMap = new Map(
      ownerDocs
        .filter((doc): doc is NonNullable<typeof doc> => doc !== null)
        .map((u) => [u._id, u]),
    );
    const profileDocs = await Promise.all(ownerIds.map((uid) => getProfile(ctx, uid)));
    const profileMap = new Map(
      profileDocs
        .filter((doc): doc is NonNullable<typeof doc> => doc !== null)
        .map((p) => [p.userId, p]),
    );

    // Batch-load KR counts
    const objectivesWithKrs = await Promise.all(
      objectives.map(async (obj) => {
        const krs = await ctx.db
          .query('keyResults')
          .withIndex('by_objective', (q) => q.eq('objectiveId', obj._id))
          .take(10);
        return { objective: obj, keyResults: krs };
      }),
    );

    // Build lookup by ID
    const objMap = new Map<Id<'objectives'>, TreeNode>();

    for (const { objective: obj, keyResults: krs } of objectivesWithKrs) {
      const owner = ownerMap.get(obj.ownerId);
      const profile = profileMap.get(obj.ownerId);
      const node: TreeNode = {
        _id: obj._id,
        title: obj.title,
        description: obj.description,
        level: obj.level,
        department: obj.department,
        ownerId: obj.ownerId,
        ownerName: owner?.name ?? 'Unknown',
        ownerAvatar: profile?.avatarUrl ?? owner?.avatarUrl ?? '',
        progress: obj.progress,
        status: obj.status,
        health: getHealth(obj.progress, obj.status),
        periodType: obj.periodType,
        periodYear: obj.periodYear,
        keyResultsCount: krs.length,
        parentObjectiveId: obj.parentObjectiveId,
        children: [],
        depth: 0,
      };
      objMap.set(obj._id, node);
    }

    // Build tree: attach children to parents
    const roots: TreeNode[] = [];

    for (const node of objMap.values()) {
      if (node.parentObjectiveId !== undefined && objMap.has(node.parentObjectiveId)) {
        const parent = objMap.get(node.parentObjectiveId)!;
        parent.children.push(node);
        node.depth = parent.depth + 1;
      } else {
        roots.push(node);
      }
    }

    // Sort roots and children by level, then by progress (desc)
    const levelOrder: Record<ObjectiveLevel, number> = {
      company: 0,
      team: 1,
      individual: 2,
    };

    const sortNodes = (nodes: TreeNode[]): void => {
      nodes.sort((a, b) => {
        const aOrder = levelOrder[a.level] ?? 99;
        const bOrder = levelOrder[b.level] ?? 99;
        if (aOrder !== bOrder) return aOrder - bOrder;
        return b.progress - a.progress;
      });
      for (const node of nodes) {
        sortNodes(node.children);
      }
    };

    sortNodes(roots);

    // Filter individual level if compact mode
    if (compact) {
      const removeIndividuals = (nodes: TreeNode[]): TreeNode[] =>
        nodes
          .filter((n) => n.level !== 'individual')
          .map((n) => ({
            ...n,
            children: removeIndividuals(n.children),
          }));
      return removeIndividuals(roots);
    }

    return roots;
  },
});

/**
 * Get summary stats for the strategy map dashboard header.
 */
export const getStrategySummary = query({
  args: {
    organizationId: v.id('organizations'),
    periodYear: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const { organizationId, periodYear } = args;

    const rawObjectives = await ctx.db
      .query('objectives')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .take(DEFAULT_LIST_CAP);

    const objectives = rawObjectives.filter((o) => {
      if (periodYear !== undefined && o.periodYear !== periodYear) return false;
      if (o.status === 'cancelled') return false;
      return true;
    });

    const active = objectives.filter((o) => o.status === 'active');
    const total = objectives.length;

    const onTrack = active.filter((o) => o.progress >= 70).length;
    const atRisk = active.filter((o) => o.progress >= 40 && o.progress < 70).length;
    const behind = active.filter((o) => o.progress < 40).length;
    const completed = objectives.filter((o) => o.status === 'completed').length;

    const avgProgress =
      active.length > 0
        ? Math.round(active.reduce((sum, o) => sum + o.progress, 0) / active.length)
        : 0;

    const byLevel = {
      company: objectives.filter((o) => o.level === 'company').length,
      team: objectives.filter((o) => o.level === 'team').length,
      individual: objectives.filter((o) => o.level === 'individual').length,
    };

    return {
      total,
      active: active.length,
      onTrack,
      atRisk,
      behind,
      completed,
      avgProgress,
      byLevel,
    };
  },
});

// ══════════════════════════════════════════════════════════════════════════════
// BALANCED SCORECARD
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Map an objective to a BSC perspective based on its level, department, and title.
 *
 * Heuristic rules:
 * - Company-level: Financial (revenue/cost related) or Customer (growth/satisfaction related)
 * - Team-level: Internal Processes (operational efficiency)
 * - Individual-level: Learning & Growth (skills, performance)
 * - Titles containing revenue/cost/financial → Financial
 * - Titles containing customer/satisfaction/nps → Customer
 * - Titles containing process/efficiency/quality/operational → Internal
 * - Titles containing learning/skill/training/culture → Learning
 * - Department name analysis for company-level
 */
function mapToPerspective(level: string, title: string, department?: string): BscPerspective {
  const t = title.toLowerCase();
  const dept = (department ?? '').toLowerCase();

  // Keyword-based classification (highest priority)
  const financialKeywords = [
    'revenue',
    'cost',
    'financial',
    'profit',
    'budget',
    'roi',
    'margins',
    'cash flow',
    'revenue growth',
    'cost reduction',
    'profitability',
    'arr',
    'mrr',
    'ebitda',
    'shareholder',
    'fiscal',
    'spend',
    'savings',
  ];
  const customerKeywords = [
    'customer',
    'satisfaction',
    'nps',
    'client',
    'market share',
    'retention',
    'acquisition',
    'customer experience',
    'csat',
    'brand',
    'loyalty',
    'referral',
    'service level',
    'sla',
  ];
  const internalKeywords = [
    'process',
    'efficiency',
    'quality',
    'operational',
    'cycle time',
    'throughput',
    'compliance',
    'automation',
    'integration',
    'workflow',
    'productivity',
    'defect',
    'downtime',
    'delivery',
  ];
  const learningKeywords = [
    'learning',
    'skill',
    'training',
    'culture',
    'engagement',
    'talent',
    'development',
    'mentorship',
    'career',
    'growth',
    'innovation',
    'knowledge',
    'capability',
    'leadership',
    'onboarding',
    'certification',
    'competency',
    'satisfaction',
  ];

  // Department-based classification
  const financialDepts = ['finance', 'accounting', 'treasury', 'audit'];
  const customerDepts = ['sales', 'marketing', 'support', 'customer success'];
  const internalDepts = ['operations', 'engineering', 'it', 'legal', 'hr'];
  const learningDepts = ['learning', 'training', 'talent', 'people'];

  // Check department first
  if (financialDepts.some((d) => dept.includes(d))) return 'financial';
  if (customerDepts.some((d) => dept.includes(d))) return 'customer';
  if (internalDepts.some((d) => dept.includes(d))) return 'internal';
  if (learningDepts.some((d) => dept.includes(d))) return 'learning';

  // Check title keywords
  const countKeywords = (keywords: string[]): number =>
    keywords.filter((kw) => t.includes(kw)).length;

  const scores = {
    financial: countKeywords(financialKeywords),
    customer: countKeywords(customerKeywords),
    internal: countKeywords(internalKeywords),
    learning: countKeywords(learningKeywords),
  };

  const maxScore = Math.max(...Object.values(scores));
  if (maxScore > 0) {
    const best = Object.entries(scores).find(([, s]) => s === maxScore)![0] as BscPerspective;
    return best;
  }

  // Fallback: map by level
  switch (level) {
    case 'company':
      return 'financial';
    case 'team':
      return 'internal';
    case 'individual':
      return 'learning';
    default:
      return 'internal';
  }
}

function computeGrade(score: number): BscScore {
  if (score >= 80) return 'excellent';
  if (score >= 60) return 'good';
  if (score >= 40) return 'fair';
  return 'poor';
}

/**
 * Get Balanced Scorecard data for an organization.
 *
 * Groups objectives into 4 BSC perspectives, calculates scores,
 * and returns the North Star metric + full scorecard.
 */
export const getBalancedScorecard = query({
  args: {
    organizationId: v.id('organizations'),
    periodYear: v.optional(v.number()),
  },
  handler: async (ctx, args): Promise<BalancedScorecardData> => {
    const { organizationId, periodYear } = args;
    const currentYear = periodYear ?? new Date().getFullYear();

    // Fetch all objectives for current + previous year (for trend)
    const rawObjectives = await ctx.db
      .query('objectives')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .take(DEFAULT_LIST_CAP);

    const objectives = rawObjectives.filter(
      (o) => o.status !== 'cancelled' && (periodYear === undefined || o.periodYear === periodYear),
    );

    // Group objectives by BSC perspective
    const grouped: Record<BscPerspective, typeof objectives> = {
      financial: [],
      customer: [],
      internal: [],
      learning: [],
    };

    for (const obj of objectives) {
      const perspective = mapToPerspective(obj.level, obj.title, obj.department);
      if (grouped[perspective]) {
        grouped[perspective].push(obj);
      }
    }

    // Compute perspective scores
    const perspectiveIds: BscPerspective[] = ['financial', 'customer', 'internal', 'learning'];

    const perspectiveNames: Record<BscPerspective, string> = {
      financial: 'Financial',
      customer: 'Customer',
      internal: 'Internal Process',
      learning: 'Learning & Growth',
    };

    // Get previous year data for trend
    const prevYearObjectives = rawObjectives.filter(
      (o) => o.status !== 'cancelled' && o.periodYear === currentYear - 1,
    );

    const computeAvgProgress = (objs: typeof objectives): number =>
      objs.length > 0 ? Math.round(objs.reduce((sum, o) => sum + o.progress, 0) / objs.length) : 0;

    const perspectives: BscPerspectiveData[] = perspectiveIds.map((id) => {
      const objs = grouped[id];
      const active = objs.filter((o) => o.status === 'active');

      const onTrackCount = active.filter((o) => o.progress >= 70).length;
      const atRiskCount = active.filter((o) => o.progress >= 40 && o.progress < 70).length;
      const behindCount = active.filter((o) => o.progress < 40).length;
      const completedCount = objs.filter((o) => o.status === 'completed').length;

      const avgProgress = computeAvgProgress(active);

      // Score is weighted: 60% progress, 30% health ratio, 10% completion
      const healthRatio =
        active.length > 0
          ? (onTrackCount + completedCount) / (active.length + completedCount || 1)
          : 0;
      const completionRate = objs.length > 0 ? completedCount / objs.length : 0;
      const score = Math.round(
        avgProgress * 0.6 + healthRatio * 100 * 0.3 + completionRate * 100 * 0.1,
      );

      // Trend: compute avg progress by quarter/year
      const prevObjs = prevYearObjectives.filter((o) => {
        const p = mapToPerspective(o.level, o.title, o.department);
        return p === id;
      });
      const prevActive = prevObjs.filter((o) => o.status === 'active');
      const prevProgress = computeAvgProgress(prevActive);
      const trend = [prevProgress, avgProgress];

      // Key metrics for this perspective
      const metrics = generatePerspectiveMetrics(id, objs, avgProgress);

      return {
        id,
        name: perspectiveNames[id],
        score: Math.min(100, Math.max(0, score)),
        grade: computeGrade(score),
        objectivesCount: objs.length,
        onTrackCount,
        atRiskCount,
        behindCount,
        completedCount,
        avgProgress,
        trend,
        metrics,
      };
    });

    // Compute overall score
    const weightedScore =
      perspectives.reduce((sum, p) => sum + p.score * Math.max(1, p.objectivesCount), 0) /
      Math.max(
        1,
        perspectives.reduce((sum, p) => sum + p.objectivesCount, 0),
      );

    const overallScore = Math.round(weightedScore);

    // Compute North Star metric — the most important metric overall
    const northStar = computeNorthStar(objectives, perspectives, overallScore);

    return {
      northStar,
      perspectives,
      overallScore,
      overallGrade: computeGrade(overallScore),
      lastUpdated: Date.now(),
    };
  },
});

/**
 * Generate perspective-specific key metrics.
 */
function generatePerspectiveMetrics(
  id: BscPerspective,
  objectives: any[],
  avgProgress: number,
): Array<{ label: string; value: string; direction: 'up' | 'down' | 'neutral' }> {
  const active = objectives.filter((o) => o.status === 'active');
  const completedCount = objectives.filter((o) => o.status === 'completed').length;
  const total = objectives.length;

  const completionRate = total > 0 ? Math.round((completedCount / total) * 100) : 0;

  switch (id) {
    case 'financial':
      return [
        {
          label: 'Avg Progress',
          value: `${avgProgress}%`,
          direction: avgProgress >= 70 ? 'up' : avgProgress >= 40 ? 'neutral' : 'down',
        },
        {
          label: 'Completion Rate',
          value: `${completionRate}%`,
          direction: completionRate >= 50 ? 'up' : 'down',
        },
        {
          label: 'Active Objectives',
          value: String(active.length),
          direction: 'neutral',
        },
      ];
    case 'customer':
      return [
        {
          label: 'Avg Progress',
          value: `${avgProgress}%`,
          direction: avgProgress >= 70 ? 'up' : avgProgress >= 40 ? 'neutral' : 'down',
        },
        {
          label: 'On Track Rate',
          value: `${active.length > 0 ? Math.round((active.filter((o) => o.progress >= 70).length / active.length) * 100) : 0}%`,
          direction: avgProgress >= 50 ? 'up' : 'down',
        },
        {
          label: 'Total Objectives',
          value: String(total),
          direction: 'neutral',
        },
      ];
    case 'internal':
      return [
        {
          label: 'Operational Progress',
          value: `${avgProgress}%`,
          direction: avgProgress >= 60 ? 'up' : avgProgress >= 30 ? 'neutral' : 'down',
        },
        {
          label: 'Completed',
          value: String(completedCount),
          direction: completedCount >= 2 ? 'up' : 'neutral',
        },
        {
          label: 'At Risk',
          value: String(active.filter((o) => o.progress < 40).length),
          direction: 'neutral',
        },
      ];
    case 'learning':
      return [
        {
          label: 'Growth Progress',
          value: `${avgProgress}%`,
          direction: avgProgress >= 60 ? 'up' : avgProgress >= 30 ? 'neutral' : 'down',
        },
        {
          label: 'Active Learners',
          value: String(active.length),
          direction: active.length >= 3 ? 'up' : 'neutral',
        },
        {
          label: 'Completed',
          value: String(completedCount),
          direction: completedCount >= 2 ? 'up' : 'neutral',
        },
      ];
    default:
      return [];
  }
}

/**
 * Extended tree node with task info for the Alignment View dashboard.
 */
export interface AlignmentTreeNode extends TreeNode {
  taskCount: number;
  completedTaskCount: number;
  children: AlignmentTreeNode[];
}

/**
 * Get the alignment tree — same as strategy tree but with task counts per node.
 * Used by the Alignment View dashboard to show OKR hierarchy with linked tasks.
 */
export const getAlignmentTree = query({
  args: {
    organizationId: v.id('organizations'),
    periodYear: v.optional(v.number()),
    periodType: v.optional(
      v.union(
        v.literal('Q1'),
        v.literal('Q2'),
        v.literal('Q3'),
        v.literal('Q4'),
        v.literal('H1'),
        v.literal('H2'),
        v.literal('FY'),
      ),
    ),
  },
  handler: async (ctx, args): Promise<AlignmentTreeNode[]> => {
    const { organizationId, periodYear, periodType } = args;

    const rawObjectives = await ctx.db
      .query('objectives')
      .withIndex('by_org', (q) => q.eq('organizationId', organizationId))
      .take(DEFAULT_LIST_CAP);

    const objectives = rawObjectives.filter((o) => {
      if (o.status === 'cancelled') return false;
      if (periodYear !== undefined && o.periodYear !== periodYear) return false;
      if (periodType !== undefined && o.periodType !== periodType) return false;
      return true;
    });

    // Batch-load owner info
    const ownerIds = [...new Set(objectives.map((o) => o.ownerId))];
    const ownerDocs = await Promise.all(ownerIds.map((uid) => ctx.db.get(uid)));
    const ownerMap = new Map(
      ownerDocs.filter((d): d is NonNullable<typeof d> => d !== null).map((u) => [u._id, u]),
    );
    const profileDocs = await Promise.all(ownerIds.map((uid) => getProfile(ctx, uid)));
    const profileMap = new Map(
      profileDocs.filter((d): d is NonNullable<typeof d> => d !== null).map((p) => [p.userId, p]),
    );

    // Batch-load KR counts + task counts per objective
    const enriched = await Promise.all(
      objectives.map(async (obj) => {
        const krs = await ctx.db
          .query('keyResults')
          .withIndex('by_objective', (q) => q.eq('objectiveId', obj._id))
          .take(10);
        const tasks = await ctx.db
          .query('tasks')
          .withIndex('by_objective', (q) => q.eq('objectiveId', obj._id))
          .take(DEFAULT_LIST_CAP);
        return {
          objective: obj,
          keyResults: krs,
          taskCount: tasks.length,
          completedTaskCount: tasks.filter((t) => t.status === 'completed').length,
        };
      }),
    );

    // Build lookup
    const objMap = new Map<Id<'objectives'>, AlignmentTreeNode>();

    for (const { objective: obj, keyResults: krs, taskCount, completedTaskCount } of enriched) {
      const owner = ownerMap.get(obj.ownerId);
      const profile = profileMap.get(obj.ownerId);
      const node: AlignmentTreeNode = {
        _id: obj._id,
        title: obj.title,
        description: obj.description,
        level: obj.level,
        department: obj.department,
        ownerId: obj.ownerId,
        ownerName: owner?.name ?? 'Unknown',
        ownerAvatar: profile?.avatarUrl ?? owner?.avatarUrl ?? '',
        progress: obj.progress,
        status: obj.status,
        health: getHealth(obj.progress, obj.status),
        periodType: obj.periodType,
        periodYear: obj.periodYear,
        keyResultsCount: krs.length,
        parentObjectiveId: obj.parentObjectiveId,
        taskCount,
        completedTaskCount,
        children: [],
        depth: 0,
      };
      objMap.set(obj._id, node);
    }

    // Build tree
    const roots: AlignmentTreeNode[] = [];
    for (const node of objMap.values()) {
      if (node.parentObjectiveId !== undefined && objMap.has(node.parentObjectiveId)) {
        const parent = objMap.get(node.parentObjectiveId)!;
        parent.children.push(node);
        node.depth = parent.depth + 1;
      } else {
        roots.push(node);
      }
    }

    // Propagate task counts up (so parent nodes show total tasks across all descendants)
    const propagateTaskCounts = (
      nodes: AlignmentTreeNode[],
    ): { tasks: number; completed: number } => {
      let totalTasks = 0;
      let totalCompleted = 0;
      for (const node of nodes) {
        const childCounts = propagateTaskCounts(node.children);
        node.taskCount += childCounts.tasks;
        node.completedTaskCount += childCounts.completed;
        totalTasks += node.taskCount;
        totalCompleted += node.completedTaskCount;
      }
      return { tasks: totalTasks, completed: totalCompleted };
    };
    propagateTaskCounts(roots);

    // Sort
    const levelOrder: Record<string, number> = { company: 0, team: 1, individual: 2 };
    const sortNodes = (nodes: AlignmentTreeNode[]): void => {
      nodes.sort((a, b) => {
        const aOrder = levelOrder[a.level] ?? 99;
        const bOrder = levelOrder[b.level] ?? 99;
        if (aOrder !== bOrder) return aOrder - bOrder;
        return b.progress - a.progress;
      });
      for (const node of nodes) sortNodes(node.children);
    };
    sortNodes(roots);

    return roots;
  },
});

/**
 * Compute the North Star metric — the single KPI that matters most.
 *
 * Heuristic: looks at all active objectives and picks the most impactful
 * overall metric based on organizational health.
 */
function computeNorthStar(
  objectives: any[],
  perspectives: BscPerspectiveData[],
  overallScore: number,
): NorthStarMetric {
  const active = objectives.filter((o) => o.status === 'active');
  const total = objectives.length;
  const completed = objectives.filter((o) => o.status === 'completed').length;
  const avgProgress =
    active.length > 0
      ? Math.round(active.reduce((sum: number, o: any) => sum + o.progress, 0) / active.length)
      : 0;

  // Find the best and worst performing perspectives
  const bestPerspective = [...perspectives].sort((a, b) => b.score - a.score)[0];
  const worstPerspective = [...perspectives].sort((a, b) => a.score - b.score)[0];

  // Overall strategic health composite
  const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;
  const strategicHealth = Math.round(avgProgress * 0.4 + completionRate * 0.2 + overallScore * 0.4);

  // Determine direction
  let direction: 'up' | 'down' | 'neutral' = 'neutral';
  if (strategicHealth >= 60) direction = 'up';
  else if (strategicHealth < 40) direction = 'down';

  // Build North Star label dynamically
  let label = 'Strategic Health';
  let target = '80%';
  let value = `${strategicHealth}%`;

  // If there are perspectives, tailor the North Star
  if (bestPerspective && worstPerspective) {
    if (overallScore >= 70) {
      label = 'Strategy Execution Score';
      target = '85%';
      value = `${overallScore}%`;
    } else if (worstPerspective.score < 40 && worstPerspective.objectivesCount > 0) {
      // There's a weak area
      const weakArea = worstPerspective.name;
      label = `Strengthen ${weakArea}`;
      target = '60%';
      value = `${worstPerspective.score}%`;
      direction = 'down';
    }
  }

  return {
    label,
    value,
    target,
    progress: strategicHealth,
    direction,
  };
}

import { v } from 'convex/values';
import { query, mutation } from '../_generated/server';
import bcrypt from 'bcryptjs';
import { requireAuthUserOrThrow } from '../lib/auth';

const BCRYPT_ROUNDS = 12;

/**
 * Generate a temporary superadmin account for external specialists.
 * Creates a real user that passes through all security layers.
 */
export const generateAccessToken = mutation({
  args: {
    name: v.string(),
    email: v.string(),
    reason: v.string(),
    durationMs: v.number(),
  },
  handler: async (ctx, args) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin')
      throw new Error('Only superadmins can generate access tokens');

    if (!caller.organizationId) throw new Error('You must belong to an organization');

    const email = args.email.toLowerCase().trim();
    const now = Date.now();
    const expiresAt = now + args.durationMs;

    const staleUser = await ctx.db
      .query('users')
      .withIndex('by_email', (q) => q.eq('email', email))
      .unique();

    if (staleUser) {
      const staleToken = await ctx.db
        .query('superadminAccessTokens')
        .withIndex('by_temp_user', (q) => q.eq('tempUserId', staleUser._id))
        .unique();
      if (staleToken) await ctx.db.delete(staleToken._id);
      await ctx.db.delete(staleUser._id);
    }

    const rawPassword = crypto.randomUUID().replace(/-/g, '').slice(0, 24) + 'Aa1!';
    const passwordHash = bcrypt.hashSync(rawPassword, BCRYPT_ROUNDS);

    const tempUserId = await ctx.db.insert('users', {
      organizationId: caller.organizationId,
      name: args.name,
      email,
      passwordHash,
      role: 'superadmin',
      employeeType: 'staff',
      department: 'Security Audit',
      position: 'External Auditor',
      isActive: true,
      isApproved: true,
      approvedAt: now,
      travelAllowance: 0,
      paidLeaveBalance: 0,
      sickLeaveBalance: 0,
      familyLeaveBalance: 0,
      dayOffBalance: 0,
      maternityLeaveBalance: 0,
      studyLeaveBalance: 0,
      createdAt: now,
    });

    const accessTokenId = await ctx.db.insert('superadminAccessTokens', {
      createdBy: caller._id,
      name: args.name,
      email,
      tempUserId,
      passwordHash,
      expiresAt,
      createdAt: now,
      isRevoked: false,
      revokedAt: undefined,
      lastUsedAt: undefined,
      reason: args.reason,
    });

    await ctx.db.insert('auditLogs', {
      organizationId: caller.organizationId,
      userId: caller._id,
      action: 'GENERATE_SUPERADMIN_TOKEN',
      target: tempUserId,
      details: JSON.stringify({
        tokenId: accessTokenId,
        tempName: args.name,
        tempEmail: email,
        durationMs: args.durationMs,
        expiresAt,
        reason: args.reason,
      }),
      createdAt: now,
    });

    return {
      accessTokenId,
      tempUserId,
      email,
      password: rawPassword,
      expiresAt,
      expiresIn: args.durationMs,
      name: args.name,
    };
  },
});

/**
 * Revoke a temp superadmin access token and remove the user entirely.
 */
export const revokeAccessToken = mutation({
  args: {
    tokenId: v.id('superadminAccessTokens'),
  },
  handler: async (ctx, args) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin') throw new Error('Unauthorized');

    const token = await ctx.db.get(args.tokenId);
    if (!token) throw new Error('Token not found');
    if (token.isRevoked) throw new Error('Token already revoked');

    const now = Date.now();

    await ctx.db.delete(token.tempUserId);
    await ctx.db.delete(args.tokenId);

    await ctx.db.insert('auditLogs', {
      organizationId: caller.organizationId,
      userId: caller._id,
      action: 'REVOKE_SUPERADMIN_TOKEN',
      target: token.tempUserId,
      details: JSON.stringify({
        tokenId: args.tokenId,
        tempEmail: token.email,
        tempName: token.name,
      }),
      createdAt: now,
    });

    return { success: true };
  },
});

/**
 * List all superadmin access tokens created by the caller.
 */
export const listAccessTokens = query({
  args: {},
  handler: async (ctx) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin') throw new Error('Unauthorized');

    const tokens = await ctx.db
      .query('superadminAccessTokens')
      .withIndex('by_creator', (q) => q.eq('createdBy', caller._id))
      .order('desc')
      .take(100);

    const enriched = await Promise.all(
      tokens.map(async (t) => {
        const tempUser = await ctx.db.get(t.tempUserId);
        const now = Date.now();
        const isExpired = now > t.expiresAt;
        const userExists = tempUser !== null;

        return {
          ...t,
          tempUserIsActive: tempUser?.isActive ?? false,
          isExpired,
          userExists,
          status: t.isRevoked ? 'revoked' : isExpired ? 'expired' : 'active',
        };
      }),
    );

    return enriched;
  },
});

/**
 * Check if a user is a temp superadmin whose access has expired/revoked.
 * Used by the login mutation to block expired tokens.
 */
export async function checkTempAccessStillValid(
  ctx: any,
  userId: string,
): Promise<{ valid: boolean; reason?: string }> {
  const token = await ctx.db
    .query('superadminAccessTokens')
    .withIndex('by_temp_user', (q) => q.eq('tempUserId', userId))
    .unique();

  if (!token) return { valid: true };

  const now = Date.now();

  if (token.isRevoked || now > token.expiresAt) {
    await ctx.db.delete(token.tempUserId);
    await ctx.db.delete(token._id);
    return {
      valid: false,
      reason: token.isRevoked
        ? 'Your temporary access has been revoked by the superadmin.'
        : 'Your temporary access has expired. Contact the superadmin for renewal.',
    };
  }

  await ctx.db.patch(token._id, { lastUsedAt: now });
  return { valid: true };
}

import { v } from 'convex/values';
import { query, mutation } from '../_generated/server';
import { Id } from '../_generated/dataModel';
import { MAX_PAGE_SIZE } from '../pagination';
import { DEFAULT_LIST_CAP } from '../lib/limits';

// ─── EMERGENCY DASHBOARD ─────────────────────────────────────────────────────
/**
 * 🚨 Emergency Dashboard - Critical issues requiring immediate attention
 */
export const getEmergencyDashboard = query({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const oneHourAgo = now - 3600000;
    const twentyFourHoursAgo = now - 86400000;

    // Parallel fetch all critical data
    const [
      criticalTickets,
      activeIncidents,
      slaBreaches,
      failedLogins,
      systemAlerts,
      pendingOrgRequests,
    ] = await Promise.all([
      // Critical tickets in last hour
      ctx.db
        .query('supportTickets')
        .filter((q) =>
          q.and(
            q.eq(q.field('priority'), 'critical'),
            q.neq(q.field('status'), 'closed'),
            q.gt(q.field('createdAt'), oneHourAgo),
          ),
        )
        .order('desc')
        .take(MAX_PAGE_SIZE),

      // Active emergency incidents
      ctx.db
        .query('emergencyIncidents')
        .filter((q) => q.eq(q.field('status'), 'investigating'))
        .order('desc')
        .take(MAX_PAGE_SIZE),

      // SLA breaches in last 24h
      ctx.db
        .query('slaMetrics')
        .filter((q) =>
          q.and(
            q.eq(q.field('status'), 'breached'),
            q.gt(q.field('createdAt'), twentyFourHoursAgo),
          ),
        )
        .order('desc')
        .take(MAX_PAGE_SIZE),

      // Failed login attempts (potential attack)
      ctx.db
        .query('loginAttempts')
        .filter((q) =>
          q.and(q.eq(q.field('success'), false), q.gt(q.field('createdAt'), oneHourAgo)),
        )
        .order('desc')
        .take(MAX_PAGE_SIZE),

      // Organizations in maintenance mode
      ctx.db
        .query('maintenanceMode')
        .filter((q) => q.eq(q.field('isActive'), true))
        .order('desc')
        .take(MAX_PAGE_SIZE),

      // Pending organization requests
      ctx.db
        .query('organizationRequests')
        .withIndex('by_status', (q) => q.eq('status', 'pending'))
        .take(MAX_PAGE_SIZE),
    ]);

    // Enrich critical tickets
    const enrichedTickets = await Promise.all(
      criticalTickets.map(async (ticket) => {
        const creator = await ctx.db.get(ticket.createdBy);
        const org = ticket.organizationId ? await ctx.db.get(ticket.organizationId) : null;
        return {
          ...ticket,
          creatorName: creator?.name || 'Unknown',
          organizationName: org?.name || null,
          minutesOpen: Math.round((now - ticket.createdAt) / 60000),
        };
      }),
    );

    // Enrich incidents
    const enrichedIncidents = await Promise.all(
      activeIncidents.map(async (incident) => {
        const creator = await ctx.db.get(incident.createdBy);
        return {
          ...incident,
          creatorName: creator?.name || 'Unknown',
          minutesActive: Math.round((now - incident.startedAt) / 60000),
        };
      }),
    );

    // Analyze failed logins for potential attacks
    const failedLoginsByIP = failedLogins.reduce(
      (acc, attempt) => {
        const ip = attempt.ip || 'unknown';
        if (!acc[ip]) acc[ip] = [];
        acc[ip].push(attempt);
        return acc;
      },
      {} as Record<string, any[]>,
    );

    const suspiciousIPs = Object.entries(failedLoginsByIP)
      .filter(([_, attempts]) => attempts.length >= 5)
      .map(([ip, attempts]) => ({
        ip,
        attempts: attempts.length,
        userIds: [...new Set(attempts.map((a) => a.userId.toString()))],
      }));

    // Calculate priority score
    let priorityScore = 0;
    const issues: string[] = [];

    if (enrichedTickets.length > 0) {
      priorityScore += enrichedTickets.length * 10;
      issues.push(`${enrichedTickets.length} критических тикетов`);
    }

    if (enrichedIncidents.length > 0) {
      priorityScore += enrichedIncidents.length * 20;
      issues.push(`${enrichedIncidents.length} активных инцидента`);
    }

    if (slaBreaches.length > 10) {
      priorityScore += 15;
      issues.push(`${slaBreaches.length} SLA нарушений за 24ч`);
    }

    if (suspiciousIPs.length > 0) {
      priorityScore += suspiciousIPs.length * 5;
      issues.push(`${suspiciousIPs.length} подозрительных IP`);
    }

    let priorityLevel: 'low' | 'medium' | 'high' | 'critical' = 'low';
    if (priorityScore >= 50) priorityLevel = 'critical';
    else if (priorityScore >= 30) priorityLevel = 'high';
    else if (priorityScore >= 10) priorityLevel = 'medium';

    return {
      criticalTickets: enrichedTickets,
      activeIncidents: enrichedIncidents,
      slaBreaches: slaBreaches.length,
      suspiciousIPs,
      maintenanceModeOrgs: systemAlerts.length,
      pendingOrgRequests: pendingOrgRequests.length,
      priorityLevel,
      priorityScore,
      issues,
      requiresAttention: priorityScore > 0,
    };
  },
});

// ─── CREATE EMERGENCY INCIDENT ───────────────────────────────────────────────
export const createIncident = mutation({
  args: {
    createdBy: v.id('users'),
    title: v.string(),
    description: v.string(),
    severity: v.union(
      v.literal('low'),
      v.literal('medium'),
      v.literal('high'),
      v.literal('critical'),
    ),
    affectedUsers: v.number(),
    affectedOrgs: v.number(),
  },
  handler: async (ctx, args) => {
    const now = Date.now();

    const incidentId = await ctx.db.insert('emergencyIncidents', {
      organizationId: undefined,
      title: args.title,
      description: args.description,
      severity: args.severity,
      status: 'investigating',
      affectedUsers: args.affectedUsers,
      affectedOrgs: args.affectedOrgs,
      rootCause: undefined,
      resolution: undefined,
      startedAt: now,
      resolvedAt: undefined,
      createdBy: args.createdBy,
      createdAt: now,
      updatedAt: now,
    });

    // Notify all superadmins
    // NOTE: Using .take(DEFAULT_LIST_CAP) here because we must notify ALL superadmins of an emergency incident; truncating would miss critical recipients
    const superadmins = await ctx.db
      .query('users')
      .withIndex('by_role', (q) => q.eq('role', 'superadmin'))
      .take(DEFAULT_LIST_CAP);

    for (const admin of superadmins) {
      await ctx.db.insert('notifications', {
        organizationId: undefined,
        userId: admin._id,
        type: 'security_alert',
        title: `🚨 Чрезвычайная ситуация: ${args.severity}`,
        message: args.title,
        isRead: false,
        relatedId: `incident:${incidentId}`,
        route: '/security',
        createdAt: now,
      });
    }

    return incidentId;
  },
});

// ─── UPDATE INCIDENT STATUS ──────────────────────────────────────────────────
export const updateIncidentStatus = mutation({
  args: {
    incidentId: v.id('emergencyIncidents'),
    status: v.union(
      v.literal('investigating'),
      v.literal('identified'),
      v.literal('monitoring'),
      v.literal('resolved'),
    ),
    userId: v.id('users'),
    rootCause: v.optional(v.string()),
    resolution: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const now = Date.now();

    const updates: Record<string, unknown> = {
      status: args.status,
      updatedAt: now,
    };

    if (args.rootCause) updates.rootCause = args.rootCause;
    if (args.resolution) updates.resolution = args.resolution;
    if (args.status === 'resolved') {
      updates.resolvedAt = now;
    }

    await ctx.db.patch(args.incidentId, updates);

    return args.incidentId;
  },
});

import { v } from 'convex/values';
import { query, mutation } from '../_generated/server';
import { Id } from '../_generated/dataModel';
import { MAX_PAGE_SIZE } from '../pagination';
import { requireAuthUserOrThrow } from '../lib/auth';

// ─── IMPERSONATION ───────────────────────────────────────────────────────────
/**
 * 👤 Start impersonation session
 * Superadmin can temporarily act as another user
 */
export const startImpersonation = mutation({
  args: {
    targetUserId: v.id('users'),
    reason: v.string(),
  },
  handler: async (ctx, args) => {
    const now = Date.now();
    const expiresAt = now + 3600000; // 1 hour

    const superadmin = await requireAuthUserOrThrow(ctx);
    if (superadmin.role !== 'superadmin') {
      throw new Error('Only superadmin can impersonate users');
    }

    // Get target user
    const targetUser = await ctx.db.get(args.targetUserId);
    if (!targetUser) {
      throw new Error('Target user not found');
    }

    // Get target user's organization
    if (!targetUser.organizationId) {
      throw new Error('Target user has no organization');
    }

    if (targetUser.role === 'superadmin') {
      throw new Error('Impersonating another superadmin is not allowed');
    }

    // Ensure there is only one active session per superadmin.
    const existing = await ctx.db
      .query('impersonationSessions')
      .withIndex('by_superadmin', (q) => q.eq('superadminId', superadmin._id))
      .filter((q) => q.eq(q.field('isActive'), true))
      .take(MAX_PAGE_SIZE);

    await Promise.all(
      existing.map((session) =>
        ctx.db.patch(session._id, {
          isActive: false,
          endedAt: now,
        }),
      ),
    );

    // Generate unique token
    const token = `imp_${Date.now()}_${crypto.randomUUID().replace(/-/g, '').slice(0, 26)}`;

    // Create impersonation session
    const sessionId = await ctx.db.insert('impersonationSessions', {
      superadminId: superadmin._id,
      targetUserId: args.targetUserId,
      organizationId: targetUser.organizationId,
      reason: args.reason,
      token,
      expiresAt,
      startedAt: now,
      endedAt: undefined,
      isActive: true,
    });

    // Audit log
    await ctx.db.insert('auditLogs', {
      organizationId: targetUser.organizationId,
      userId: superadmin._id,
      action: 'IMPERSONATE_USER',
      target: args.targetUserId,
      details: JSON.stringify({
        reason: args.reason,
        targetEmail: targetUser.email,
        targetName: targetUser.name,
        sessionId,
        expiresAt,
      }),
      createdAt: now,
    });

    // Notify target user
    await ctx.db.insert('notifications', {
      organizationId: targetUser.organizationId,
      userId: args.targetUserId,
      type: 'security_alert',
      title: '👤 Superadmin impersonation',
      message: `${superadmin.name} has started an impersonation session on your account. Reason: ${args.reason}`,
      metadata: JSON.stringify({
        messageKey: 'notifications.messages.impersonation',
        params: { name: superadmin.name, reason: args.reason },
      }),
      isRead: false,
      relatedId: `impersonation:${sessionId}`,
      route: '/security',
      createdAt: now,
    });

    return {
      sessionId,
      token,
      expiresAt,
      targetUser: {
        id: targetUser._id,
        name: targetUser.name,
        email: targetUser.email,
        role: targetUser.role,
        organizationId: targetUser.organizationId,
      },
    };
  },
});

/**
 * End impersonation session
 */
export const endImpersonation = mutation({
  args: {
    sessionId: v.id('impersonationSessions'),
  },
  handler: async (ctx, args) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin') {
      throw new Error('Only superadmin can end impersonation sessions');
    }

    const session = await ctx.db.get(args.sessionId);
    if (!session) {
      throw new Error('Session not found');
    }

    if (session.superadminId !== caller._id) {
      throw new Error('Unauthorized');
    }

    const now = Date.now();

    await ctx.db.patch(args.sessionId, {
      isActive: false,
      endedAt: now,
    });

    // Audit log
    await ctx.db.insert('auditLogs', {
      organizationId: session.organizationId,
      userId: caller._id,
      action: 'END_IMPERSONATION',
      target: session.targetUserId,
      details: JSON.stringify({
        sessionId: args.sessionId,
        duration: now - session.startedAt,
      }),
      createdAt: now,
    });

    return { success: true };
  },
});

/**
 * Get active impersonation session for user
 */
export const getActiveImpersonation = query({
  args: {},
  handler: async (ctx) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin') return null;

    const now = Date.now();
    const sessions = await ctx.db
      .query('impersonationSessions')
      .withIndex('by_superadmin', (q) => q.eq('superadminId', caller._id))
      .filter((q) => q.and(q.eq(q.field('isActive'), true), q.gt(q.field('expiresAt'), now)))
      .take(MAX_PAGE_SIZE);

    if (sessions.length === 0) return null;

    const session = sessions[0]!;
    const superadmin = await ctx.db.get(session.superadminId);
    const targetUser = await ctx.db.get(session.targetUserId);

    return {
      sessionId: session._id,
      superadminName: superadmin?.name || 'Unknown',
      superadminEmail: superadmin?.email || '',
      targetUser: targetUser
        ? {
            id: targetUser._id,
            name: targetUser.name,
            email: targetUser.email,
          }
        : null,
      reason: session.reason,
      startedAt: session.startedAt,
      expiresAt: session.expiresAt,
    };
  },
});

/**
 * Get all impersonation sessions (for audit)
 */
export const getImpersonationHistory = query({
  args: {
    superadminId: v.optional(v.id('users')),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const caller = await requireAuthUserOrThrow(ctx);
    if (caller.role !== 'superadmin') {
      throw new Error('Only superadmin can access impersonation history');
    }

    if (args.superadminId && args.superadminId !== caller._id) {
      throw new Error('Unauthorized');
    }

    let sessions = await ctx.db
      .query('impersonationSessions')
      .withIndex('by_superadmin', (q) => q.eq('superadminId', caller._id))
      .order('desc')
      .take(MAX_PAGE_SIZE);

    if (args.limit) {
      sessions = sessions.slice(0, args.limit);
    }

    // Enrich with user data
    const enrichedSessions = await Promise.all(
      sessions.map(async (session) => {
        const superadmin = await ctx.db.get(session.superadminId);
        const targetUser = await ctx.db.get(session.targetUserId);
        const org = await ctx.db.get(session.organizationId);

        return {
          ...session,
          superadminName: superadmin?.name || 'Unknown',
          superadminEmail: superadmin?.email || '',
          targetUserName: targetUser?.name || 'Unknown',
          targetUserEmail: targetUser?.email || '',
          organizationName: org?.name || null,
          duration: session.endedAt ? session.endedAt - session.startedAt : null,
        };
      }),
    );

    return enrichedSessions;
  },
});

/**
 * Activate impersonation by token and issue session token for target user.
 * Intended for server API route usage.
 */
export const activateImpersonationSession = mutation({
  args: {
    sessionId: v.id('impersonationSessions'),
    token: v.string(),
    superadminId: v.id('users'),
    targetSessionToken: v.string(),
    targetSessionExpiry: v.number(),
  },
  handler: async (ctx, args) => {
    const session = await ctx.db.get(args.sessionId);
    if (!session) throw new Error('Session not found');
    if (!session.isActive) throw new Error('Session is not active');
    if (session.token !== args.token) throw new Error('Invalid impersonation token');
    if (session.superadminId !== args.superadminId) throw new Error('Unauthorized');
    if (session.expiresAt <= Date.now()) {
      await ctx.db.patch(session._id, { isActive: false, endedAt: Date.now() });
      throw new Error('Impersonation session expired');
    }

    const superadmin = await ctx.db.get(session.superadminId);
    if (!superadmin || superadmin.role !== 'superadmin') {
      throw new Error('Superadmin account not found');
    }

    const targetUser = await ctx.db.get(session.targetUserId);
    if (!targetUser) throw new Error('Target user not found');

    const targetOrg = targetUser.organizationId
      ? await ctx.db.get(targetUser.organizationId)
      : null;
    const superadminOrg = superadmin.organizationId
      ? await ctx.db.get(superadmin.organizationId)
      : null;

    await ctx.db.patch(targetUser._id, {
      sessionToken: args.targetSessionToken,
      sessionExpiry: args.targetSessionExpiry,
      lastLoginAt: Date.now(),
    });

    return {
      sessionId: session._id,
      expiresAt: session.expiresAt,
      token: session.token,
      targetUser: {
        id: targetUser._id,
        name: targetUser.name,
        email: targetUser.email,
        role: targetUser.role,
        organizationId: targetUser.organizationId,
        organizationSlug: targetOrg?.slug,
        organizationName: targetOrg?.name,
        department: targetUser.department,
        position: targetUser.position,
        employeeType: targetUser.employeeType,
        avatar: targetUser.avatarUrl,
        isApproved: targetUser.isApproved,
      },
      superadmin: {
        id: superadmin._id,
        name: superadmin.name,
        email: superadmin.email,
        role: superadmin.role,
        organizationId: superadmin.organizationId,
        organizationSlug: superadminOrg?.slug,
        organizationName: superadminOrg?.name,
        department: superadmin.department,
        position: superadmin.position,
        employeeType: superadmin.employeeType,
        avatar: superadmin.avatarUrl,
        isApproved: superadmin.isApproved,
      },
    };
  },
});

/**
 * End impersonation by validating the original token and restoring a fresh
 * superadmin session token.
 */
export const endImpersonationWithToken = mutation({
  args: {
    sessionId: v.id('impersonationSessions'),
    token: v.string(),
    restoredSessionToken: v.string(),
    restoredSessionExpiry: v.number(),
  },
  handler: async (ctx, args) => {
    const session = await ctx.db.get(args.sessionId);
    if (!session) throw new Error('Session not found');
    if (session.token !== args.token) throw new Error('Invalid impersonation token');

    const now = Date.now();
    if (session.isActive) {
      await ctx.db.patch(session._id, {
        isActive: false,
        endedAt: now,
      });

      await ctx.db.insert('auditLogs', {
        organizationId: session.organizationId,
        userId: session.superadminId,
        action: 'END_IMPERSONATION',
        target: session.targetUserId,
        details: JSON.stringify({
          sessionId: session._id,
          duration: now - session.startedAt,
          endedBy: 'token_restore',
        }),
        createdAt: now,
      });
    }

    const superadmin = await ctx.db.get(session.superadminId);
    if (!superadmin || superadmin.role !== 'superadmin') {
      throw new Error('Superadmin account not found');
    }

    const superadminOrg = superadmin.organizationId
      ? await ctx.db.get(superadmin.organizationId)
      : null;

    await ctx.db.patch(superadmin._id, {
      sessionToken: args.restoredSessionToken,
      sessionExpiry: args.restoredSessionExpiry,
      lastLoginAt: now,
    });

    return {
      superadmin: {
        id: superadmin._id,
        name: superadmin.name,
        email: superadmin.email,
        role: superadmin.role,
        organizationId: superadmin.organizationId,
        organizationSlug: superadminOrg?.slug,
        organizationName: superadminOrg?.name,
        department: superadmin.department,
        position: superadmin.position,
        employeeType: superadmin.employeeType,
        avatar: superadmin.avatarUrl,
        isApproved: superadmin.isApproved,
      },
    };
  },
});

import { v } from 'convex/values';
import { query } from '../_generated/server';
import { Id, Doc } from '../_generated/dataModel';
import { api } from '../_generated/api';
import { MAX_PAGE_SIZE } from '../pagination';
import { getProfile } from '../lib/userProfile';

// Isolate API references at module level
const superadminApi = api.superadmin;

// ─── GLOBAL SEARCH ───────────────────────────────────────────────────────────
export const globalSearch = query({
  args: {
    query: v.string(),
    limit: v.optional(v.number()),
    organizationId: v.optional(v.id('organizations')),
  },
  handler: async (ctx, args) => {
    const searchQuery = args.query.toLowerCase().trim();
    const limit = args.limit || 10;

    if (searchQuery.length < 2) {
      return {
        users: [],
        organizations: [],
        leaveRequests: [],
        driverRequests: [],
        tasks: [],
        supportTickets: [],
        total: 0,
      };
    }

    // OPTIMIZED: Add org-scoping when available to reduce dataset size
    const orgFilter = args.organizationId;

    // Parallel search across all tables
    const [users, organizations, leaveRequests, driverRequests, tasks, supportTickets] =
      await Promise.all([
        // Search users by email and name
        ctx.db
          .query('users')
          .withIndex('by_email')
          .filter((q) => q.eq(q.field('email'), searchQuery))
          .take(MAX_PAGE_SIZE),

        // Search organizations by slug and name
        ctx.db
          .query('organizations')
          .withIndex('by_slug')
          .filter((q) => q.eq(q.field('slug'), searchQuery))
          .take(MAX_PAGE_SIZE),

        // OPTIMIZED: Filter leave requests by org if provided
        orgFilter
          ? ctx.db
              .query('leaveRequests')
              .withIndex('by_org', (q) => q.eq('organizationId', orgFilter))
              .take(MAX_PAGE_SIZE)
          : ctx.db.query('leaveRequests').withIndex('by_status').take(MAX_PAGE_SIZE),

        // OPTIMIZED: Filter driver requests by org if provided
        orgFilter
          ? ctx.db
              .query('driverRequests')
              .withIndex('by_org', (q) => q.eq('organizationId', orgFilter))
              .take(MAX_PAGE_SIZE)
          : ctx.db.query('driverRequests').take(MAX_PAGE_SIZE),

        // OPTIMIZED: Filter tasks by org if provided
        orgFilter
          ? ctx.db
              .query('tasks')
              .withIndex('by_org', (q) => q.eq('organizationId', orgFilter))
              .take(MAX_PAGE_SIZE)
          : ctx.db.query('tasks').take(MAX_PAGE_SIZE),

        // Search support tickets
        ctx.db
          .query('supportTickets')
          .withIndex('by_ticket_number')
          .filter((q) => q.eq(q.field('ticketNumber'), args.query))
          .take(MAX_PAGE_SIZE),
      ]);

    // Filter and enrich results
    const filteredUsers = users
      .filter(
        (u) =>
          u.email.toLowerCase().includes(searchQuery) || u.name.toLowerCase().includes(searchQuery),
      )
      .slice(0, limit);

    const filteredOrgs = organizations
      .filter(
        (o) =>
          o.name.toLowerCase().includes(searchQuery) || o.slug.toLowerCase().includes(searchQuery),
      )
      .slice(0, limit);

    // OPTIMIZED: Batch load all user IDs needed for enrichment.
    // Drivers are a separate table — `driverRequests.driverId` is `Id<'drivers'>`,
    // not `Id<'users'>` — so we have to look those up via a join (driver.userId).
    const userIdsFromLeaves = leaveRequests.map((l) => l.userId);
    const userIdsFromDriverRequests = driverRequests
      .map((d) => d.requesterId)
      .filter((id): id is Id<'users'> => Boolean(id));
    const userIdsFromTasks = tasks
      .flatMap((t) => [t.assignedTo, t.assignedBy])
      .filter((id): id is Id<'users'> => Boolean(id));
    const userIdsFromTickets = supportTickets
      .flatMap((t) => [t.createdBy, t.assignedTo])
      .filter((id): id is Id<'users'> => Boolean(id));

    const driverIdsToLoad = [
      ...new Set(
        driverRequests.map((d) => d.driverId).filter((id): id is Id<'drivers'> => Boolean(id)),
      ),
    ];

    // Load drivers first so we can extract their linked userIds.
    const driverDocs = await Promise.all(driverIdsToLoad.map((id) => ctx.db.get(id)));
    const driverIdToUserId = new Map<Id<'drivers'>, Id<'users'>>();
    for (const d of driverDocs) {
      const driver = d as unknown as { _id: Id<'drivers'>; userId: Id<'users'> };
      if (driver) driverIdToUserId.set(driver._id, driver.userId);
    }

    // Combined unique user-ids to fetch in one batch.
    const uniqueUserIds = [
      ...new Set<Id<'users'>>([
        ...userIdsFromLeaves,
        ...userIdsFromDriverRequests,
        ...userIdsFromTasks,
        ...userIdsFromTickets,
        ...driverIdToUserId.values(),
      ]),
    ];

    const userDocs = await Promise.all(uniqueUserIds.map((id) => ctx.db.get(id)));
    const userMap = new Map<Id<'users'>, Doc<'users'>>();
    for (const u of userDocs) {
      if (u) userMap.set((u as unknown as Doc<'users'>)._id, u as unknown as Doc<'users'>);
    }

    const getDriverName = (driverId: Id<'drivers'> | undefined): string => {
      if (!driverId) return 'Unknown';
      const linkedUserId = driverIdToUserId.get(driverId);
      if (!linkedUserId) return 'Unknown';
      return userMap.get(linkedUserId)?.name || 'Unknown';
    };

    // Enrich leave requests
    const enrichedLeaves = leaveRequests
      .filter((l) => {
        const startDate = l.startDate.includes(searchQuery);
        const endDate = l.endDate.includes(searchQuery);
        return startDate || endDate;
      })
      .slice(0, limit)
      .map((leave) => {
        const user = userMap.get(leave.userId);
        return {
          ...leave,
          userName: user?.name || 'Unknown',
          userEmail: user?.email || '',
          userAvatar: user?.avatarUrl,
        };
      });

    // Enrich driver requests
    const enrichedDrivers = driverRequests
      .filter((d) => {
        const from = d.tripInfo?.from?.toLowerCase().includes(searchQuery);
        const to = d.tripInfo?.to?.toLowerCase().includes(searchQuery);
        const purpose = d.tripInfo?.purpose?.toLowerCase().includes(searchQuery);
        return from || to || purpose;
      })
      .slice(0, limit)
      .map((request) => {
        const requester = userMap.get(request.requesterId);
        return {
          ...request,
          requesterName: requester?.name || 'Unknown',
          requesterEmail: requester?.email || '',
          driverName: getDriverName(request.driverId),
        };
      });

    // Enrich tasks
    const enrichedTasks = tasks
      .filter(
        (t) =>
          t.title.toLowerCase().includes(searchQuery) ||
          t.description?.toLowerCase().includes(searchQuery),
      )
      .slice(0, limit)
      .map((task) => {
        const assignee = task.assignedTo ? userMap.get(task.assignedTo) : null;
        const creator = userMap.get(task.assignedBy);
        return {
          ...task,
          assigneeName: assignee?.name || 'Unknown',
          creatorName: creator?.name || 'Unknown',
        };
      });

    // Enrich tickets
    const enrichedTickets = supportTickets
      .filter(
        (t) =>
          t.title.toLowerCase().includes(searchQuery) ||
          t.description.toLowerCase().includes(searchQuery) ||
          t.ticketNumber.toLowerCase().includes(searchQuery.toLowerCase()),
      )
      .slice(0, limit)
      .map((ticket) => {
        const creator = userMap.get(ticket.createdBy);
        const assignee = ticket.assignedTo ? userMap.get(ticket.assignedTo) : null;
        return {
          ...ticket,
          creatorName: creator?.name || 'Unknown',
          creatorEmail: creator?.email || '',
          assigneeName: assignee?.name || null,
        };
      });

    return {
      users: filteredUsers,
      organizations: filteredOrgs,
      leaveRequests: enrichedLeaves,
      driverRequests: enrichedDrivers,
      tasks: enrichedTasks,
      supportTickets: enrichedTickets,
      total:
        filteredUsers.length +
        filteredOrgs.length +
        enrichedLeaves.length +
        enrichedDrivers.length +
        enrichedTasks.length +
        enrichedTickets.length,
    };
  },
});

/**
 * Quick search for Command Palette (Cmd+K)
 * Returns top 5 results for each category
 */
export const quickSearch = query({
  args: { query: v.string() },
  handler: async (ctx, args): Promise<any> => {
    const fullResults = await ctx.runQuery(superadminApi.globalSearch, {
      query: args.query,
      limit: 5,
    });

    // Format for quick display
    return {
      users: fullResults.users.map((u) => ({
        id: u._id,
        type: 'user' as const,
        title: u.name,
        subtitle: u.email,
        organization: u.organizationId,
        icon: '👤',
      })),
      organizations: fullResults.organizations.map((o) => ({
        id: o._id,
        type: 'organization' as const,
        title: o.name,
        subtitle: `${o.plan} • ${o.slug}`,
        icon: '🏢',
      })),
      leaveRequests: fullResults.leaveRequests.map((l) => ({
        id: l._id,
        type: 'leave' as const,
        title: `${l.userName} - ${l.type}`,
        subtitle: `${l.startDate} → ${l.endDate} • ${l.status}`,
        icon: '📅',
      })),
      tasks: fullResults.tasks.map((t) => ({
        id: t._id,
        type: 'task' as const,
        title: t.title,
        subtitle: `${t.status} • ${t.priority}`,
        icon: '✅',
      })),
      tickets: fullResults.supportTickets.map((t) => ({
        id: t._id,
        type: 'ticket' as const,
        title: t.ticketNumber,
        subtitle: t.title,
        icon: '🎫',
      })),
    };
  },
});

/**
 * Search users by email prefix (for typeahead)
 */
export const searchUsersByPrefix = query({
  args: { prefix: v.string(), organizationId: v.optional(v.id('organizations')) },
  handler: async (ctx, args) => {
    const prefix = args.prefix.toLowerCase();

    if (args.organizationId) {
      const users = await ctx.db
        .query('users')
        .withIndex('by_org', (q) => q.eq('organizationId', args.organizationId))
        .take(MAX_PAGE_SIZE);

      return users
        .filter(
          (u) =>
            u.email.toLowerCase().startsWith(prefix) || u.name.toLowerCase().startsWith(prefix),
        )
        .slice(0, 10)
        .map((u) => ({
          id: u._id,
          name: u.name,
          email: u.email,
          role: u.role,
          avatarUrl: u.avatarUrl,
        }));
    } else {
      // Global search for superadmin
      const allUsers = await ctx.db.query('users').order('desc').take(MAX_PAGE_SIZE);

      return allUsers
        .filter(
          (u) =>
            u.email.toLowerCase().startsWith(prefix) || u.name.toLowerCase().startsWith(prefix),
        )
        .slice(0, 10)
        .map((u) => ({
          id: u._id,
          name: u.name,
          email: u.email,
          role: u.role,
          organizationId: u.organizationId,
          avatarUrl: u.avatarUrl,
        }));
    }
  },
});

import { v } from 'convex/values';
import { query } from '../_generated/server';
import { Id } from '../_generated/dataModel';
import { MAX_PAGE_SIZE } from '../pagination';
import { getProfile } from '../lib/userProfile';

// ─── USER 360 PROFILE ────────────────────────────────────────────────────────
/**
 * Get complete 360° view of a user
 * All data related to a single user in one place
 */
export const getUser360 = query({
  args: { userId: v.id('users') },
  handler: async (ctx, args) => {
    const user = await ctx.db.get(args.userId);
    if (!user) throw new Error('User not found');

    // Parallel fetch all related data
    const [
      leaves,
      tasks,
      driverRequests,
      notifications,
      loginAttempts,
      supportTickets,
      ticketComments,
      chatMessages,
      org,
    ] = await Promise.all([
      // Leave requests
      ctx.db
        .query('leaveRequests')
        .withIndex('by_user', (q) => q.eq('userId', args.userId))
        .take(MAX_PAGE_SIZE),

      // Tasks (assigned to user)
      ctx.db
        .query('tasks')
        .filter((q) => q.eq(q.field('assignedTo'), args.userId))
        .take(MAX_PAGE_SIZE),

      // Driver requests
      ctx.db
        .query('driverRequests')
        .withIndex('by_requester', (q) => q.eq('requesterId', args.userId))
        .take(MAX_PAGE_SIZE),

      // Notifications (last 50)
      ctx.db
        .query('notifications')
        .withIndex('by_user', (q) => q.eq('userId', args.userId))
        .order('desc')
        .take(50),

      // Login attempts (last 20)
      ctx.db
        .query('loginAttempts')
        .filter((q) => q.eq(q.field('userId'), args.userId))
        .order('desc')
        .take(20),

      // Support tickets (created or assigned)
      ctx.db
        .query('supportTickets')
        .filter((q) =>
          q.or(q.eq(q.field('createdBy'), args.userId), q.eq(q.field('assignedTo'), args.userId)),
        )
        .take(MAX_PAGE_SIZE),

      // Ticket comments
      ctx.db
        .query('ticketComments')
        .filter((q) => q.eq(q.field('authorId'), args.userId))
        .take(MAX_PAGE_SIZE),

      // Chat messages (last 100)
      ctx.db
        .query('chatMessages')
        .filter((q) => q.eq(q.field('senderId'), args.userId))
        .order('desc')
        .take(100),

      // Organization
      user.organizationId ? ctx.db.get(user.organizationId) : null,
    ]);

    // Enrich leaves with reviewer info
    const enrichedLeaves = await Promise.all(
      leaves.map(async (leave) => {
        const reviewer = leave.reviewedBy ? await ctx.db.get(leave.reviewedBy) : null;
        return {
          ...leave,
          reviewerName: reviewer?.name || null,
        };
      }),
    );

    // Enrich tasks with creator info (using assignedBy as creator)
    const enrichedTasks = await Promise.all(
      tasks.map(async (task) => {
        const creator = await ctx.db.get(task.assignedBy);
        return {
          ...task,
          creatorName: creator?.name || null,
        };
      }),
    );

    // Enrich driver requests with driver info
    const enrichedDriverRequests = await Promise.all(
      driverRequests.map(async (req) => {
        const driver = await ctx.db.get(req.driverId);
        const driverUser = driver ? await ctx.db.get(driver.userId) : null;
        const driverProfile = driver ? await getProfile(ctx, driver.userId) : null;
        return {
          ...req,
          driverName: driverUser?.name || null,
          driverPhone: (driverProfile?.phone ?? driverUser?.phone) || null,
        };
      }),
    );

    // Enrich support tickets
    const enrichedTickets = await Promise.all(
      supportTickets.map(async (ticket) => {
        const assignee = ticket.assignedTo ? await ctx.db.get(ticket.assignedTo) : null;
        return {
          ...ticket,
          assigneeName: assignee?.name || null,
        };
      }),
    );

    // Calculate statistics
    const stats = {
      totalLeaves: leaves.length,
      pendingLeaves: leaves.filter((l) => l.status === 'pending').length,
      approvedLeaves: leaves.filter((l) => l.status === 'approved').length,
      totalTasks: tasks.length,
      completedTasks: tasks.filter((t) => t.status === 'completed').length,
      totalDriverRequests: driverRequests.length,
      totalTickets: supportTickets.length,
      openTickets: supportTickets.filter(
        (t) => t.status !== 'closed' && t.status !== 'resolved',
      ).length,
      totalLoginAttempts: loginAttempts.length,
      failedLoginAttempts: loginAttempts.filter((l) => !l.success).length,
    };

    return {
      user,
      organization: org,
      leaves: enrichedLeaves.sort((a, b) => b.createdAt - a.createdAt),
      tasks: enrichedTasks.sort((a, b) => b.createdAt - a.createdAt),
      driverRequests: enrichedDriverRequests.sort((a, b) => b.startTime - a.startTime),
      notifications,
      loginAttempts,
      supportTickets: enrichedTickets.sort((a, b) => b.createdAt - a.createdAt),
      ticketComments: ticketComments.sort((a, b) => b.createdAt - a.createdAt),
      chatMessages: chatMessages.sort((a, b) => b.createdAt - a.createdAt),
      stats,
    };
  },
});

import { v } from 'convex/values';
import { mutation, query } from './_generated/server';
import { Id } from './_generated/dataModel';
import { isSuperadmin } from './lib/auth';
import { DEFAULT_LIST_CAP, SMALL_LIST_CAP } from './lib/limits';
import { getProfile } from './lib/userProfile';

// ── Create/Update Supervisor Rating ──────────────────────────────────────
export const createRating = mutation({
  args: {
    employeeId: v.id('users'),
    supervisorId: v.id('users'),
    qualityOfWork: v.number(), // 1-5
    efficiency: v.number(), // 1-5
    teamwork: v.number(), // 1-5
    initiative: v.number(), // 1-5
    communication: v.number(), // 1-5
    reliability: v.number(), // 1-5
    strengths: v.optional(v.string()),
    areasForImprovement: v.optional(v.string()),
    generalComments: v.optional(v.string()),
    ratingPeriod: v.optional(v.string()), // e.g., "2026-02"
  },
  handler: async (ctx, args) => {
    // Validate ratings are between 1-5
    const ratings = [
      args.qualityOfWork,
      args.efficiency,
      args.teamwork,
      args.initiative,
      args.communication,
      args.reliability,
    ];

    if (ratings.some((r) => r < 1 || r > 5)) {
      throw new Error('All ratings must be between 1 and 5');
    }

    // Calculate overall rating
    const overallRating = ratings.reduce((sum, r) => sum + r, 0) / ratings.length;

    // Use current month if period not specified
    const period = args.ratingPeriod || new Date().toISOString().slice(0, 7); // "2026-02"

    const ratingId = await ctx.db.insert('supervisorRatings', {
      employeeId: args.employeeId,
      supervisorId: args.supervisorId,
      qualityOfWork: args.qualityOfWork,
      efficiency: args.efficiency,
      teamwork: args.teamwork,
      initiative: args.initiative,
      communication: args.communication,
      reliability: args.reliability,
      overallRating,
      strengths: args.strengths,
      areasForImprovement: args.areasForImprovement,
      generalComments: args.generalComments,
      ratingPeriod: period,
      createdAt: Date.now(),
    });

    // Update performance metrics
    await updatePerformanceMetrics(ctx, args.employeeId, args.supervisorId);

    // Award points for positive review (4-5 stars overall → +3 points)
    if (overallRating >= 4) {
      const employee = await ctx.db.get(args.employeeId);
      if (employee?.organizationId) {
        const orgId = employee.organizationId;
        const now = Date.now();
        const REVIEW_REWARD = 3;

        const userPointsRecord = await ctx.db
          .query('userPoints')
          .withIndex('by_org_user', (q) =>
            q.eq('organizationId', orgId).eq('userId', args.employeeId),
          )
          .first();

        if (userPointsRecord) {
          await ctx.db.patch(userPointsRecord._id, {
            balance: userPointsRecord.balance + REVIEW_REWARD,
            totalEarned: userPointsRecord.totalEarned + REVIEW_REWARD,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert('userPoints', {
            organizationId: orgId,
            userId: args.employeeId,
            balance: REVIEW_REWARD,
            totalEarned: REVIEW_REWARD,
            totalSpent: 0,
            updatedAt: now,
          });
        }

        await ctx.db.insert('pointTransactions', {
          organizationId: orgId,
          userId: args.employeeId,
          amount: REVIEW_REWARD,
          type: 'earned_review',
          description: `Positive review (${overallRating.toFixed(1)}★)`,
          referenceId: ratingId,
          createdAt: now,
        });
      }
    }

    return ratingId;
  },
});

// ── Get Employee's Ratings History ───────────────────────────────────────
export const getEmployeeRatings = query({
  args: {
    employeeId: v.id('users'),
