// ── Helper: Update Performance Metrics ───────────────────────────────────
async function updatePerformanceMetrics(ctx: any, employeeId: Id<'users'>, updatedBy: Id<'users'>) {
  // Get average ratings
  const ratings = await ctx.db
    .query('supervisorRatings')
    .withIndex('by_employee', (q) => q.eq('employeeId', employeeId))
    .take(SMALL_LIST_CAP);

  if (ratings.length === 0) return;

  const recent = ratings.slice(-3); // Last 3 ratings
  const count = recent.length;

  const avgQuality = recent.reduce((sum: number, r: any) => sum + r.qualityOfWork, 0) / count;
  const avgEfficiency = recent.reduce((sum: number, r: any) => sum + r.efficiency, 0) / count;
  const avgTeamwork = recent.reduce((sum: number, r: any) => sum + r.teamwork, 0) / count;

  // Convert 1-5 scale to 0-5 scale for kpiScore
  const kpiScore = recent.reduce((sum: number, r: any) => sum + r.overallRating, 0) / count;

  // Get or create performance metrics
  const existing = await ctx.db
    .query('performanceMetrics')
    .withIndex('by_user', (q) => q.eq('userId', employeeId))
    .first();

  const metricsData = {
    kpiScore,
    projectCompletion: avgQuality * 20, // Convert to percentage
    deadlineAdherence: avgEfficiency * 20,
    teamworkRating: avgTeamwork,
    communicationScore: recent.reduce((sum: number, r: any) => sum + r.communication, 0) / count,
  };

  if (existing) {
    await ctx.db.patch(existing._id, {
      ...metricsData,
      updatedBy,
    });
  } else {
    await ctx.db.insert('performanceMetrics', {
      userId: employeeId,
      updatedBy,
      ...metricsData,
      punctualityScore: 75, // Default
      absenceRate: 0,
      lateArrivals: 0,
      conflictIncidents: 0,
      createdAt: Date.now(),
    });
  }
}

// ── Get All Employees Needing Rating ─────────────────────────────────────
export const getEmployeesNeedingRating = query({
  args: {
    supervisorId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const supervisor = await ctx.db.get(args.supervisorId);
    if (!supervisor) throw new Error('Supervisor not found');

    const userIsSuperadmin = isSuperadmin(supervisor);

    const currentPeriod = new Date().toISOString().slice(0, 7);

    // Get active employees scoped to org
    let allUsers;
    if (!userIsSuperadmin) {
      if (!supervisor.organizationId) {
        throw new Error('User does not belong to an organization');
      }
      allUsers = await ctx.db
        .query('users')
        .withIndex('by_org', (q) => q.eq('organizationId', supervisor.organizationId))
        .take(DEFAULT_LIST_CAP);
    } else {
      allUsers = await ctx.db.query('users').take(DEFAULT_LIST_CAP);
    }

    // Exclude superadmins and admins from rating list
    const activeEmployees = allUsers.filter(
      (u) => u.isActive && u.role !== 'admin' && u.role !== 'superadmin',
    );

    // Check which ones don't have a rating this month
    const needsRating = await Promise.all(
      activeEmployees.map(async (employee) => {
        const rating = await ctx.db
          .query('supervisorRatings')
          .withIndex('by_employee', (q) => q.eq('employeeId', employee._id))
          .order('desc')
          .first();

        const needsRatingThisMonth = !rating || rating.ratingPeriod !== currentPeriod;

        const profile = await getProfile(ctx, employee._id);
        return {
          employee: {
            ...employee,
            avatarUrl: profile?.avatarUrl ?? employee.avatarUrl ?? employee.faceImageUrl,
          },
          lastRated: rating?.ratingPeriod || 'Never',
          needsRating: needsRatingThisMonth,
        };
      }),
    );

    return needsRating.filter((item) => item.needsRating);
  },
});

import { v } from 'convex/values';
import { mutation, query, internalMutation } from './_generated/server';
import type { Id } from './_generated/dataModel';
import { MAX_PAGE_SIZE } from './pagination';
import { DEFAULT_LIST_CAP, SMALL_LIST_CAP } from './lib/limits';
import { getProfile } from './lib/userProfile';

// ─────────────────────────────────────────────────────────────────────────────
// QUERIES
// ─────────────────────────────────────────────────────────────────────────────

/**
 * List surveys for an organization, optionally filtered by status
 */
export const listSurveys = query({
  args: {
    organizationId: v.id('organizations'),
    status: v.optional(v.union(v.literal('draft'), v.literal('active'), v.literal('closed'))),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const { organizationId, status, limit } = args;
    const pageSize = Math.min(limit ?? 50, MAX_PAGE_SIZE);

    let surveyQuery;
    if (status) {
      surveyQuery = ctx.db
        .query('surveys')
        .withIndex('by_org_status', (q) =>
          q.eq('organizationId', organizationId).eq('status', status),
        );
    } else {
      surveyQuery = ctx.db
        .query('surveys')
        .withIndex('by_org_created', (q) => q.eq('organizationId', organizationId));
    }

    const surveys = await surveyQuery.order('desc').take(pageSize);

    // Batch load creators
    const creatorIds = [...new Set(surveys.map((s) => s.createdBy))];
    const creators = await Promise.all(creatorIds.map((id) => ctx.db.get(id)));
    const creatorMap = new Map(creators.filter(Boolean).map((u) => [u!._id, u!]));
    const creatorProfiles = await Promise.all(creatorIds.map((id) => getProfile(ctx, id)));
    const creatorProfileMap = new Map(creatorIds.map((id, i) => [id, creatorProfiles[i]]));

    return surveys.map((survey) => ({
      ...survey,
      creator: creatorMap.get(survey.createdBy)
        ? {
            name: creatorMap.get(survey.createdBy)!.name,
            avatarUrl:
              creatorProfileMap.get(survey.createdBy)?.avatarUrl ??
              creatorMap.get(survey.createdBy)?.avatarUrl,
          }
        : null,
    }));
  },
});

/**
 * Get a single survey with its questions
 */
export const getSurveyWithQuestions = query({
  args: {
    surveyId: v.id('surveys'),
  },
  handler: async (ctx, args) => {
    const { surveyId } = args;
    const survey = await ctx.db.get(surveyId);
    if (!survey) return null;

    const questions = await ctx.db
      .query('surveyQuestions')
      .withIndex('by_survey_order', (q) => q.eq('surveyId', surveyId))
      .take(DEFAULT_LIST_CAP);

    const creator = await ctx.db.get(survey.createdBy);
    const creatorProfile = await getProfile(ctx, survey.createdBy);

    return {
      ...survey,
      questions,
      creator: creator
        ? {
            name: creator.name,
            avatarUrl: creatorProfile?.avatarUrl ?? creator?.avatarUrl,
          }
        : null,
    };
  },
});

/**
 * Get survey results/analytics
 */
export const getSurveyResults = query({
  args: {
    surveyId: v.id('surveys'),
    organizationId: v.id('organizations'),
  },
  handler: async (ctx, args) => {
    const { surveyId, organizationId } = args;
    const survey = await ctx.db.get(surveyId);
    if (!survey || survey.organizationId !== organizationId) return null;

    const questions = await ctx.db
      .query('surveyQuestions')
      .withIndex('by_survey_order', (q) => q.eq('surveyId', surveyId))
      .take(DEFAULT_LIST_CAP);

    const responses = await ctx.db
      .query('surveyResponses')
      .withIndex('by_survey', (q) => q.eq('surveyId', surveyId))
      .take(DEFAULT_LIST_CAP);

    const answers = await ctx.db
      .query('surveyAnswers')
      .withIndex('by_survey', (q) => q.eq('surveyId', surveyId))
      .take(DEFAULT_LIST_CAP);

    // Aggregate answers per question
    const questionResults = questions.map((question) => {
      const questionAnswers = answers.filter((a) => a.questionId === question._id);

      const aggregation: any = { totalResponses: questionAnswers.length };

      switch (question.type) {
        case 'rating':
        case 'nps': {
          const values = questionAnswers
            .map((a) => a.ratingValue)
            .filter((v): v is number => v !== undefined);
          aggregation.average =
            values.length > 0 ? values.reduce((sum, v) => sum + v, 0) / values.length : 0;
          aggregation.distribution = values.reduce(
            (acc, val) => {
              acc[val] = (acc[val] || 0) + 1;
              return acc;
            },
            {} as Record<number, number>,
          );
          break;
        }
        case 'multiple_choice': {
          const optionCounts: Record<string, number> = {};
          questionAnswers.forEach((a) => {
            a.selectedOptions?.forEach((opt) => {
              optionCounts[opt] = (optionCounts[opt] || 0) + 1;
            });
          });
          aggregation.optionCounts = optionCounts;
          break;
        }
        case 'yes_no': {
          const yesCount = questionAnswers.filter((a) => a.booleanValue === true).length;
          const noCount = questionAnswers.filter((a) => a.booleanValue === false).length;
          aggregation.yesCount = yesCount;
          aggregation.noCount = noCount;
          break;
        }
        case 'text': {
          aggregation.textResponses = questionAnswers.map((a) => a.textValue).filter(Boolean);
          break;
        }
      }

      return {
        question,
        ...aggregation,
      };
    });

    return {
      survey,
      totalResponses: responses.length,
      questionResults,
    };
  },
});

/**
 * Check if user has already responded to a survey
 */
export const hasUserResponded = query({
  args: {
    surveyId: v.id('surveys'),
    userId: v.id('users'),
  },
  handler: async (ctx, args) => {
    const { surveyId, userId } = args;
    const existing = await ctx.db
      .query('surveyResponses')
      .withIndex('by_survey_respondent', (q) =>
        q.eq('surveyId', surveyId).eq('respondentId', userId),
      )
      .first();
    return !!existing;
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// MUTATIONS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a new survey (admin/supervisor only)
 */
export const createSurvey = mutation({
  args: {
    organizationId: v.id('organizations'),
    createdBy: v.id('users'),
    title: v.string(),
    description: v.optional(v.string()),
    isAnonymous: v.boolean(),
    targetRoles: v.optional(
      v.array(
        v.union(
          v.literal('admin'),
          v.literal('supervisor'),
          v.literal('employee'),
          v.literal('driver'),
        ),
      ),
    ),
    targetDepartments: v.optional(v.array(v.string())),
    startsAt: v.optional(v.number()),
    endsAt: v.optional(v.number()),
    questions: v.array(
      v.object({
        type: v.union(
          v.literal('rating'),
          v.literal('multiple_choice'),
          v.literal('text'),
          v.literal('yes_no'),
          v.literal('nps'),
        ),
        text: v.string(),
        description: v.optional(v.string()),
        options: v.optional(v.array(v.string())),
        isRequired: v.boolean(),
      }),
    ),
  },
  handler: async (ctx, args) => {
    const now = Date.now();

    const surveyId = await ctx.db.insert('surveys', {
      organizationId: args.organizationId,
      title: args.title,
      description: args.description,
      createdBy: args.createdBy,
      status: 'draft',
      isAnonymous: args.isAnonymous,
      targetRoles: args.targetRoles,
      targetDepartments: args.targetDepartments,
      startsAt: args.startsAt,
      endsAt: args.endsAt,
      responseCount: 0,
      createdAt: now,
      updatedAt: now,
    });

    // Create questions
    for (let i = 0; i < args.questions.length; i++) {
      const q = args.questions[i]!;
      await ctx.db.insert('surveyQuestions', {
        organizationId: args.organizationId,
        surveyId,
        type: q.type,
        text: q.text,
        description: q.description,
        options: q.options,
        isRequired: q.isRequired,
        order: i,
        createdAt: now,
      });
    }

    return surveyId;
  },
});

/**
 * Publish a survey (change status from draft to active)
 */
export const publishSurvey = mutation({
  args: {
    surveyId: v.id('surveys'),
    organizationId: v.id('organizations'),
  },
  handler: async (ctx, args) => {
    const { surveyId, organizationId } = args;
    const survey = await ctx.db.get(surveyId);
    if (!survey || survey.organizationId !== organizationId) {
      throw new Error('Survey not found');
    }
    if (survey.status !== 'draft') {
      throw new Error('Only draft surveys can be published');
    }

    await ctx.db.patch(surveyId, {
      status: 'active',
      startsAt: survey.startsAt ?? Date.now(),
      updatedAt: Date.now(),
    });
  },
});

/**
 * Close a survey
 */
export const closeSurvey = mutation({
  args: {
    surveyId: v.id('surveys'),
