// ── Get single task by ID ─────────────────────────────────────────────────
export const getTask = query({
  args: { taskId: v.id('tasks') },
  handler: async (ctx, args) => {
    const task = await ctx.db.get(args.taskId);
    if (!task) return null;

    // Load assigned user
    const assignedTo = await ctx.db.get(task.assignedTo);
    const assignedBy = await ctx.db.get(task.assignedBy);

    // Load profiles
    const assignedToProfile = assignedTo ? await getProfile(ctx, assignedTo._id) : null;
    const assignedByProfile = assignedBy ? await getProfile(ctx, assignedBy._id) : null;

    // Load comments
    const comments = await ctx.db
      .query('taskComments')
      .withIndex('by_task', (q) => q.eq('taskId', args.taskId))
      .take(DEFAULT_LIST_CAP);

    const commentAuthorIds = [...new Set(comments.map((c) => c.authorId))];
    const commentAuthors = await Promise.all(commentAuthorIds.map((id) => ctx.db.get(id)));
    const commentAuthorMap = new Map(commentAuthors.map((a) => [a?._id, a]));

    return {
      ...task,
      assignedToUser: assignedTo
        ? {
            ...assignedTo,
            department: assignedToProfile?.department ?? assignedTo.department,
            position: assignedToProfile?.position ?? assignedTo.position,
            avatarUrl:
              assignedToProfile?.avatarUrl ?? assignedTo.avatarUrl ?? assignedTo.faceImageUrl,
          }
        : null,
      assignedByUser: assignedBy
        ? {
            ...assignedBy,
            department: assignedByProfile?.department ?? assignedBy.department,
            position: assignedByProfile?.position ?? assignedBy.position,
            avatarUrl:
              assignedByProfile?.avatarUrl ?? assignedBy.avatarUrl ?? assignedBy.faceImageUrl,
          }
        : null,
      comments: comments.map((c) => ({
        ...c,
        author: commentAuthorMap.get(c.authorId),
      })),
      commentCount: comments.length,
    };
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// SECURED: DELETE TASK — verified identity via ctx.auth
// ─────────────────────────────────────────────────────────────────────────────
export const secureDeleteTask = mutation({
  args: { taskId: v.id('tasks') },
  handler: async (ctx, { taskId }) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) throw new Error('Not authenticated');
    const task = await ctx.db.get(taskId);
    if (!task) throw new Error('Task not found');

    // Cross-org protection
    if (caller.role !== 'superadmin' && caller.organizationId !== task.organizationId) {
      throw new Error('Access denied: cross-organization operation');
    }

    const comments = await ctx.db
      .query('taskComments')
      .withIndex('by_task', (q) => q.eq('taskId', taskId))
      .take(SMALL_LIST_CAP);
    for (const c of comments) await ctx.db.delete(c._id);
    await ctx.db.delete(taskId);

    await ctx.db.insert('auditLogs', {
      organizationId: task.organizationId,
      userId: caller._id,
      action: 'task_deleted',
      target: taskId,
      details: JSON.stringify({ title: task.title }),
      createdAt: Date.now(),
    });
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// SECURED: REASSIGN TASK — verified identity via ctx.auth
// ─────────────────────────────────────────────────────────────────────────────
export const secureReassignTask = mutation({
  args: { taskId: v.id('tasks'), newAssigneeId: v.id('users') },
  handler: async (ctx, { taskId, newAssigneeId }) => {
    const caller = await getAuthCaller(ctx);
    if (!caller) throw new Error('Not authenticated');
    const task = await ctx.db.get(taskId);
    if (!task) throw new Error('Task not found');

    if (caller.role !== 'superadmin' && caller.organizationId !== task.organizationId) {
      throw new Error('Access denied: cross-organization operation');
    }

    await ctx.db.patch(taskId, { assignedTo: newAssigneeId, updatedAt: Date.now() });

    await ctx.db.insert('notifications', {
      organizationId: task.organizationId,
      userId: newAssigneeId,
      type: 'system',
      title: '📋 Task Assigned',
      message: `${caller.name} assigned you: "${task.title}"`,
      isRead: false,
      relatedId: taskId,
      route: '/tasks',
      createdAt: Date.now(),
    });

    await ctx.db.insert('auditLogs', {
      organizationId: task.organizationId,
      userId: caller._id,
      action: 'task_reassigned',
      target: taskId,
      details: JSON.stringify({ title: task.title, newAssigneeId }),
      createdAt: Date.now(),
    });
  },
});

/**
 * 🎫 SUPPORT TICKETS - Unified ticket system for superadmin
 * Create, manage, and resolve support tickets across all organizations
 */

import { v } from 'convex/values';
import { query, mutation } from './_generated/server';
import { Id } from './_generated/dataModel';
import { getTranslation, getUserLocale } from './translations';
import { DEFAULT_LIST_CAP, SMALL_LIST_CAP, XLARGE_LIST_CAP } from './lib/limits';
import { getProfile } from './lib/userProfile';
import { logger } from '../src/lib/logger';

// ─── CREATE TICKET ───────────────────────────────────────────────────────────
export const createTicket = mutation({
  args: {
    organizationId: v.optional(v.id('organizations')),
    createdBy: v.id('users'),
    title: v.string(),
    description: v.string(),
    priority: v.union(
      v.literal('low'),
      v.literal('medium'),
      v.literal('high'),
      v.literal('critical'),
    ),
    category: v.union(
      v.literal('technical'),
      v.literal('billing'),
      v.literal('access'),
      v.literal('feature_request'),
      v.literal('bug'),
      v.literal('other'),
    ),
    relatedLeaveId: v.optional(v.id('leaveRequests')),
    relatedDriverRequestId: v.optional(v.id('driverRequests')),
    relatedTaskId: v.optional(v.id('tasks')),
  },
  handler: async (ctx, args) => {
    const now = Date.now();

    // Generate ticket number: SUP-YYYYMMDD-XXXX
    const datePart = (new Date(now).toISOString().split('T')[0] || '').replace(/-/g, '');
    const ticketsToday = await ctx.db
      .query('supportTickets')
      .withIndex('by_created')
      .filter((q) => q.gte(q.field('createdAt'), new Date(datePart).getTime()))
      .take(SMALL_LIST_CAP);
    const seqNum = String(ticketsToday.length + 1).padStart(4, '0');
    const ticketNumber = `SUP-${datePart}-${seqNum}`;

    // Calculate SLA deadline based on priority
    const slaHours = {
      critical: 4,
      high: 12,
      medium: 24,
      low: 48,
    };
    const slaDeadline = now + slaHours[args.priority as keyof typeof slaHours] * 60 * 60 * 1000;

    const ticketId = await ctx.db.insert('supportTickets', {
      organizationId: args.organizationId,
      ticketNumber,
      title: args.title,
      description: args.description,
      priority: args.priority,
      status: 'open',
      category: args.category,
      createdBy: args.createdBy,
      assignedTo: undefined,
      relatedLeaveId: args.relatedLeaveId,
      relatedDriverRequestId: args.relatedDriverRequestId,
      relatedTaskId: args.relatedTaskId,
      slaDeadline,
      firstResponseAt: undefined,
      resolution: undefined,
      resolvedAt: undefined,
      resolvedBy: undefined,
      closedAt: undefined,
      createdAt: now,
      updatedAt: now,
    });

    // Create initial comment from description
    await ctx.db.insert('ticketComments', {
      ticketId,
      organizationId: args.organizationId,
      authorId: args.createdBy,
      message: args.description,
      isInternal: false,
      createdAt: now,
      updatedAt: now,
    });

    // Notify superadmins
    const superadmins = await ctx.db
      .query('users')
      .withIndex('by_role', (q) => q.eq('role', 'superadmin'))
      .take(SMALL_LIST_CAP);

    for (const admin of superadmins) {
      await ctx.db.insert('notifications', {
        organizationId: args.organizationId,
        userId: admin._id,
        type: 'system',
        title: `🎫 Новый тикет: ${ticketNumber}`,
        message: `${args.title} (Приоритет: ${args.priority})`,
        isRead: false,
        relatedId: `support_ticket:${ticketId}`,
        route: '/tickets',
        createdAt: now,
      });
    }

    // Audit log: ticket created
    await ctx.db.insert('auditLogs', {
      organizationId: args.organizationId,
      userId: args.createdBy,
      action: 'ticket_created',
      target: ticketId,
      details: JSON.stringify({
        ticketNumber,
        title: args.title,
        priority: args.priority,
        category: args.category,
      }),
      createdAt: now,
    });

    return { ticketId, ticketNumber };
  },
});

// ─── GET ALL TICKETS ─────────────────────────────────────────────────────────
export const getAllTickets = query({
  args: {
    status: v.optional(
      v.union(
        v.literal('open'),
        v.literal('in_progress'),
        v.literal('waiting_customer'),
        v.literal('resolved'),
        v.literal('closed'),
      ),
    ),
    priority: v.optional(
      v.union(v.literal('low'), v.literal('medium'), v.literal('high'), v.literal('critical')),
    ),
    organizationId: v.optional(v.id('organizations')),
    assignedTo: v.optional(v.id('users')),
    limit: v.optional(v.number()),
    cursor: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    // Superadmin cross-tenant view — capped at XLARGE.
    let tickets = await ctx.db.query('supportTickets').take(XLARGE_LIST_CAP);

    // Apply filters
    if (args.status) {
      tickets = tickets.filter((t) => t.status === args.status);
    }
    if (args.priority) {
      tickets = tickets.filter((t) => t.priority === args.priority);
    }
    if (args.organizationId) {
      tickets = tickets.filter((t) => t.organizationId === args.organizationId);
    }
    if (args.assignedTo) {
      tickets = tickets.filter((t) => t.assignedTo === args.assignedTo);
    }

    // Sort by priority (critical first) then by createdAt (newest first)
    const priorityOrder: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
    tickets.sort((a, b) => {
      const priorityDiff = (priorityOrder[a.priority] ?? 4) - (priorityOrder[b.priority] ?? 4);
      if (priorityDiff !== 0) return priorityDiff;
      return b.createdAt - a.createdAt;
    });

    // Apply limit and cursor for pagination
    if (args.cursor) {
      tickets = tickets.slice(args.cursor);
    }
    if (args.limit) {
      tickets = tickets.slice(0, args.limit);
    }

    // Enrich with user data
    const enrichedTickets = await Promise.all(
      tickets.map(async (ticket) => {
        const creator = await ctx.db.get(ticket.createdBy);
        const assignee = ticket.assignedTo ? await ctx.db.get(ticket.assignedTo) : null;
        const org = ticket.organizationId ? await ctx.db.get(ticket.organizationId) : null;
        const creatorProfile = await getProfile(ctx, ticket.createdBy);
        const assigneeProfile = ticket.assignedTo ? await getProfile(ctx, ticket.assignedTo) : null;

        // Count comments
        const comments = await ctx.db
          .query('ticketComments')
          .withIndex('by_ticket', (q) => q.eq('ticketId', ticket._id))
          .take(DEFAULT_LIST_CAP);

        return {
          ...ticket,
          creatorName: creator?.name || 'Unknown',
          creatorEmail: creator?.email || '',
          creatorAvatar: creatorProfile?.avatarUrl ?? creator?.avatarUrl,
          assigneeName: assignee?.name || null,
          assigneeAvatar: assigneeProfile?.avatarUrl ?? assignee?.avatarUrl,
          organizationName: org?.name || null,
          commentCount: comments.length,
          isOverdue:
            ticket.status !== 'closed' && ticket.slaDeadline && Date.now() > ticket.slaDeadline,
        };
      }),
    );

    return enrichedTickets;
  },
});

// ─── GET TICKET BY ID ────────────────────────────────────────────────────────
export const getTicketById = query({
  args: { ticketId: v.id('supportTickets') },
